async function inspectAgentOsMemoryEvalAssets(workspaceRoot) {
  const reportRoot = resolveAgentOsBenchmarkReportRoot(workspaceRoot);
  const reportPath = join(
    reportRoot,
    "benchmarks",
    "results",
    "director-agent-os-mempalace-real-eval-fixture-gate-latest.json",
  );
  const report = await readJsonOrNull(reportPath);
  return normalizeAgentOsMemoryEvalReport(report, { reportPath });
}

function resolveAgentOsBenchmarkReportRoot(workspaceRoot) {
  return basename(workspaceRoot) === ".director-angel" ? dirname(workspaceRoot) : workspaceRoot;
}

function normalizeAgentOsMemoryEvalReport(report, { reportPath }) {
  const fallback = {
    schemaVersion: "director.desktop.agent-os-memory-eval.v1",
    suiteId: "director-agent-os-mempalace-real-eval-fixture-gate",
    status: "missing",
    reportPath,
    generatedAt: null,
    fixturePath: null,
    source: {
      name: "local-mini-locomem-style-fixture",
      dataset: "local-fixture",
      version: null,
      localOnly: true,
    },
    summary: {
      qualityCaseCount: 0,
      diagnosticCaseCount: 0,
      failed: 0,
    },
    thresholds: {
      recallAtK: 0.8,
      recallAnyAtK: 1,
      ndcgAtK: 0.75,
      requireVerbatimEvidence: true,
      requireProvenanceEvidence: true,
    },
    qualityAverages: {
      recallAtK: 0,
      recallAnyAtK: 0,
      recallAllAtK: 0,
      ndcgAtK: 0,
    },
    diagnosticStatus: "missing",
    diagnosticFailures: [],
    diagnosticCases: [],
    issues: [],
  };

  if (report === null) {
    return fallback;
  }
  if (typeof report?.readError === "string") {
    return {
      ...fallback,
      status: "degraded",
      diagnosticStatus: "degraded",
      issues: [`Agent OS memory eval report could not be read: ${report.readError}.`],
    };
  }
  if (!isPlainObject(report) || report.suiteId !== fallback.suiteId) {
    return {
      ...fallback,
      status: "degraded",
      diagnosticStatus: "degraded",
      issues: ["Agent OS memory eval report has an unsupported schema."],
    };
  }

  const summary = isPlainObject(report.summary) ? report.summary : {};
  const thresholds = isPlainObject(summary.thresholds)
    ? summary.thresholds
    : isPlainObject(report.qualityThresholds?.thresholds)
      ? report.qualityThresholds.thresholds
      : {};
  const qualityAverages = isPlainObject(summary.qualityAverages)
    ? summary.qualityAverages
    : isPlainObject(report.qualityReport?.summary?.averages)
      ? report.qualityReport.summary.averages
      : {};
  const source = isPlainObject(report.source) ? report.source : {};
  const diagnosticThresholds = isPlainObject(report.diagnosticThresholds)
    ? report.diagnosticThresholds
    : {};
  const diagnosticResults = Array.isArray(report.diagnosticReport?.results)
    ? report.diagnosticReport.results
    : [];
  const diagnosticFailures = [
    ...(Array.isArray(diagnosticThresholds.failures) ? diagnosticThresholds.failures : []),
    ...(Array.isArray(report.diagnosticReport?.failures) ? report.diagnosticReport.failures : []),
  ].map(normalizeAgentOsMemoryEvalDiagnosticFailure);

  return {
    schemaVersion: "director.desktop.agent-os-memory-eval.v1",
    suiteId: report.suiteId,
    status: typeof summary.status === "string" ? summary.status : "unknown",
    reportPath,
    generatedAt: typeof report.generatedAt === "string" ? report.generatedAt : null,
    fixturePath: typeof report.fixturePath === "string" ? report.fixturePath : null,
    source: {
      name: typeof source.name === "string" ? source.name : fallback.source.name,
      dataset: typeof source.dataset === "string" ? source.dataset : fallback.source.dataset,
      version: typeof source.version === "string" ? source.version : null,
      localOnly: source.localOnly === true,
    },
    summary: {
      qualityCaseCount: readFiniteNumber(summary.qualityCaseCount) ?? 0,
      diagnosticCaseCount: readFiniteNumber(summary.diagnosticCaseCount) ?? 0,
      failed: readFiniteNumber(summary.failed) ?? 0,
    },
    thresholds: {
      recallAtK: readFiniteNumber(thresholds.recallAtK) ?? fallback.thresholds.recallAtK,
      recallAnyAtK:
        readFiniteNumber(thresholds.recallAnyAtK) ?? fallback.thresholds.recallAnyAtK,
      ndcgAtK: readFiniteNumber(thresholds.ndcgAtK) ?? fallback.thresholds.ndcgAtK,
      requireVerbatimEvidence:
        thresholds.requireVerbatimEvidence === undefined
          ? fallback.thresholds.requireVerbatimEvidence
          : thresholds.requireVerbatimEvidence === true,
      requireProvenanceEvidence:
        thresholds.requireProvenanceEvidence === undefined
          ? fallback.thresholds.requireProvenanceEvidence
          : thresholds.requireProvenanceEvidence === true,
    },
    qualityAverages: {
      recallAtK: readFiniteNumber(qualityAverages.recallAtK) ?? 0,
      recallAnyAtK: readFiniteNumber(qualityAverages.recallAnyAtK) ?? 0,
      recallAllAtK: readFiniteNumber(qualityAverages.recallAllAtK) ?? 0,
      ndcgAtK: readFiniteNumber(qualityAverages.ndcgAtK) ?? 0,
    },
    diagnosticStatus:
      typeof diagnosticThresholds.status === "string" ? diagnosticThresholds.status : "unknown",
    diagnosticFailures,
    diagnosticCases: diagnosticResults.map(normalizeAgentOsMemoryEvalDiagnosticCase),
    issues: [],
  };
}

function normalizeAgentOsMemoryEvalDiagnosticFailure(failure) {
  if (typeof failure === "string") {
    return {
      queryId: null,
      detail: failure,
      missingExpectedIds: [],
    };
  }
  const missingExpectedIds = Array.isArray(failure?.missingExpectedIds)
    ? failure.missingExpectedIds.filter((id) => typeof id === "string")
    : [];
  return {
    queryId: typeof failure?.queryId === "string" ? failure.queryId : null,
    detail:
      missingExpectedIds.length > 0
        ? `missing expected IDs: ${missingExpectedIds.join(", ")}`
        : "diagnostic failure",
    missingExpectedIds,
  };
}

function normalizeAgentOsMemoryEvalDiagnosticCase(result) {
  return {
    queryId: typeof result?.queryId === "string" ? result.queryId : "unknown",
    recallAtK: readFiniteNumber(result?.recallAtK) ?? 0,
    recallAnyAtK: readFiniteNumber(result?.recallAnyAtK) ?? 0,
    ndcgAtK: readFiniteNumber(result?.ndcgAtK) ?? 0,
    missingExpectedIds: Array.isArray(result?.missingExpectedIds)
      ? result.missingExpectedIds.filter((id) => typeof id === "string")
      : [],
    retrievedIdsAtK: Array.isArray(result?.retrievedIdsAtK)
      ? result.retrievedIdsAtK.filter((id) => typeof id === "string")
      : [],
  };
}

function createAgentOsMemoryEvalDashboardAssets(agentOsMemoryEval, agentOsMemorySweepSafety) {
  const memoryEval =
    agentOsMemoryEval?.schemaVersion === "director.desktop.agent-os-memory-eval.v1"
      ? agentOsMemoryEval
      : normalizeAgentOsMemoryEvalReport(agentOsMemoryEval ?? null, {
          reportPath: agentOsMemoryEval?.reportPath ?? "derived",
        });
  const memorySweepSafety = normalizeAgentOsMemorySweepSafetyReport(agentOsMemorySweepSafety ?? null);
  return normalizeAgentOsMemoryEvalDashboardReport({
    schemaVersion: "director.desktop.agent-os-memory-eval-dashboard.v1",
    status:
      memoryEval.status === "passed" && memorySweepSafety.summary.canReadUserDataCount === 0
        ? "ready"
        : memoryEval.status,
    localOnly: true,
    canReadUserData: false,
    generatedAt: memoryEval.generatedAt,
    source: {
      memoryEvalStatus: memoryEval.status,
      memoryEvalReportPath: memoryEval.reportPath,
      memoryEvalSuiteId: memoryEval.suiteId,
      sweepSafetyStatus: memorySweepSafety.status,
      datasetLoaderGate: "bench:director-agent-os-memory-dataset-loader-anonymization",
    },
    memoryEvalTrend: createAgentOsMemoryEvalTrend(memoryEval),
    maintenanceDueActions: createAgentOsMemoryMaintenanceDueActions(
      memoryEval,
      memorySweepSafety,
    ),
    issues: [...(memoryEval.issues ?? []), ...(memorySweepSafety.issues ?? [])],
  });
}

function createAgentOsMemoryEvalTrend(memoryEval) {
  return [
    createAgentOsMemoryEvalTrendPoint({
      id: "local-fixture-recall",
      label: "local fixture recall@k",
      metric: "recall@k",
      current: memoryEval.qualityAverages?.recallAtK,
      threshold: memoryEval.thresholds?.recallAtK,
      source: memoryEval.source?.name,
    }),
    createAgentOsMemoryEvalTrendPoint({
      id: "local-fixture-ndcg",
      label: "local fixture ndcg@k",
      metric: "ndcg@k",
      current: memoryEval.qualityAverages?.ndcgAtK,
      threshold: memoryEval.thresholds?.ndcgAtK,
      source: memoryEval.source?.name,
    }),
  ];
}

function createAgentOsMemoryEvalTrendPoint(input) {
  const current = readFiniteNumber(input.current) ?? 0;
  const threshold = readFiniteNumber(input.threshold) ?? 0;
  return {
    id: input.id,
    label: input.label,
    metric: input.metric,
    current,
    threshold,
    status: current >= threshold ? "passed" : "attention",
    source: typeof input.source === "string" ? input.source : "local fixture",
    localOnly: true,
    canReadUserData: false,
  };
}

function createAgentOsMemoryMaintenanceDueActions(memoryEval, memorySweepSafety) {
  const recallAtK = readFiniteNumber(memoryEval.qualityAverages?.recallAtK) ?? 0;
  const recallThreshold = readFiniteNumber(memoryEval.thresholds?.recallAtK) ?? 0.8;
  const ndcgAtK = readFiniteNumber(memoryEval.qualityAverages?.ndcgAtK) ?? 0;
  const ndcgThreshold = readFiniteNumber(memoryEval.thresholds?.ndcgAtK) ?? 0.75;
  const liveUserMemoryPlan = (memorySweepSafety.plans ?? []).find(
    (plan) => plan.safetyEnvelope?.sourceKind === "live-user-memory",
  );

  return [
    {
      id: "recall-degradation-watch",
      kind: "maintenance-due",
      status:
        memoryEval.status !== "passed" || recallAtK < recallThreshold || ndcgAtK < ndcgThreshold
          ? "due"
          : "watch",
      title: "recall degradation watch",
      reason:
        memoryEval.status === "missing"
          ? "local fixture recall report is missing; rerun the MemPalace real-eval fixture gate before trusting recall trend."
          : "watch recall@k and ndcg@k drift against the local-only fixture thresholds before expanding dataset coverage.",
      canReadUserData: false,
      localOnly: true,
      nextRecommendedCommand: "pnpm --dir benchmarks bench:director-agent-os-mempalace-real-eval",
    },
    {
      id: "dataset-loader-gate",
      kind: "maintenance-due",
      status: "ready",
      title: "dataset loader gate",
      reason:
        "rerun the approved public-benchmark dataset loader anonymization gate after memory fixture schema or anonymization policy changes.",
      canReadUserData: false,
      localOnly: true,
      nextRecommendedCommand:
        "pnpm --dir benchmarks bench:director-agent-os-memory-dataset-loader-anonymization",
    },
    {
      id: "live-user-memory-sweep-safety",
      kind: "maintenance-due",
      status: liveUserMemoryPlan?.status === "ready" ? "watch" : "blocked",
      title: "live user memory sweep safety",
      reason:
        liveUserMemoryPlan?.status === "ready"
          ? "live-user-memory sweep is still operator-gated; keep it dry-run, read-only, anonymized, and network-disabled."
          : "live-user-memory sweep remains blocked until approval, anonymization, retention, dry-run, read-only, and network-disabled requirements are satisfied.",
      canReadUserData: false,
      localOnly: true,
      nextRecommendedCommand: "pnpm --dir benchmarks bench:director-agent-os-memory-sweep-safety",
    },
  ];
}

function normalizeAgentOsMemoryEvalDashboardReport(report) {
  const memoryEvalTrend = Array.isArray(report?.memoryEvalTrend)
    ? report.memoryEvalTrend.map(normalizeAgentOsMemoryEvalDashboardTrendPoint)
    : [];
  const maintenanceDueActions = Array.isArray(report?.maintenanceDueActions)
    ? report.maintenanceDueActions.map(normalizeAgentOsMemoryEvalDashboardMaintenanceAction)
    : [];
  const source = isPlainObject(report?.source) ? report.source : {};
  return {
    schemaVersion: "director.desktop.agent-os-memory-eval-dashboard.v1",
    status: typeof report?.status === "string" ? report.status : "missing",
    localOnly: true,
    canReadUserData: false,
    generatedAt: typeof report?.generatedAt === "string" ? report.generatedAt : null,
    source: {
      memoryEvalStatus:
        typeof source.memoryEvalStatus === "string" ? source.memoryEvalStatus : "missing",
      memoryEvalReportPath:
        typeof source.memoryEvalReportPath === "string" ? source.memoryEvalReportPath : null,
      memoryEvalSuiteId:
        typeof source.memoryEvalSuiteId === "string"
          ? source.memoryEvalSuiteId
          : "director-agent-os-mempalace-real-eval-fixture-gate",
      sweepSafetyStatus:
        typeof source.sweepSafetyStatus === "string" ? source.sweepSafetyStatus : "blocked",
      datasetLoaderGate:
        typeof source.datasetLoaderGate === "string"
          ? source.datasetLoaderGate
          : "bench:director-agent-os-memory-dataset-loader-anonymization",
    },
    memoryEvalTrend,
    maintenanceDueActions,
    issues: Array.isArray(report?.issues)
      ? report.issues.filter((issue) => typeof issue === "string")
      : [],
  };
}

function normalizeAgentOsMemoryEvalDashboardTrendPoint(point) {
  const current = readFiniteNumber(point?.current) ?? 0;
  const threshold = readFiniteNumber(point?.threshold) ?? 0;
  return {
    id: typeof point?.id === "string" ? point.id : "unknown-memory-eval-trend",
    label: typeof point?.label === "string" ? point.label : "memory eval trend",
    metric: typeof point?.metric === "string" ? point.metric : "unknown",
    current,
    threshold,
    status:
      typeof point?.status === "string"
        ? point.status
        : current >= threshold
          ? "passed"
          : "attention",
    source: typeof point?.source === "string" ? point.source : "local fixture",
    localOnly: true,
    canReadUserData: false,
  };
}

function normalizeAgentOsMemoryEvalDashboardMaintenanceAction(action) {
  return {
    id: typeof action?.id === "string" ? action.id : "unknown-maintenance-action",
    kind: "maintenance-due",
    status: typeof action?.status === "string" ? action.status : "due",
    title: typeof action?.title === "string" ? action.title : "memory eval maintenance",
    reason: typeof action?.reason === "string" ? action.reason : "maintenance action needs review.",
    canReadUserData: false,
    localOnly: true,
    nextRecommendedCommand:
      typeof action?.nextRecommendedCommand === "string"
        ? action.nextRecommendedCommand
        : "pnpm --dir benchmarks bench:director-agent-os-memory-dataset-loader-anonymization",
  };
}

function createAgentOsMemorySweepSafetyAssets() {
  return normalizeAgentOsMemorySweepSafetyReport({
    schemaVersion: "director.desktop.agent-os-memory-sweep-safety.v1",
    status: "blocked",
    plans: [
      planMempalaceLiveMemoryEvalSweep({
        sweepId: "live-user-memory-sweep",
        dataset: {
          datasetId: "live-user-memory",
          sourceKind: "live-user-memory",
          localOnly: false,
          containsUserContent: true,
          estimatedCaseCount: 25,
        },
        approval: {
          operatorApproved: false,
          scope: "live-user-memory-eval",
        },
        anonymization: {
          enabled: false,
          strategy: "none",
        },
        retention: {
          reportTtlDays: 120,
          storeRawContent: true,
          deleteRawContentAfterEval: false,
        },
        execution: {
          dryRunOnly: false,
          allowNetwork: true,
          readOnly: false,
        },
      }),
      planMempalaceLiveMemoryEvalSweep({
        sweepId: "local-fixture-sweep",
        dataset: {
          datasetId: "local-mini-fixture",
          sourceKind: "local-fixture",
          localOnly: true,
          containsUserContent: false,
          estimatedCaseCount: 3,
        },
        approval: {
          operatorApproved: false,
        },
        anonymization: {
          enabled: true,
          strategy: "fixture-redacted",
          irreversible: true,
          removesDirectIdentifiers: true,
        },
        retention: {
          reportTtlDays: 30,
          storeRawContent: false,
          deleteRawContentAfterEval: true,
        },
        execution: {
          dryRunOnly: true,
          allowNetwork: false,
          readOnly: true,
        },
      }),
    ],
    issues: [],
  });
}

function planMempalaceLiveMemoryEvalSweep(input) {
  const reasonCodes = [
    ...validateMemorySweepApproval(input.dataset, input.approval),
    ...validateMemorySweepAnonymization(input.dataset, input.anonymization),
    ...validateMemorySweepRetention(input.retention),
    ...validateMemorySweepExecution(input.execution),
  ];
  const uniqueReasonCodes = [...new Set(reasonCodes)];
  return {
    schemaVersion: "hotflow.mempalace.live-memory-eval-safety.v1",
    sweepId: input.sweepId,
    status: uniqueReasonCodes.length === 0 ? "ready" : "blocked",
    readyToRun: uniqueReasonCodes.length === 0,
    canReadUserData: false,
    reasonCodes: uniqueReasonCodes,
    operatorChecklist: [
      `dataset ${input.dataset.datasetId} source=${input.dataset.sourceKind}`,
      "operator approval: required before any live user-memory eval sweep",
      "anonymization: irreversible direct identifier removal before evaluation",
      "retention: no raw content storage and report TTL <= 30 days",
      "execution: dry-run, read-only, network disabled until a separate live runner is approved",
    ],
    safetyEnvelope: {
      sourceKind: input.dataset.sourceKind,
      localOnly: input.dataset.localOnly === true,
      dryRunOnly: input.execution.dryRunOnly === true,
      allowNetwork: input.execution.allowNetwork === true,
      readOnly: input.execution.readOnly === true,
      storeRawContent: input.retention.storeRawContent === true,
      reportTtlDays: input.retention.reportTtlDays,
      anonymizationStrategy: input.anonymization.strategy,
      approvalScope: input.approval.scope,
    },
  };
}

function validateMemorySweepApproval(dataset, approval) {
  if (dataset.sourceKind === "local-fixture" && dataset.containsUserContent !== true) {
    return [];
  }
  const reasons = [];
  if (approval.operatorApproved !== true) {
    reasons.push("operator-approval-required");
  }
  if (approval.operatorApproved === true && approval.scope !== "live-user-memory-eval") {
    reasons.push("approval-scope-insufficient");
  }
  return reasons;
}

function validateMemorySweepAnonymization(dataset, anonymization) {
  if (dataset.sourceKind === "local-fixture" && dataset.containsUserContent !== true) {
    return [];
  }
  const reasons = [];
  if (anonymization.enabled !== true || anonymization.strategy === "none") {
    reasons.push("anonymization-required");
  }
  if (anonymization.irreversible !== true) {
    reasons.push("irreversible-anonymization-required");
  }
  if (anonymization.removesDirectIdentifiers !== true) {
    reasons.push("direct-identifier-redaction-required");
  }
  return reasons;
}

function validateMemorySweepRetention(retention) {
  const reasons = [];
  if (retention.storeRawContent === true) {
    reasons.push("raw-content-storage-forbidden");
  }
  if (retention.deleteRawContentAfterEval !== true) {
    reasons.push("delete-raw-content-after-eval-required");
  }
  if (!Number.isFinite(retention.reportTtlDays) || retention.reportTtlDays > 30) {
    reasons.push("retention-ttl-too-long");
  }
  return reasons;
}

function validateMemorySweepExecution(execution) {
  const reasons = [];
  if (execution.dryRunOnly !== true) {
    reasons.push("dry-run-required");
  }
  if (execution.allowNetwork === true) {
    reasons.push("network-disabled-required");
  }
  if (execution.readOnly !== true) {
    reasons.push("readonly-required");
  }
  return reasons;
}

function normalizeAgentOsMemorySweepSafetyReport(report) {
  const plans = Array.isArray(report?.plans)
    ? report.plans.map(normalizeAgentOsMemorySweepSafetyPlan)
    : [];
  const blockedPlans = plans.filter((plan) => plan.status === "blocked");
  const readyPlans = plans.filter((plan) => plan.status === "ready");
  return {
    schemaVersion: "director.desktop.agent-os-memory-sweep-safety.v1",
    status:
      typeof report?.status === "string"
        ? report.status
        : blockedPlans.length > 0
          ? "blocked"
          : "ready",
    summary: {
      planCount: plans.length,
      blockedCount: blockedPlans.length,
      readyCount: readyPlans.length,
      canReadUserDataCount: plans.filter((plan) => plan.canReadUserData === true).length,
    },
    plans,
    issues: Array.isArray(report?.issues)
      ? report.issues.filter((issue) => typeof issue === "string")
      : [],
  };
}

function normalizeAgentOsMemorySweepSafetyPlan(plan) {
  const reasonCodes = Array.isArray(plan?.reasonCodes)
    ? plan.reasonCodes.filter((reason) => typeof reason === "string")
    : [];
  const safetyEnvelope = isPlainObject(plan?.safetyEnvelope) ? plan.safetyEnvelope : {};
  return {
    schemaVersion: "hotflow.mempalace.live-memory-eval-safety.v1",
    sweepId: typeof plan?.sweepId === "string" ? plan.sweepId : "unknown",
    status: typeof plan?.status === "string" ? plan.status : "blocked",
    readyToRun: plan?.readyToRun === true,
    canReadUserData: plan?.canReadUserData === true,
    reasonCodes,
    operatorChecklist: Array.isArray(plan?.operatorChecklist)
      ? plan.operatorChecklist.filter((item) => typeof item === "string")
      : [],
    safetyEnvelope: {
      sourceKind:
        typeof safetyEnvelope.sourceKind === "string" ? safetyEnvelope.sourceKind : "unknown",
      localOnly: safetyEnvelope.localOnly === true,
      dryRunOnly: safetyEnvelope.dryRunOnly === true,
      allowNetwork: safetyEnvelope.allowNetwork === true,
      readOnly: safetyEnvelope.readOnly === true,
      storeRawContent: safetyEnvelope.storeRawContent === true,
      reportTtlDays: readFiniteNumber(safetyEnvelope.reportTtlDays) ?? null,
      anonymizationStrategy:
        typeof safetyEnvelope.anonymizationStrategy === "string"
          ? safetyEnvelope.anonymizationStrategy
          : "unknown",
      approvalScope:
        typeof safetyEnvelope.approvalScope === "string" ? safetyEnvelope.approvalScope : null,
    },
  };
}

async function inspectHeartbeatAssets(workspace) {
  const heartbeatRoot = join(workspace.root, "heartbeat");
  const latestPath = join(heartbeatRoot, "latest.json");
  const latest = await readJsonOrNull(latestPath);
  if (latest === null) {
    return {
      heartbeatRoot,
      heartbeatStatus: "empty",
      heartbeatLatestPath: latestPath,
      heartbeatLatest: null,
      heartbeatEventCount: 0,
      heartbeatAttentionCount: 0,
      heartbeatHighestSeverity: "none",
      heartbeatItems: [],
      heartbeatNotes: [],
      heartbeatIssues: [],
    };
  }
  if (typeof latest.readError === "string") {
    return {
      heartbeatRoot,
      heartbeatStatus: "degraded",
      heartbeatLatestPath: latestPath,
      heartbeatLatest: null,
      heartbeatEventCount: 0,
      heartbeatAttentionCount: 1,
      heartbeatHighestSeverity: "blocked",
      heartbeatItems: [],
      heartbeatNotes: [],
      heartbeatIssues: [`Heartbeat latest could not be read: ${latest.readError}.`],
    };
  }
  if (latest.schemaVersion !== "director.heartbeat.snapshot.v1") {
    return {
      heartbeatRoot,
      heartbeatStatus: "degraded",
      heartbeatLatestPath: latestPath,
      heartbeatLatest: null,
      heartbeatEventCount: 0,
      heartbeatAttentionCount: 1,
      heartbeatHighestSeverity: "blocked",
      heartbeatItems: [],
      heartbeatNotes: [],
      heartbeatIssues: ["Heartbeat latest has an unsupported schema."],
    };
  }

  const heartbeatItems = Array.isArray(latest.events)
    ? latest.events.filter(isHeartbeatEventRecord).map(formatHeartbeatEventAsset)
    : [];
  return {
    heartbeatRoot,
    heartbeatStatus: "ok",
    heartbeatLatestPath: latestPath,
    heartbeatLatest: {
      snapshotId: latest.snapshotId,
      enabled: latest.enabled === true,
      createdAt: latest.createdAt,
      eventCount: readFiniteNumber(latest.eventCount) ?? heartbeatItems.length,
      highestSeverity: latest.highestSeverity ?? "none",
    },
    heartbeatEventCount: readFiniteNumber(latest.eventCount) ?? heartbeatItems.length,
    heartbeatAttentionCount: heartbeatItems.length,
    heartbeatHighestSeverity: latest.highestSeverity ?? "none",
    heartbeatItems,
    heartbeatNotes: Array.isArray(latest.notes)
      ? latest.notes.filter((note) => typeof note === "string")
      : [],
    heartbeatIssues: [],
  };
}

function isHeartbeatEventRecord(value) {
  return (
    isPlainObject(value) &&
    value.schemaVersion === "director.heartbeat.event.v1" &&
    typeof value.eventId === "string" &&
    typeof value.kind === "string" &&
    typeof value.severity === "string"
  );
}

function formatHeartbeatEventAsset(event) {
  const actionRefs = Array.isArray(event.actionRefs)
    ? event.actionRefs.filter((ref) => typeof ref === "string")
    : [];
  const evidenceRefs = Array.isArray(event.evidenceRefs)
    ? event.evidenceRefs.filter((ref) => typeof ref === "string")
    : [];
  return {
    eventId: event.eventId,
    kind: event.kind,
    severity: event.severity,
    summary: typeof event.summary === "string" ? event.summary : "",
    actionRefs,
    evidenceRefs,
    target: deriveHeartbeatEventTarget(evidenceRefs),
    createdAt: typeof event.createdAt === "string" ? event.createdAt : null,
  };
}

function deriveHeartbeatEventTarget(evidenceRefs) {
  for (const ref of evidenceRefs) {
    if (!ref.startsWith("learning-governance://")) {
      continue;
    }
    let match = /^learning-governance:\/\/([^/]+)\/count\/(\d+)$/u.exec(ref);
    if (match) {
      return {
        kind: "learning-governance",
        reason: match[1],
        count: readFiniteNumber(Number(match[2])),
      };
    }
    match = /^learning-governance:\/\/([^/]+)\/(.+)$/u.exec(ref);
    if (match) {
      return { kind: "learning-governance", reason: match[1], sampleId: match[2] };
    }
  }
  for (const ref of evidenceRefs) {
    let match = /^director-run:\/\/([^/]+)\/report\/([^/]+)$/u.exec(ref);
    if (match) {
      return { kind: "run-report", runId: match[1], reportId: match[2] };
    }
    match = /^experience:\/\/(.+)$/u.exec(ref);
    if (match) {
      return { kind: "experience", candidateId: match[1] };
    }
    match = /^knowledge-candidate:\/\/(.+)$/u.exec(ref);
    if (match) {
      return { kind: "knowledge", packId: match[1] };
    }
    match = /^soul-candidate:\/\/(.+)$/u.exec(ref);
    if (match) {
      return { kind: "soul", candidateId: match[1] };
    }
    match = /^adapter:\/\/(.+)$/u.exec(ref);
    if (match) {
      return { kind: "adapter", adapterId: match[1] };
    }
    match = /^skill:\/\/(.+)$/u.exec(ref);
    if (match) {
      return { kind: "skill", skillId: match[1] };
    }
    match = /^skill-proposal:\/\/(.+)$/u.exec(ref);
    if (match) {
      return { kind: "skill-proposal", proposalId: match[1] };
    }
    match = /^path:\/\/(.+)$/u.exec(ref);
    if (match) {
      return { kind: "path", path: match[1] };
    }
  }
  return null;
}

async function inspectTraceProposalAssets(workspace) {
  const traceProposalRoot = join(workspace.runtime, "proposals");
  const store = new FileSystemDirectorProposalStore({ rootPath: traceProposalRoot });
  const status = await store.getStatus();
  const issues = [];
  let proposals = [];

  try {
    proposals = [...(await store.listProposals())];
  } catch (error) {
    issues.push(`Failed to list trace proposals: ${toErrorMessage(error)}.`);
  }

  const pending = proposals.filter((proposal) => proposal.status === "pending");
  const accepted = proposals.filter((proposal) => proposal.status === "accepted");
  const rejected = proposals.filter((proposal) => proposal.status === "rejected");

  return {
    traceProposalRoot,
    traceProposalStatus: status.status === "degraded" || issues.length > 0 ? "degraded" : "ok",
    traceProposalCount: Math.max(status.proposalCount, proposals.length),
    pendingTraceProposalCount: pending.length,
    acceptedTraceProposalCount: accepted.length,
    rejectedTraceProposalCount: rejected.length,
    traceProposalLastUpdatedAt: status.lastUpdatedAt ?? null,
    traceProposalNotes: [...status.notes],
    traceProposalIssues: issues,
    traceProposalItems: proposals.map((proposal) => ({
      id: proposal.proposalId,
      kind: proposal.kind,
      title: proposal.title,
      summary: proposal.summary,
      trigger: proposal.trigger,
      evidenceSummary: proposal.evidenceSummary,
      explanation: proposal.explanation,
      provenance: proposal.provenance,
      status: proposal.status,
      riskLevel: proposal.riskLevel,
      confidence: proposal.confidence,
      projectId: proposal.projectId,
      groupId: proposal.groupId,
      runId: proposal.runId,
      reportId: proposal.reportId,
      recordId: proposal.recordId,
      digestId: proposal.digestId,
      createdAt: proposal.createdAt,
      updatedAt: proposal.updatedAt,
      tags: [...proposal.tags],
      roles: [...(proposal.roles ?? [])],
      selectedAdapters: [...(proposal.selectedAdapters ?? [])],
    })),
  };
}

async function inspectExecutionRunAssets(workspace, dataDir) {
  const executionRoot = join(workspace.runtime, "execution");
  const executionRunRoot = join(executionRoot, "runs");
  const store = new FileSystemRunStore({ rootPath: executionRoot });
  let entries;

  try {
    entries = await readdir(executionRunRoot, { withFileTypes: true });
  } catch (error) {
    if (error?.code === "ENOENT") {
      return createEmptyExecutionRunAssets(executionRunRoot);
    }
    return {
      ...createEmptyExecutionRunAssets(executionRunRoot),
      executionStatus: "degraded",
      unreadableExecutionArtifacts: 1,
      runAttentionCount: 1,
      executionIssues: [`Failed to read execution runs: ${toErrorMessage(error)}.`],
    };
  }

  const runs = [];
  const reports = [];
  const issues = [];
  let unreadableExecutionArtifacts = 0;

  for (const entry of entries) {
    if (!entry.isDirectory()) {
      continue;
    }
    const [runResult, reportResult] = await Promise.all([
      readExecutionStoreArtifact(() => store.loadRun(entry.name)),
      readExecutionStoreArtifact(() => store.loadReport(entry.name)),
    ]);

    if (runResult.unreadable) {
      unreadableExecutionArtifacts += 1;
      issues.push(`Run ${entry.name} could not be read: ${runResult.issue}.`);
    } else if (runResult.value !== null) {
      runs.push(runResult.value);
    }

    if (reportResult.unreadable) {
      unreadableExecutionArtifacts += 1;
      issues.push(`Run report ${entry.name} could not be read: ${reportResult.issue}.`);
    } else if (reportResult.value !== null) {
      reports.push(reportResult.value);
    }
  }

  runs.sort((left, right) => compareIsoDesc(left.updatedAt, right.updatedAt));
  reports.sort((left, right) => compareIsoDesc(left.recordedAt, right.recordedAt));

  const statusCounts = countExecutionRunStatuses(runs);
  const runAttentionCount =
    statusCounts.failed +
    statusCounts.paused +
    statusCounts.created +
    statusCounts.aborted +
    unreadableExecutionArtifacts;

  return {
    executionRunRoot,
    executionStatus: issues.length > 0 ? "degraded" : "ok",
    executionRunCount: runs.length,
    executionReportCount: reports.length,
    unreadableExecutionArtifacts,
    runAttentionCount,
    createdRunCount: statusCounts.created,
    runningRunCount: statusCounts.running,
    pausedRunCount: statusCounts.paused,
    completedRunCount: statusCounts.completed,
    failedRunCount: statusCounts.failed,
    abortedRunCount: statusCounts.aborted,
    latestRun:
      runs[0] === undefined
        ? null
        : await formatExecutionRunSummaryWithDelegations(workspace.root, dataDir, runs[0]),
    latestReport: reports[0] === undefined ? null : formatExecutionReportSummary(reports[0]),
    executionIssues: issues,
    executionItems: await Promise.all(
      runs.map((run) => formatExecutionRunSummaryWithDelegations(workspace.root, dataDir, run)),
    ),
    executionReportItems: reports.map(formatExecutionReportSummary),
  };
}

function createEmptyExecutionRunAssets(executionRunRoot) {
  return {
    executionRunRoot,
    executionStatus: "ok",
    executionRunCount: 0,
    executionReportCount: 0,
    unreadableExecutionArtifacts: 0,
    runAttentionCount: 0,
    createdRunCount: 0,
    runningRunCount: 0,
    pausedRunCount: 0,
    completedRunCount: 0,
    failedRunCount: 0,
    abortedRunCount: 0,
    latestRun: null,
    latestReport: null,
    executionIssues: [],
    executionItems: [],
    executionReportItems: [],
  };
}

async function readExecutionStoreArtifact(loader) {
  try {
    return {
      value: await loader(),
      unreadable: false,
      issue: null,
    };
  } catch (error) {
    return {
      value: null,
      unreadable: true,
      issue: toErrorMessage(error),
    };
  }
}

function countExecutionRunStatuses(runs) {
  const counts = {
    created: 0,
    running: 0,
    paused: 0,
    completed: 0,
    failed: 0,
    aborted: 0,
  };

  for (const run of runs) {
    if (run.status in counts) {
      counts[run.status] += 1;
    }
  }

  return counts;
}

function formatExecutionRunSummary(run) {
  return {
    runId: run.runId,
    snapshotId: run.snapshotId,
    runtimeId: run.runtimeId,
    blueprintId: run.blueprintId,
    handoffId: run.handoffId,
    actionGraphId: run.actionGraphId,
    status: run.status,
    createdAt: run.createdAt,
    startedAt: run.startedAt ?? null,
    updatedAt: run.updatedAt,
    completedAt: run.completedAt ?? null,
    goal: run.goal,
    previewSummary: run.previewSummary,
    sideEffectsAllowed: run.sideEffectsAllowed,
    notes: [...(run.notes ?? [])],
    assignmentCounts: countExecutionAssignmentStatuses(run.assignments ?? []),
    assignmentCount: run.assignments?.length ?? 0,
    assignments: (run.assignments ?? []).map(formatExecutionAssignmentSummary),
    eventCount: run.events?.length ?? 0,
    events: (run.events ?? []).map(formatExecutionEventSummary),
  };
}

async function formatExecutionRunSummaryWithDelegations(_directorRoot, dataDir, run) {
  const summary = formatExecutionRunSummary(run);
  const delegationSnapshot = await readDesktopRunDelegationSnapshot({
    dataDir,
    workspaceRoot: dataDir,
    runId: run.runId,
    run,
  });
  return {
    ...summary,
    delegationSnapshot: summarizeDesktopRunDelegationSnapshot(delegationSnapshot),
  };
}

function summarizeDesktopRunDelegationSnapshot(snapshot) {
  return {
    schemaId: snapshot.schemaId,
    runId: snapshot.runId,
    sessionId: snapshot.sessionId,
    delegationCount: snapshot.delegationCount,
    verificationCount: snapshot.verificationCount,
    notificationCount: snapshot.notificationCount,
    subagentRunCount: snapshot.subagentRunCount ?? 0,
    pendingDelegationCount: snapshot.pendingDelegationCount,
    runningDelegationCount: snapshot.runningDelegationCount,
    completedDelegationCount: snapshot.completedDelegationCount,
    failedDelegationCount: snapshot.failedDelegationCount,
    subagentAnnounceCount: snapshot.subagentAnnounceCount ?? 0,
    queuedSubagentRunCount: snapshot.queuedSubagentRunCount ?? 0,
    runningSubagentRunCount: snapshot.runningSubagentRunCount ?? 0,
    completedSubagentRunCount: snapshot.completedSubagentRunCount ?? 0,
    failedSubagentRunCount: snapshot.failedSubagentRunCount ?? 0,
    workerIds: [...(snapshot.workerIds ?? [])],
    verifierIds: [...(snapshot.verifierIds ?? [])],
    subagentRuns: (snapshot.subagentRuns ?? []).map(formatDesktopRunSubagentRun),
    subagentAnnounces: (snapshot.subagentAnnounces ?? []).map(formatDesktopRunSubagentAnnounce),
    subagentSchedulerHeartbeat: snapshot.subagentSchedulerHeartbeat ?? null,
    subagentSchedulerDispatchPlan: snapshot.subagentSchedulerDispatchPlan ?? null,
    subagentSchedulerTick: snapshot.subagentSchedulerTick ?? null,
    subagentSchedulerRecoveryPlan: snapshot.subagentSchedulerRecoveryPlan ?? null,
    delegations: (snapshot.delegations ?? []).map(formatDesktopRunDelegationRecord),
    verification: (snapshot.verification ?? []).map(formatDesktopRunVerificationRecord),
  };
}

function formatDesktopRunSubagentAnnounce(announce) {
  return {
    announceId: announce.announceId,
    subagentId: announce.subagentId,
    requesterSessionKey: announce.requesterSessionKey,
    requesterOrigin: announce.requesterOrigin,
    deliveryTarget: announce.deliveryTarget,
    childSessionKey: announce.childSessionKey,
    status: announce.status,
    summary: announce.summary,
    userFacingText: announce.userFacingText,
    createdAtMs: announce.createdAtMs,
    updatedAtMs: announce.updatedAtMs,
    completedAtMs: announce.completedAtMs,
  };
}

function formatDesktopRunSubagentRun(run) {
  return {
    subagentId: run.subagentId,
    parentTurnId: run.parentTurnId,
    profileId: run.profileId,
    workerId: run.workerId,
    taskId: run.taskId,
    status: run.status,
    role: run.role,
    targetAgent: run.targetAgent,
    isolatedContext: run.isolatedContext,
    instruction: run.instruction,
    contextSnapshot: run.contextSnapshot,
    resultSummary: run.resultSummary,
    observedWriteSet: run.observedWriteSet,
    observedWriteSetSource: run.observedWriteSetSource,
    createdAtMs: run.createdAtMs,
    updatedAtMs: run.updatedAtMs,
    completedAtMs: run.completedAtMs,
    error: run.error,
    parentVisibleResult: run.parentVisibleResult,
    verification: run.verification,
    scheduling: run.scheduling,
  };
}

function formatDesktopRunDelegationRecord(record) {
  return {
    id: record.id,
    taskId: record.taskId,
    workerId: record.workerId,
    targetAgent: record.targetAgent,
    specialization: record.specialization,
    status: record.status,
    fromAgent: record.fromAgent,
    instruction: record.instruction,
    resultSummary: record.resultSummary,
    error: record.error,
    createdAtMs: record.createdAtMs,
    updatedAtMs: record.updatedAtMs,
    completedAtMs: record.completedAtMs,
    verificationRequest: record.verificationRequest,
  };
}

function formatDesktopRunVerificationRecord(record) {
  return {
    id: record.id,
    taskId: record.taskId,
    verifierId: record.verifierId,
    requirement: record.requirement,
    status: record.status,
    verdict: record.verdict,
    verdictSummary: record.verdictSummary,
    createdAtMs: record.createdAtMs,
    updatedAtMs: record.updatedAtMs,
  };
}

function formatExecutionReportSummary(report) {
  const operatorSurface = report.operatorSurface;
  const runSummary = formatExecutionRunSummary(report.run);
  const primaryAssignment = selectPrimaryReportAssignment(report.run.assignments ?? []);
  const primaryBridgeExecution = primaryAssignment?.result?.bridgeExecution;
  const primaryAdapter =
    primaryAssignment?.result?.adapterId ?? primaryAssignment?.selectedAdapter ?? null;
  const primaryRerouteCandidates =
    primaryAssignment === null
      ? []
      : collectExecutionRerouteCandidates(primaryAssignment, primaryAdapter);
  return {
    runId: report.runId,
    reportId: report.reportId,
    recordedAt: report.recordedAt,
    runStatus: report.run.status,
    summary: [...(report.summary ?? [])],
    flags: [...(report.flags ?? [])],
    directorGoal: operatorSurface?.directorGoal ?? report.run.goal,
    operatorSummary: operatorSurface?.operatorSummary ?? report.run.previewSummary,
    objective: operatorSurface?.objective ?? primaryAssignment?.objective ?? null,
    deliverable: operatorSurface?.deliverable ?? primaryAssignment?.deliverable ?? null,
    adapterRoute: operatorSurface?.adapterRoute ?? primaryAdapter,
    lastBridgeRoute: operatorSurface?.lastBridgeRoute ?? primaryAdapter,
    bridgeVerdict: operatorSurface?.bridgeVerdict ?? null,
    bridgeFailureReason:
      operatorSurface?.bridgeFailureReason ?? primaryBridgeExecution?.failure?.reason ?? null,
    bridgeFailureMessage: primaryBridgeExecution?.failure?.message ?? null,
    bridgeStatus:
      operatorSurface?.bridgeStatus ??
      primaryBridgeExecution?.failure?.statusCode ??
      primaryBridgeExecution?.response?.statusCode ??
      null,
    requestId: operatorSurface?.requestId ?? primaryBridgeExecution?.response?.requestId ?? null,
    requestAccepted:
      operatorSurface?.requestAccepted ?? primaryBridgeExecution?.response?.accepted ?? null,
    retryable: operatorSurface?.retryable ?? primaryBridgeExecution?.failure?.retryable ?? null,
    retryAllowed:
      operatorSurface?.retryAllowed ??
      operatorSurface?.retryable ??
      primaryBridgeExecution?.failure?.retryable ??
      null,
    rerouteCandidates: [...(operatorSurface?.rerouteCandidates ?? primaryRerouteCandidates)],
    bridgeAttempts: operatorSurface?.bridgeAttempts ?? null,
    nextAction: operatorSurface?.nextAction ?? null,
    assignmentCounts: runSummary.assignmentCounts,
    assignmentCount: runSummary.assignmentCount,
    assignments: runSummary.assignments,
    eventCount: report.events?.length ?? 0,
    events: (report.events ?? []).map(formatExecutionEventSummary),
  };
}

function formatExecutionAssignmentSummary(assignment) {
  const bridgeExecution = assignment.result?.bridgeExecution;
  const adapterId = assignment.result?.adapterId ?? assignment.selectedAdapter ?? null;
  return {
    runId: assignment.runId,
    assignmentId: assignment.assignmentId,
    role: assignment.role,
    objective: assignment.objective,
    deliverable: assignment.deliverable,
    actionClass: assignment.actionClass,
    approvalMode: assignment.approvalMode,
    dependsOn: [...(assignment.dependsOn ?? [])],
    status: assignment.status,
    selectedAdapter: assignment.selectedAdapter ?? null,
    adapterId,
    allowedAdapters: [...(assignment.allowedAdapters ?? [])],
    rerouteCandidates: collectExecutionRerouteCandidates(assignment, adapterId),
    blockingReason: assignment.blockingReason ?? null,
    timeoutMs: assignment.timeoutMs ?? null,
    createdAt: assignment.createdAt,
    startedAt: assignment.startedAt ?? null,
    completedAt: assignment.completedAt ?? null,
    notes: [...(assignment.notes ?? [])],
    resultStatus: assignment.result?.status ?? null,
    resultSummary: assignment.result?.summary ?? null,
    bridgeVerdict:
      bridgeExecution === undefined
        ? null
        : bridgeExecution.failure !== undefined
          ? "failed"
          : bridgeExecution.response?.accepted === true
            ? "accepted"
            : "responded",
    bridgeFailureReason: bridgeExecution?.failure?.reason ?? null,
    bridgeFailureMessage: bridgeExecution?.failure?.message ?? null,
    bridgeStatus:
      bridgeExecution?.failure?.statusCode ?? bridgeExecution?.response?.statusCode ?? null,
    bridgeRetryable: bridgeExecution?.failure?.retryable ?? null,
    retryAllowed:
      bridgeExecution?.failure?.retryable === undefined
        ? assignment.status === "failed" || assignment.status === "blocked"
        : bridgeExecution.failure.retryable,
  };
}

function formatExecutionEventSummary(event) {
  if (!isPlainObject(event)) {
    return { type: "unknown", summary: String(event) };
  }
  return {
    eventId: event.eventId ?? null,
    type: event.type ?? "unknown",
    at: event.at ?? event.occurredAt ?? event.createdAt ?? null,
    assignmentId: event.assignmentId ?? event.metadata?.assignmentId ?? null,
    summary: event.summary ?? event.message ?? event.type ?? "event",
  };
}

function countExecutionAssignmentStatuses(assignments) {
  const counts = {
    ready: 0,
    pending: 0,
    running: 0,
    completed: 0,
    failed: 0,
    blocked: 0,
    skipped: 0,
    aborted: 0,
  };
  for (const assignment of assignments) {
    if (assignment.status in counts) {
      counts[assignment.status] += 1;
    }
  }
  return counts;
}

function collectExecutionRerouteCandidates(assignment, currentAdapter) {
  return uniqueStringArray(
    (assignment.allowedAdapters ?? []).filter((adapterId) => adapterId !== currentAdapter),
  );
}

function selectPrimaryReportAssignment(assignments) {
  return (
    assignments.find((assignment) => assignment.result?.bridgeExecution !== undefined) ??
    assignments.find((assignment) => assignment.actionClass === "generate") ??
    assignments[0] ??
    null
  );
}

function isRealExecutionEligible(adapter, switchState) {
  if (adapter.adapterKind === "media" && adapter.adapterId === "comfyui-media") {
    return (
      adapter.enabled &&
      !adapter.mockOnly &&
      switchState.features["mediaAdapters.enabled"] &&
      switchState.features["execution.enabled"]
    );
  }
  return (
    adapter.adapterKind === "execution" &&
    adapter.enabled &&
    !adapter.mockOnly &&
    adapter.bridge !== undefined &&
    switchState.features["execution.enabled"] &&
    switchState.features["execution.sideEffects.enabled"]
  );
}

function deriveAdapterRiskLevel(adapter) {
  if (["low", "medium", "high"].includes(adapter.riskLevel)) {
    return adapter.riskLevel;
  }
  if (adapter.mockOnly) {
    return "low";
  }
  const actionClasses = adapter.supportedActionClasses ?? [];
  const canMutate = actionClasses.some((actionClass) =>
    ["write", "generate", "publish"].includes(actionClass),
  );
  if (adapter.bridge !== undefined && canMutate) {
    return "high";
  }
  if (adapter.bridge !== undefined || canMutate || adapter.adapterKind === "execution") {
    return "medium";
  }
  return "low";
}

function deriveAdapterApprovalMode(adapter, riskLevel) {
  if (["auto_allow", "operator_approve", "forbidden_in_beta1"].includes(adapter.approvalMode)) {
    return adapter.approvalMode;
  }
  if (adapter.mockOnly || riskLevel === "low") {
    return "auto_allow";
  }
  return "operator_approve";
}

function createAdapterActionCatalog(adapter, { realExecutionEligible }) {
  return uniqueStringArray(adapter.supportedActionClasses ?? []).map((actionClass) =>
    createAdapterActionDescriptor(adapter, actionClass, { realExecutionEligible }),
  );
}

function createAdapterActionDescriptor(adapter, actionClass, { realExecutionEligible }) {
  const sideEffect = isAdapterActionSideEffect(actionClass);
  const riskLevel = deriveAdapterActionRiskLevel(adapter, actionClass);
  const approvalMode = deriveAdapterActionApprovalMode(adapter, riskLevel);
  const executionMode = deriveAdapterActionExecutionMode(adapter, {
    sideEffect,
    realExecutionEligible,
  });
  const label = formatAdapterActionClassLabel(actionClass);
  return {
    actionClass,
    label,
    sideEffect,
    riskLevel,
    approvalMode,
    executionMode,
    inputs: deriveAdapterActionInputs(adapter, actionClass),
    outputs: deriveAdapterActionOutputs(adapter, actionClass),
    costClass: deriveAdapterActionCostClass(adapter),
    retryPolicy: deriveAdapterActionRetryPolicy(adapter, { approvalMode, sideEffect }),
    timeoutMs: readFiniteNumber(adapter.bridge?.timeoutMs),
    auditTrailRequired: adapter.bridge !== undefined || sideEffect || riskLevel !== "low",
    summary: `${label} · ${formatAdapterRiskText(riskLevel)} · ${formatAdapterApprovalText(
      approvalMode,
    )} · ${formatAdapterExecutionModeText(executionMode)}`,
    reason: formatAdapterActionReason(adapter, {
      actionClass,
      label,
      sideEffect,
      riskLevel,
      approvalMode,
      executionMode,
      realExecutionEligible,
    }),
  };
}

function deriveAdapterActionInputs(adapter, actionClass) {
  if (adapter.mediaCapability !== null && adapter.mediaCapability !== undefined) {
    return [
      `输入模态：${(adapter.mediaCapability.inputModalities ?? []).join("/") || "未声明"}`,
      "制作目标",
      "参考素材或上下文",
    ];
  }
  if (actionClass === "read") {
    return ["查询目标", "只读上下文"];
  }
  if (actionClass === "generate") {
    return ["生成目标", "参考素材", "人工审批记录"];
  }
  if (actionClass === "publish") {
    return ["待发布产物", "发布目标", "人工审批记录"];
  }
  return ["执行目标", "待写入或修改的资产", "人工审批记录"];
}

function deriveAdapterActionOutputs(adapter, actionClass) {
  if (adapter.mediaCapability !== null && adapter.mediaCapability !== undefined) {
    return [
      `输出类型：${(adapter.mediaCapability.outputArtifactTypes ?? []).join("/") || "未声明"}`,
      "生成资产引用",
      "审计事件",
    ];
  }
  if (actionClass === "read") {
    return ["查询结果", "审计事件"];
  }
  if (actionClass === "generate") {
    return ["生成产物引用", "执行摘要", "审计事件"];
  }
  if (actionClass === "publish") {
    return ["发布结果", "外部平台引用", "审计事件"];
  }
  return ["变更摘要", "产物或文件引用", "审计事件"];
}

function deriveAdapterActionCostClass(adapter) {
  if (adapter.mediaCapability?.costClass !== undefined) {
    return adapter.mediaCapability.costClass;
  }
  if (adapter.bridge !== undefined) {
    return "external-unknown";
  }
  return adapter.mockOnly ? "none" : "local";
}

function deriveAdapterActionRetryPolicy(adapter, { approvalMode, sideEffect }) {
  if (adapter.mockOnly) {
    return "safe-repeat";
  }
  if (approvalMode === "operator_approve") {
    return "manual-review-required";
  }
  if (!sideEffect) {
    return "auto-retry-allowed";
  }
  return "manual-on-failure";
}

function isAdapterActionSideEffect(actionClass) {
  return ["generate", "write", "publish"].includes(actionClass);
}

function deriveAdapterActionRiskLevel(adapter, actionClass) {
  if (adapter.mockOnly) {
    return "low";
  }
  if (adapter.riskLevel === "high" && isAdapterActionSideEffect(actionClass)) {
    return "high";
  }
  const sideEffect = isAdapterActionSideEffect(actionClass);
  if (adapter.bridge !== undefined && sideEffect) {
    return "high";
  }
  if (adapter.bridge !== undefined || sideEffect || adapter.adapterKind === "execution") {
    return "medium";
  }
  return "low";
}

function deriveAdapterActionApprovalMode(adapter, riskLevel) {
  if (["operator_approve", "forbidden_in_beta1"].includes(adapter.approvalMode)) {
    return adapter.approvalMode;
  }
  if (adapter.mockOnly || riskLevel === "low") {
    return "auto_allow";
  }
  return "operator_approve";
}

function deriveAdapterActionExecutionMode(adapter, { sideEffect, realExecutionEligible }) {
  if (adapter.mockOnly) {
    return "mock-only";
  }
  if (!sideEffect) {
    return "read-only";
  }
  if (adapter.dryRunSupported) {
    return "dry-run-required";
  }
  if (realExecutionEligible) {
    return "operator-approved-real";
  }
  return "blocked";
}

function formatAdapterActionReason(
  adapter,
  { label, sideEffect, riskLevel, approvalMode, executionMode, realExecutionEligible },
) {
  return [
    sideEffect ? `${label}会改变外部工具状态或生成资产` : `${label}不产生外部副作用`,
    adapter.bridge !== undefined ? `外部桥接 ${adapter.bridge.kind} 需要记录和审查` : "无外部桥接",
    adapter.mockOnly ? "当前仅模拟执行" : null,
    adapter.enabled ? null : "当前工具开关未启用",
    realExecutionEligible ? "真实执行门禁已满足" : "真实执行门禁未满足",
    `风险=${formatAdapterRiskText(riskLevel)}`,
    `审批=${formatAdapterApprovalText(approvalMode)}`,
    `执行=${formatAdapterExecutionModeText(executionMode)}`,
  ]
    .filter(Boolean)
    .join("；");
}

function formatAdapterActionClassLabel(actionClass) {
  const labels = {
    read: "读取",
    generate: "生成",
    write: "写入",
    publish: "发布",
  };
  return labels[actionClass] ?? actionClass;
}

function formatAdapterRiskText(riskLevel) {
  const labels = {
    low: "低风险",
    medium: "中风险",
    high: "高风险",
  };
  return labels[riskLevel] ?? riskLevel;
}

function formatAdapterApprovalText(approvalMode) {
  const labels = {
    auto_allow: "自动允许",
    operator_approve: "人工审批",
    forbidden_in_beta1: "当前禁止",
  };
  return labels[approvalMode] ?? approvalMode;
}

function formatAdapterExecutionModeText(executionMode) {
  const labels = {
    blocked: "阻断",
    "dry-run-required": "先 dry-run",
    "mock-only": "仅模拟",
    "operator-approved-real": "审批后真实执行",
    "read-only": "只读",
  };
  return labels[executionMode] ?? executionMode;
}

function formatAdapterAuditSummary(adapter, { realExecutionEligible, riskLevel, approvalMode }) {
  return [
    `bridge=${adapter.bridge?.kind ?? "none"}`,
    `risk=${riskLevel}`,
    `approval=${approvalMode}`,
    `dryRun=${adapter.dryRunSupported === true ? "yes" : "no"}`,
    `mockOnly=${adapter.mockOnly === true ? "yes" : "no"}`,
    `realEligible=${realExecutionEligible ? "yes" : "no"}`,
    `permissions=${(adapter.permissionScopes ?? []).length}`,
  ].join(" · ");
}

function compareIsoDesc(left, right) {
  return right.localeCompare(left);
}

function toErrorMessage(error) {
  return error instanceof Error ? error.message : String(error);
}

function selectPrimaryExperienceCandidate(candidates) {
  return candidates[0] ?? null;
}

function selectPrimaryKnowledgeCandidate(candidates) {
  return candidates[0] ?? null;
}

function resolveCandidateStatus(candidate) {
  return candidate.promoted ? "promoted" : candidate.status;
}

function extractKnowledgeCandidateIdFromPromotion(promotion) {
  if (promotion === null || typeof promotion !== "object") {
    return null;
  }
  const ref = typeof promotion.promotedRef === "string" ? promotion.promotedRef.trim() : "";
  const prefix = "knowledge://candidate/";
  if (ref.startsWith(prefix) && ref.length > prefix.length) {
    return ref.slice(prefix.length);
  }
  return null;
}

function formatExperienceCandidate(
  entry,
  artifactsById = new Map(),
  taxonomy = createEmptyExperienceTaxonomy(),
  artifactIndex = createExperienceArtifactIndex(),
) {
  const candidate = entry.candidate;
  const quality = formatExperienceQuality(candidate.quality);
  const evidence = formatExperienceEvidenceReferences(candidate);
  const sourceArtifactId =
    typeof candidate.sourceArtifactId === "string" ? candidate.sourceArtifactId : null;
  const sourceArtifact = resolveExperienceCandidateSourceArtifact(
    candidate,
    artifactsById,
    artifactIndex,
  );
  const sourceDocument = formatExperienceSourceDocument(candidate, sourceArtifact);
  const taxonomyBinding = entry.taxonomy ?? null;
  const category = resolveTaxonomyCategory(taxonomy, taxonomyBinding?.categoryId);
  const taxonomyTags = resolveTaxonomyTags(taxonomy, taxonomyBinding?.tagIds ?? []);
  const latestPromotion = entry.latestPromotion ?? null;
  const sourceContent = [sourceDocument.content, sourceDocument.rawContent, candidate.evidencePreview]
    .filter((value) => typeof value === "string" && value.length > 0)
    .join("\n");
  const mediaAuthorizationRequest = readDesktopMediaAuthorizationRequest(candidate, sourceArtifact);
  const mediaUnderstandingFromArtifact = summarizeDesktopExperienceMediaUnderstandingArtifact(
    candidate,
    sourceArtifact,
  );
  return {
    id: candidate.candidateId,
    title: candidate.title,
    summary: candidate.summary,
    applicability: candidate.applicability,
    risks: Array.isArray(candidate.risks) ? [...candidate.risks] : [],
    status: resolveCandidateStatus(entry),
    sourceKind: candidate.sourceAdapter.sourceKind,
    sourceRef: resolveExperienceCandidatePrimarySourceRef(candidate, evidence),
    rawSourceRef: candidate.sourceAdapter.sourceRef,
    adapterId: candidate.sourceAdapter.adapterId,
    privacy: candidate.privacy,
    provenance: candidate.provenance ?? null,
    runtimeInjection: candidate.runtimeInjection ?? null,
    tags: [...candidate.tags],
    category,
    taxonomyTags,
    taxonomy: taxonomyBinding,
    distillation: summarizeExperienceDistillation(candidate.tags),
    evidenceCount: candidate.evidence.length,
    evidence,
    sourceArtifactId,
    sourceDigest: candidate.sourceDigest ?? null,
    evidencePreview: candidate.evidencePreview ?? "",
    sourceDocument,
    contentQuality: summarizeDesktopExperienceContentQualityText(sourceContent),
    mediaUnderstanding:
      mediaUnderstandingFromArtifact ?? summarizeDesktopExperienceMediaUnderstandingText(sourceContent),
    ...(mediaAuthorizationRequest === null ? {} : { mediaAuthorizationRequest }),
    quality,
    qualityScore: candidate.quality?.score ?? null,
    qualityVerdict: candidate.quality?.verdict ?? "unknown",
    qualityReasons: [...(candidate.quality?.reasons ?? [])],
    promoted: entry.promoted,
    promotion:
      latestPromotion === null
        ? null
        : {
            id: latestPromotion.promotionId,
            promotedTo: latestPromotion.promotedTo,
            promotedRef: latestPromotion.promotedRef,
            promotedAtMs: latestPromotion.promotedAtMs,
          },
    knowledgeCandidateId: extractKnowledgeCandidateIdFromPromotion(latestPromotion),
    createdAtMs: candidate.createdAtMs,
  };
}

function resolveExperienceCandidatePrimarySourceRef(candidate, evidence) {
  const evidenceSource = evidence.find(
    (entry) => typeof entry.sourceRef === "string" && /^https?:\/\//iu.test(entry.sourceRef),
  )?.sourceRef;
  if (evidenceSource !== undefined) {
    return evidenceSource;
  }
  const adapterSource =
    typeof candidate.sourceAdapter?.sourceRef === "string" ? candidate.sourceAdapter.sourceRef : "";
  if (adapterSource.startsWith("pasted://")) {
    return candidate.evidence.find(
      (entry) => typeof entry.sourceRef === "string" && entry.sourceRef.length > 0,
    )?.sourceRef ?? adapterSource;
  }
  return adapterSource;
}

function createEmptyExperienceTaxonomy() {
  return {
    schemaVersion: "director.experience.taxonomy.v1",
    categories: [],
    tags: [],
    candidates: [],
  };
}

function formatExperienceTaxonomy(taxonomy) {
  return {
    schemaVersion: taxonomy.schemaVersion ?? "director.experience.taxonomy.v1",
    categories: Array.isArray(taxonomy.categories) ? taxonomy.categories : [],
    tags: Array.isArray(taxonomy.tags) ? taxonomy.tags : [],
    candidates: Array.isArray(taxonomy.candidates) ? taxonomy.candidates : [],
  };
}

function readDesktopMediaAuthorizationRequest(candidate, artifact) {
  if (isPlainObject(candidate?.mediaAuthorizationRequest)) {
    return candidate.mediaAuthorizationRequest;
  }
  if (isPlainObject(candidate?.metadata?.mediaAuthorizationRequest)) {
    return candidate.metadata.mediaAuthorizationRequest;
  }
  if (isPlainObject(artifact?.mediaAuthorizationRequest)) {
    return artifact.mediaAuthorizationRequest;
  }
  if (isPlainObject(artifact?.metadata?.mediaAuthorizationRequest)) {
    return artifact.metadata.mediaAuthorizationRequest;
  }
  return null;
}

function summarizeDesktopExperienceMediaUnderstandingArtifact(candidate, artifact) {
  const metadataCandidates = [
    candidate?.mediaUnderstanding,
    candidate?.metadata?.mediaUnderstanding,
    artifact?.mediaUnderstanding,
    artifact?.metadata?.mediaUnderstanding,
  ];
  for (const value of metadataCandidates) {
    if (!isPlainObject(value)) {
      continue;
    }
    const status = readStringProperty(value, "status");
    const runner = readStringProperty(value, "runner");
    const processedCount = readFiniteNumber(value.processedCount) ?? 0;
    const semanticUnderstanding = readStringProperty(value, "semanticUnderstanding");
    if (status === "metadata_understood" || semanticUnderstanding === "metadata-only") {
      return `已有元数据级媒体理解证据：${runner ?? "media-understanding.local"} 已处理 ${processedCount} 个媒体；还没有完成完整视觉/视频/音频语义精读。`;
    }
  }
  return null;
}

function resolveTaxonomyCategory(taxonomy, categoryId) {
  const categories = Array.isArray(taxonomy.categories) ? taxonomy.categories : [];
  if (typeof categoryId === "string" && categoryId.length > 0) {
    const category = categories.find((entry) => entry.categoryId === categoryId);
    return category ?? { categoryId, name: categoryId };
  }
  return categories.find((entry) => entry.categoryId === "uncategorized") ?? null;
}

function resolveTaxonomyTags(taxonomy, tagIds) {
  const tags = Array.isArray(taxonomy.tags) ? taxonomy.tags : [];
  return tagIds.map(
    (tagId) => tags.find((entry) => entry.tagId === tagId) ?? { tagId, name: tagId },
  );
}

function summarizeExperienceDistillation(tags) {
  const tagList = Array.isArray(tags) ? tags : [];
  const distiller = tagList.find((tag) => tag.startsWith("distiller:"))?.replace("distiller:", "");
  const confidence = tagList
    .find((tag) => /^distillation:(high|medium|low)$/u.test(tag))
    ?.replace("distillation:", "");

  if (tagList.includes("distillation:model")) {
    return {
      mode: "model",
      label: distiller ? `API 模型提炼 · ${distiller}` : "API 模型提炼",
      confidence: confidence ?? "unknown",
    };
  }

  if (tagList.includes("distillation:model-fallback")) {
    return {
      mode: "model-fallback",
      label: distiller ? `模型失败，规则兜底 · ${distiller}` : "模型失败，规则兜底",
      confidence: confidence ?? "unknown",
    };
  }

  if (confidence !== undefined) {
    const labels = {
      high: "规则提炼 · 高置信",
      medium: "规则提炼 · 中置信",
      low: "规则提炼 · 低置信",
    };
    return {
      mode: "heuristic",
      label: labels[confidence] ?? "规则提炼",
      confidence,
    };
  }

  return {
    mode: "unknown",
    label: "未标记提炼方式",
    confidence: "unknown",
  };
}

function formatExperienceQuarantineRecord(record) {
  const artifact = isPlainObject(record.artifact) ? record.artifact : {};
  const quality = formatExperienceQuality(record.quality ?? artifact.quality);
  const id = record.quarantineId ?? record.id ?? "quarantine";
  const reason = record.reason ?? record.summary ?? "";
  return {
    id,
    title: record.title ?? artifact.title ?? artifact.sourceRef ?? id,
    summary: reason,
    reason,
    sourceKind: record.sourceKind ?? artifact.sourceKind ?? "unknown",
    sourceRef: record.sourceRef ?? artifact.sourceRef ?? "",
    quality,
    qualityScore: quality.score,
    qualityVerdict: quality.verdict,
    qualityReasons: [...quality.reasons],
    textPreview: record.textPreview ?? artifact.textPreview ?? "",
    sourceDocument: formatQuarantineSourceDocument(record, artifact),
    createdAtMs: record.createdAtMs,
    notes: [...(record.notes ?? [])],
  };
}

function createExperienceArtifactMap(artifacts) {
  const map = new Map();
  for (const artifact of Array.isArray(artifacts) ? artifacts : []) {
    if (isPlainObject(artifact) && typeof artifact.artifactId === "string") {
      map.set(artifact.artifactId, artifact);
    }
  }
  return map;
}

function createExperienceArtifactIndex(artifacts = []) {
  const byCandidateId = new Map();
  const bySourceRef = new Map();
  for (const artifact of Array.isArray(artifacts) ? artifacts : []) {
    if (!isPlainObject(artifact)) {
      continue;
    }
    const candidateIds = Array.isArray(artifact.metadata?.candidateIds)
      ? artifact.metadata.candidateIds
      : [];
    for (const candidateId of candidateIds) {
      if (typeof candidateId === "string" && candidateId.length > 0) {
        byCandidateId.set(candidateId, artifact);
      }
    }
    const sourceRefs = [
      artifact.sourceRef,
      artifact.source_ref,
      artifact.metadata?.sourceUrl,
      artifact.metadata?.url,
    ];
    for (const sourceRef of sourceRefs) {
      for (const key of normalizeDesktopEvidenceUrlKeys(sourceRef)) {
        bySourceRef.set(key, artifact);
      }
    }
  }
  return { byCandidateId, bySourceRef };
}

function resolveExperienceCandidateSourceArtifact(candidate, artifactsById, artifactIndex) {
  const sourceArtifactId =
    typeof candidate?.sourceArtifactId === "string" ? candidate.sourceArtifactId : null;
  if (sourceArtifactId !== null) {
    const byId = artifactsById.get(sourceArtifactId);
    if (isPlainObject(byId)) {
      return byId;
    }
  }
  const candidateId = readNonEmptyString(candidate?.candidateId ?? candidate?.id);
  if (candidateId !== undefined) {
    const byCandidateId = artifactIndex.byCandidateId.get(candidateId);
    if (isPlainObject(byCandidateId)) {
      return byCandidateId;
    }
  }
  const sourceRefs = [
    candidate?.sourceAdapter?.sourceRef,
    candidate?.sourceRef,
    candidate?.rawSourceRef,
    ...(Array.isArray(candidate?.evidence)
      ? candidate.evidence.map((entry) => entry?.sourceRef)
      : []),
  ];
  for (const sourceRef of sourceRefs) {
    for (const key of normalizeDesktopEvidenceUrlKeys(sourceRef)) {
      const bySourceRef = artifactIndex.bySourceRef.get(key);
      if (isPlainObject(bySourceRef)) {
        return bySourceRef;
      }
    }
  }
  return null;
}

function formatExperienceSourceDocument(candidate, artifact) {
  const content = readExperienceArtifactContent(artifact) ?? candidate.evidencePreview ?? "";
  return createDesktopSourceDocument({
    artifact,
    fallbackTitle: candidate.title,
    fallbackSourceRef: candidate.sourceAdapter?.sourceRef,
    fallbackSourceKind: candidate.sourceAdapter?.sourceKind,
    content,
    isFullContent: isPlainObject(artifact) && typeof artifact.rawContent === "string",
  });
}

function formatQuarantineSourceDocument(record, artifact) {
  const content = readExperienceArtifactContent(artifact) ?? record.textPreview ?? "";
  return createDesktopSourceDocument({
    artifact,
    fallbackTitle: record.title,
    fallbackSourceRef: record.sourceRef,
    fallbackSourceKind: record.sourceKind,
    content,
    isFullContent: isPlainObject(artifact) && typeof artifact.rawContent === "string",
  });
}

function createDesktopSourceDocument({
  artifact,
  fallbackTitle,
  fallbackSourceRef,
  fallbackSourceKind,
  content,
  isFullContent,
}) {
  const normalizedContent = String(content ?? "");
  const limited = limitDesktopSourceContent(normalizedContent);
  const rawContent = readStringProperty(artifact, "rawContent");
  const limitedRawContent =
    rawContent === null || rawContent === undefined ? null : limitDesktopSourceContent(rawContent);
  return {
    title: readStringProperty(artifact, "title") ?? fallbackTitle ?? "抓取内容",
    sourceRef: readStringProperty(artifact, "sourceRef") ?? fallbackSourceRef ?? "",
    sourceKind: readStringProperty(artifact, "sourceKind") ?? fallbackSourceKind ?? "unknown",
    contentType: readStringProperty(artifact, "contentType") ?? "text/plain",
    bytes: readFiniteNumber(artifact?.bytes),
    content: limited.content,
    ...(limitedRawContent === null ? {} : { rawContent: limitedRawContent.content }),
    ...(isPlainObject(artifact?.metadata) ? { metadata: artifact.metadata } : {}),
    ...(isDesktopStructuredSourceContent(artifact?.structuredContent)
      ? { structuredContent: artifact.structuredContent }
      : {}),
    ...(formatExperienceExtractionReport(artifact?.extractionReport) === null
      ? {}
      : { extractionReport: formatExperienceExtractionReport(artifact.extractionReport) }),
    originalChars: normalizedContent.length,
    truncated: limited.truncated,
    isFullContent,
  };
}

function isDesktopStructuredSourceContent(value) {
  return Array.isArray(value) || isPlainObject(value);
}

function readExperienceArtifactContent(artifact) {
  if (!isPlainObject(artifact)) {
    return null;
  }
  if (typeof artifact.readableContent === "string" && artifact.readableContent.length > 0) {
    return artifact.readableContent;
  }
  if (typeof artifact.rawContent === "string" && artifact.rawContent.length > 0) {
    return artifact.rawContent;
  }
  if (typeof artifact.textPreview === "string" && artifact.textPreview.length > 0) {
    return artifact.textPreview;
  }
  return null;
}

function formatExperienceExtractionReport(report) {
  if (!isPlainObject(report)) {
    return null;
  }
  const transformations = Array.isArray(report.transformations)
    ? report.transformations.filter((entry) => typeof entry === "string")
    : [];
  const notes = Array.isArray(report.notes)
    ? report.notes.filter((entry) => typeof entry === "string")
    : [];
  const unavailable = Array.isArray(report.unavailable)
    ? report.unavailable.filter((entry) => typeof entry === "string")
    : [];
  return {
    status: typeof report.status === "string" ? report.status : "unknown",
    readableChars: readFiniteNumber(report.readableChars) ?? 0,
    rawChars: readFiniteNumber(report.rawChars) ?? 0,
    transformations,
    notes,
    unavailable,
  };
}

function limitDesktopSourceContent(content) {
  return limitDesktopTextContent(content, MAX_DESKTOP_SOURCE_CONTENT_CHARS, "来源内容");
}

function limitDesktopTextContent(content, maxChars, label = "内容") {
  if (content.length <= maxChars) {
    return { content, truncated: false };
  }
  return {
    content: `${content.slice(0, maxChars)}\n\n[${label}过长，桌面端快照已截断显示前 ${maxChars} 字符。]`,
    truncated: true,
  };
}

function readExperienceQuarantineItems(experience) {
  if (Array.isArray(experience.quarantined)) {
    return experience.quarantined;
  }
  if (Array.isArray(experience.quarantineItems)) {
    return experience.quarantineItems;
  }
  return [];
}

function formatExperienceQuality(value) {
  const quality = isPlainObject(value) ? value : {};
  const score = readFiniteNumber(quality.score);
  const verdict = typeof quality.verdict === "string" ? quality.verdict : "unknown";
  const reasons = Array.isArray(quality.reasons)
    ? quality.reasons.filter((reason) => typeof reason === "string")
    : [];
  return {
    score,
    verdict,
    label: formatExperienceQualityLabel(verdict, score),
    reasons,
  };
}

function formatExperienceQualityLabel(verdict, score) {
  if (score === null) {
    return verdict;
  }
  if (score >= 0 && score <= 1) {
    return `${verdict} ${Math.round(score * 100)}%`;
  }
  return `${verdict} ${score}`;
}

function formatExperienceEvidenceReferences(candidate) {
  const evidence = Array.isArray(candidate.evidence) ? candidate.evidence : [];
  return evidence.slice(0, 4).map((entry) => ({
    id: entry.evidenceId ?? entry.id ?? "",
    sourceRef: entry.sourceRef ?? "",
    path: entry.path ?? null,
    span: entry.span ?? null,
    summary: entry.summary ?? "",
    preview: readEvidencePreview(entry) ?? entry.summary ?? "",
  }));
}

function readEvidencePreview(entry) {
  if (!isPlainObject(entry.attributes)) {
    return null;
  }
  return typeof entry.attributes.preview === "string" ? entry.attributes.preview : null;
}

function readFiniteNumber(value) {
  return typeof value === "number" && Number.isFinite(value) ? value : null;
}

function readFirstFiniteNumber(value, keys) {
  if (!isPlainObject(value)) {
    return null;
  }
  for (const key of keys) {
    const numberValue = readFiniteNumber(value[key]);
    if (numberValue !== null) {
      return numberValue;
    }
  }
  return null;
}

function readStringProperty(value, key) {
  if (!isPlainObject(value)) {
    return null;
  }
  return typeof value[key] === "string" ? value[key] : null;
}

function formatKnowledgeCandidate(entry) {
  const candidate = entry.candidate;
  return {
    id: candidate.metadata.id,
    title: candidate.metadata.title,
    summary: candidate.diff.summary || candidate.method.summary,
    status: entry.status,
    operation: candidate.evolution.operation,
    version: candidate.metadata.version,
    groupId: candidate.method.groupId,
    trigger: candidate.method.trigger,
    tags: [...(candidate.metadata.tags ?? [])],
    updatedAt: candidate.audit.candidateAt,
  };
}

function formatPublishedKnowledge(document) {
  if (document === null) {
    return null;
  }
  return {
    id: document.metadata.id,
    title: document.metadata.title,
    version: document.metadata.version,
    publishedAt: document.audit.publishedAt,
    tags: [...(document.metadata.tags ?? [])],
    projectId: document.method.projectId,
    groupId: document.method.groupId,
    anchorIds: [...(document.method.anchorIds ?? [])],
    preferredAdapters: [...(document.method.preferredAdapters ?? [])],
    generationType: document.method.generationType,
    generationStyle: document.method.generationStyle,
  };
}

function formatRecallHit(hit) {
  return {
    id: hit.knowledgePackId,
    title: hit.title,
    version: hit.version,
    score: hit.score,
    reasons: [...hit.reasons],
    tags: [...hit.tags],
    summary: hit.summary,
  };
}

function createSourceItems(experienceItems, knowledgeCandidateItems, latestPublished) {
  const seen = new Set();
  const items = [];

  for (const candidate of experienceItems) {
    const key = `${candidate.sourceKind}:${candidate.sourceRef}`;
    if (seen.has(key)) {
      continue;
    }
    seen.add(key);
    items.push({
      id: key,
      label: candidate.sourceRef,
      kind: candidate.sourceKind,
      meta: candidate.status,
    });
  }

  for (const candidate of knowledgeCandidateItems) {
    const key = `knowledge:${candidate.id}`;
    if (seen.has(key)) {
      continue;
    }
    seen.add(key);
    items.push({
      id: key,
      label: candidate.title,
      kind: "knowledge",
      meta: candidate.status,
    });
  }

  if (latestPublished !== null) {
    items.push({
      id: `published:${latestPublished.id}`,
      label: latestPublished.title,
      kind: "published",
      meta: "published",
    });
  }

  return items.slice(0, 8);
}

function groupExperienceBySource(experienceItems) {
  const groups = new Map();
  for (const item of experienceItems) {
    const current = groups.get(item.sourceKind) ?? {
      id: item.sourceKind,
      label: formatSourceKind(item.sourceKind),
      count: 0,
      pendingCount: 0,
    };
    current.count += 1;
    current.pendingCount += item.status === "pending" ? 1 : 0;
    groups.set(item.sourceKind, current);
  }
  return [...groups.values()].sort((left, right) => right.count - left.count);
}

function formatSourceKind(sourceKind) {
  const labels = {
    "local-directory": "本地资料",
    "pasted-text": "粘贴文本",
    "web-page": "网页",
    "web-search": "网页主题",
    url: "URL",
    web: "网页",
    query: "搜索主题",
  };
  return labels[sourceKind] ?? sourceKind;
}

function resolveApprovedSkillsPath(dataDir) {
  const override = process.env.HOTFLOW_SKILLS_SNAPSHOT_PATH?.trim();
  return override || join(dataDir, "skills", "approved-skills.json");
}

function createSkillTaxonomyStore(dataDir) {
  return new FileSkillTaxonomyStore({ skillsDir: join(dataDir, "skills") });
}

async function readSkillTaxonomySnapshot(dataDir) {
  try {
    return {
      document: await createSkillTaxonomyStore(dataDir).inspectTaxonomy(),
      readError: null,
    };
  } catch (error) {
    return {
      document: createEmptySkillTaxonomyDocument(),
      readError: toErrorMessage(error),
    };
  }
}

function createEmptySkillTaxonomyDocument() {
  return {
    schemaVersion: "skills.taxonomy.v1",
    categories: [],
    tags: [],
    skills: [],
  };
}

async function assertApprovedSkillExists(dataDir, skillId) {
  const document = await readJsonOrNull(resolveApprovedSkillsPath(dataDir));
  const skills = Array.isArray(document?.skills) ? document.skills.filter(isSkillRecord) : [];
  if (!skills.some((skill) => skill.id === skillId)) {
    throw new Error(`Approved Skill not found: ${skillId}`);
  }
}

async function ensureSkillCategory(store, categoryId) {
  const normalized = String(categoryId).trim();
  const categories = await store.listCategories();
  if (categories.some((category) => category.categoryId === normalized)) {
    return;
  }
  await store.upsertCategory({
    categoryId: normalized,
    name: formatGeneratedSkillTaxonomyName(normalized),
  });
}

async function ensureSkillTag(store, tagId) {
  const normalized = String(tagId).trim();
  const tags = await store.listTags();
  if (tags.some((tag) => tag.tagId === normalized)) {
    return;
  }
  await store.upsertTag({
    tagId: normalized,
    name: formatGeneratedSkillTaxonomyName(normalized),
  });
}

function formatGeneratedSkillTaxonomyName(value) {
  return String(value)
    .split(/[-_:]+/u)
    .filter(Boolean)
    .map((part) => part.slice(0, 1).toUpperCase() + part.slice(1))
    .join(" ");
}

async function readJsonOrNull(path) {
  try {
    return JSON.parse(await readFile(path, "utf8"));
  } catch (error) {
    if (error?.code === "ENOENT") {
      return null;
    }
    return {
      readError: error instanceof Error ? error.message : String(error),
    };
  }
}

async function writeJsonDocument(path, document) {
  await mkdir(dirname(path), { recursive: true });
  await writeFile(path, `${JSON.stringify(document, null, 2)}\n`, "utf8");
}

function createCostBudgetDocument(action, author) {
  const limitUsd = requiredNonNegativeNumber(action.limitUsd, "limitUsd");
  const spentUsd = requiredNonNegativeNumber(action.spentUsd, "spentUsd");
  const remainingUsd = Math.max(limitUsd - spentUsd, 0);
  const blocked = action.blocked === undefined ? false : requiredBoolean(action.blocked, "blocked");
  const updatedAt = normalizeOptionalIsoTimestamp(action.now) ?? new Date().toISOString();

  return {
    schemaVersion: "director.cost-budget.v1",
    limitUsd,
    spentUsd,
    remainingUsd,
    blocked,
    updatedAt,
    updatedBy: author,
  };
}

function isSkillRecord(value) {
  return (
    isPlainObject(value) &&
    typeof value.id === "string" &&
    typeof value.title === "string" &&
    typeof value.version === "string" &&
    typeof value.content === "string" &&
    typeof value.updatedAtMs === "number"
  );
}

function formatSkillAsset(
  skill,
  taxonomyDocument = createEmptySkillTaxonomyDocument(),
  managementDocument = null,
  usageRecord = null,
  toolDoctor = createEmptySkillToolDoctorIndex(),
) {
  const tags = uniqueStringArray(
    Array.isArray(skill.tags) ? skill.tags.filter((tag) => typeof tag === "string") : [],
  );
  const toolNames = uniqueStringArray(
    Array.isArray(skill.toolNames)
      ? skill.toolNames.filter((toolName) => typeof toolName === "string")
      : [],
  );
  const metadata = isPlainObject(skill.metadata) ? { ...skill.metadata } : {};
  const source = classifySkillSource(skill, tags, metadata);
  const enablement = resolveSkillEnablement(skill, managementDocument);
  const permissions = deriveSkillPermissions(skill, metadata, toolNames);
  const trustStatus = deriveSkillTrustStatus(skill, source, metadata);
  const auditStatus = deriveSkillAuditStatus(skill, source, metadata, trustStatus);
  const riskLevel = deriveSkillRiskLevel(skill, source, permissions, metadata);
  const modelInvocable = isSkillModelInvocable(skill, metadata);
  const doctor = deriveSkillDoctor({
    toolNames,
    enabled: enablement.enabled,
    modelInvocable,
    toolDoctor,
  });
  const permissionSummary = formatSkillPermissionSummary(permissions);
  const auditSummary = formatSkillAuditSummary({
    source,
    auditStatus,
    trustStatus,
    riskLevel,
    metadata,
  });
  const runtimeStatus = resolveSkillRuntimeStatus({
    enabled: enablement.enabled,
    modelInvocable,
    riskLevel,
    doctor,
  });
  const disabledReason = resolveSkillDisabledReason({
    enabled: enablement.enabled,
    modelInvocable,
    doctor,
    decision: enablement.decision,
  });
  const statusReason = formatSkillStatusReason({
    enabled: enablement.enabled,
    modelInvocable,
    doctor,
    disabledReason,
  });
  const explanationSurface = createSkillExplanationSurface({
    skill: {
      ...skill,
      enabled: enablement.enabled,
      configuredEnabled: enablement.enabled,
      modelInvocable,
      runtimeStatus: runtimeStatus.status,
      doctorStatus: doctor.status,
      doctorSummary: doctor.summary,
      missingToolNames: doctor.missingToolNames,
      availableToolNames: doctor.availableToolNames,
      uncheckedToolNames: doctor.uncheckedToolNames,
      nextActions: doctor.nextActions,
      disabledReason,
    },
  });
  const taxonomyBinding = resolveSkillTaxonomyBinding(taxonomyDocument, skill.id);
  const taxonomyCategory = resolveSkillTaxonomyCategory(taxonomyDocument, taxonomyBinding);
  const taxonomyTags = resolveSkillTaxonomyTags(taxonomyDocument, taxonomyBinding);
  const category = taxonomyCategory ?? inferSkillCategory(skill, { tags, toolNames, metadata });
  const priority = readFiniteNumber(skill.priority);
  const limitedContent = limitDesktopTextContent(
    skill.content,
    MAX_DESKTOP_SKILL_CONTENT_CHARS,
    "Skill 正文",
  );
  return {
    id: skill.id,
    title: skill.title,
    version: skill.version,
    source,
    enabled: enablement.enabled,
    configuredEnabled: enablement.enabled,
    modelInvocable,
    enablementStatus: enablement.enabled ? "enabled" : "disabled",
    enablementDecision: enablement.decision,
    disabledReason,
    eligible: runtimeStatus.eligible,
    modelVisible: runtimeStatus.modelVisible,
    userInvocable: enablement.enabled,
    commandVisible: true,
    permissionStatus: runtimeStatus.permissionStatus,
    runtimeStatus: runtimeStatus.status,
    statusReason,
    explanationSurface,
    doctorStatus: doctor.status,
    doctorSummary: doctor.summary,
    missingToolNames: doctor.missingToolNames,
    availableToolNames: doctor.availableToolNames,
    uncheckedToolNames: doctor.uncheckedToolNames,
    nextActions: doctor.nextActions,
    snapshotVersion: managementDocument?.updatedAtMs ?? skill.updatedAtMs,
    chineseIntro: createSkillChineseIntro({
      skill,
      source,
      category,
      riskLevel,
      trustStatus,
      permissions,
      enabled: enablement.enabled,
    }),
    category,
    categoryId: category.categoryId,
    tags,
    taxonomyTags: taxonomyTags.length > 0 ? taxonomyTags : tags.map(createSkillTaxonomyTag),
    toolNames,
    toolCount: toolNames.length,
    permissions,
    permissionSummary,
    riskLevel,
    trustStatus,
    auditStatus,
    auditSummary,
    updatedAtMs: skill.updatedAtMs,
    description: typeof skill.description === "string" ? skill.description : "",
    content: limitedContent.content,
    contentChars: skill.content.length,
    contentTruncated: limitedContent.truncated,
    metadata,
    usage: normalizeSkillUsageAsset(usageRecord),
    taxonomyBinding,
    ...(priority === null ? {} : { priority }),
    sourceDocument: formatSkillSourceDocument(skill, skill.content),
  };
}

function isSkillModelInvocable(skill, metadata = isPlainObject(skill?.metadata) ? skill.metadata : {}) {
  return skill?.disableModelInvocation !== true && metadata.disableModelInvocation !== true;
}

function resolveSkillRuntimeStatus({ enabled, modelInvocable, riskLevel, doctor }) {
  if (!enabled) {
    return {
      status: "disabled",
      eligible: false,
      modelVisible: false,
      permissionStatus: "disabled",
    };
  }
  if (!modelInvocable) {
    return {
      status: "model-invocation-disabled",
      eligible: false,
      modelVisible: false,
      permissionStatus: "model-invocation-disabled",
    };
  }
  if (doctor?.status === "needs-setup") {
    return {
      status: "needs-setup",
      eligible: false,
      modelVisible: false,
      permissionStatus: "needs-setup",
    };
  }
  return {
    status: "ready",
    eligible: true,
    modelVisible: true,
    permissionStatus: riskLevel === "high" ? "approval-required" : "allowed",
  };
}

function resolveSkillDisabledReason({ enabled, modelInvocable, doctor, decision }) {
  if (!enabled) {
    return decision?.note ?? "已被操作员关闭";
  }
  if (!modelInvocable) {
    return "该 Skill 标记为 disableModelInvocation，不能由模型在对话中直接调用。";
  }
  if (doctor?.status === "needs-setup") {
    return doctor.summary;
  }
  return "";
}

function formatSkillStatusReason({ enabled, modelInvocable, doctor, disabledReason }) {
  if (!enabled) {
    return "已关闭，不会进入模型可见 Skill 索引。";
  }
  if (!modelInvocable) {
    return `${disabledReason}仍可在管理页查看和维护，但普通对话不会自动加载或执行。`;
  }
  if (doctor?.status === "needs-setup") {
    return `${disabledReason} 先完成工具配置后，才会进入模型可见 Skill 索引。`;
  }
  return "已开启，可进入后续能力召回。";
}

function resolveSkillEnablement(skill, managementDocument) {
  const explicitEnabled =
    typeof skill.enabled === "boolean"
      ? skill.enabled
      : skill.enablementStatus === "disabled"
        ? false
        : undefined;
  const decisions = Array.isArray(managementDocument?.decisions)
    ? managementDocument.decisions
    : [];
  const decision = decisions.find((entry) => entry?.skillId === skill.id) ?? null;
  const disabledSkillIds = Array.isArray(managementDocument?.disabledSkillIds)
    ? managementDocument.disabledSkillIds
    : [];
  const enabled =
    typeof decision?.enabled === "boolean"
      ? decision.enabled
      : disabledSkillIds.includes(skill.id)
        ? false
        : (explicitEnabled ?? true);
  return {
    enabled,
    decision,
  };
}

function normalizeSkillUsageAsset(usageRecord) {
  if (!isPlainObject(usageRecord)) {
    return {
      viewCount: 0,
      useCount: 0,
      patchCount: 0,
      lastActivityAtMs: null,
      lastViewedAtMs: null,
      lastUsedAtMs: null,
      lastPatchedAtMs: null,
      state: "active",
      pinned: false,
    };
  }
  return {
    viewCount: readFiniteNumber(usageRecord.viewCount) ?? 0,
    useCount: readFiniteNumber(usageRecord.useCount) ?? 0,
    patchCount: readFiniteNumber(usageRecord.patchCount) ?? 0,
    lastActivityAtMs: readFiniteNumber(usageRecord.lastActivityAtMs),
    lastViewedAtMs: readFiniteNumber(usageRecord.lastViewedAtMs),
    lastUsedAtMs: readFiniteNumber(usageRecord.lastUsedAtMs),
    lastPatchedAtMs: readFiniteNumber(usageRecord.lastPatchedAtMs),
    state:
      usageRecord.state === "stale" || usageRecord.state === "archived"
        ? usageRecord.state
        : "active",
    pinned: usageRecord.pinned === true,
  };
}

function createSkillChineseIntro({
  skill,
  source,
  category,
  riskLevel,
  trustStatus,
  permissions,
  enabled,
}) {
  const sourceLabel = source === "self" ? "自进化 Skill" : "外部 Skill";
  const base =
    typeof skill.description === "string" && skill.description.trim().length > 0
      ? `${sourceLabel}：${skill.description.trim()}`
      : `${sourceLabel}，用于${category?.name ?? "通用"}相关任务。`;
  const status = enabled ? "当前已开启，可被后续制作召回。" : "当前已关闭，后续制作不会召回。";
  const trust = trustStatus === "trusted" ? "已信任" : "未信任";
  const permissionCopy =
    permissions.length === 0
      ? "未声明工具权限"
      : uniqueStringArray(permissions.map((permission) => permission.label)).join("、");
  return `${base} 来源：${source === "self" ? "自我进化" : "外部导入"}；风险：${formatSkillRiskText(riskLevel)}；信任：${trust}；权限：${permissionCopy}；${status}`;
}

function formatSkillRiskText(riskLevel) {
  return (
    {
      low: "低",
      medium: "中",
      high: "高",
    }[riskLevel] ?? "未知"
  );
}

function classifySkillSource(skill, tags, metadata) {
  const selfMarkers = [
    metadata.sourceTurnId,
    metadata.digestId,
    metadata.candidateId,
    tags.includes("worker-generated"),
    tags.includes("trajectory-analysis"),
  ];
  return selfMarkers.some(Boolean) ? "self" : "external";
}

function deriveSkillPermissions(skill, metadata, toolNames) {
  const declaredPermissions = Array.isArray(skill.permissions)
    ? skill.permissions
    : Array.isArray(metadata.permissions)
      ? metadata.permissions
      : [];
  const normalized = declaredPermissions
    .filter(isPlainObject)
    .map((permission) => normalizeSkillPermission(permission))
    .filter(Boolean);

  if (normalized.length > 0) {
    return normalized;
  }

  return toolNames.map(mapToolNameToSkillPermission);
}

function normalizeSkillPermission(permission) {
  const kind = readStringProperty(permission, "kind") ?? readStringProperty(permission, "scope");
  if (kind === null) {
    return null;
  }
  const riskLevel = readSkillRiskLevel(permission) ?? "low";
  return {
    kind,
    label: readStringProperty(permission, "label") ?? formatSkillPermissionKind(kind),
    riskLevel,
    toolName: readStringProperty(permission, "toolName"),
  };
}

function mapToolNameToSkillPermission(toolName) {
  const normalized = String(toolName).trim();
  const lower = normalized.toLowerCase();

  if (/^(rg|grep|find|cat|sed|awk|ls|fd)$/u.test(lower)) {
    return {
      kind: "filesystem.read",
      label: "读取文件",
      riskLevel: "low",
      toolName: normalized,
    };
  }

  if (/^(apply_patch|write|edit)$/u.test(lower)) {
    return {
      kind: "filesystem.write",
      label: "写入文件",
      riskLevel: "medium",
      toolName: normalized,
    };
  }

  if (/^(browser|fetch|curl|wget|web)$/u.test(lower)) {
    return {
      kind: "network.request",
      label: "网络请求",
      riskLevel: "medium",
      toolName: normalized,
    };
  }

  if (/^(node|python|pnpm|npm|bun|git|bash|sh|zsh)$/u.test(lower)) {
    return {
      kind: "command.execute",
      label: "执行命令",
      riskLevel: "medium",
      toolName: normalized,
    };
  }

  return {
    kind: "tool.use",
    label: "工具调用",
    riskLevel: "low",
    toolName: normalized,
  };
}

function deriveSkillTrustStatus(skill, source, metadata) {
  const explicit =
    readStringProperty(skill, "trustStatus") ?? readStringProperty(metadata, "trustStatus");
  if (explicit === "trusted" || explicit === "untrusted") {
    return explicit;
  }
  const auditStatus =
    readStringProperty(skill, "auditStatus") ?? readStringProperty(metadata, "auditStatus");
  if (["approved", "trusted", "reviewed", "accepted"].includes(auditStatus)) {
    return "trusted";
  }
  return source === "self" ? "trusted" : "untrusted";
}

function deriveSkillAuditStatus(skill, source, metadata, trustStatus) {
  const explicit =
    readStringProperty(skill, "auditStatus") ?? readStringProperty(metadata, "auditStatus");
  if (explicit === "self-evolved" || explicit === "reviewed" || explicit === "untrusted") {
    return explicit;
  }
  if (["approved", "trusted", "accepted"].includes(explicit) || trustStatus === "trusted") {
    return source === "self" ? "self-evolved" : "reviewed";
  }
  return "untrusted";
}

function deriveSkillRiskLevel(skill, source, permissions, metadata) {
  const explicit = readSkillRiskLevel(skill) ?? readSkillRiskLevel(metadata);
  if (explicit !== null) {
    return explicit;
  }
  if (permissions.some((permission) => permission.riskLevel === "high")) {
    return "high";
  }
  const hasMediumPermission = permissions.some((permission) => permission.riskLevel === "medium");
  if (source === "external" && hasMediumPermission) {
    return "high";
  }
  if (source === "external" || hasMediumPermission) {
    return "medium";
  }
  return "low";
}

function readSkillRiskLevel(value) {
  const riskLevel = readStringProperty(value, "riskLevel") ?? readStringProperty(value, "risk");
  return riskLevel === "low" || riskLevel === "medium" || riskLevel === "high" ? riskLevel : null;
}

function formatSkillPermissionSummary(permissions) {
  if (permissions.length === 0) {
    return "未声明工具权限";
  }
  return uniqueStringArray(permissions.map((permission) => permission.label)).join(", ");
}

function formatSkillAuditSummary({ source, auditStatus, trustStatus, riskLevel, metadata }) {
  const evidence = [
    readStringProperty(metadata, "sourceTurnId"),
    readStringProperty(metadata, "candidateId"),
    readStringProperty(metadata, "proposalId"),
  ].filter(Boolean);
  if (source === "self") {
    return `自进化 Skill；审计=${auditStatus}；信任=${trustStatus}；风险=${riskLevel}${
      evidence.length > 0 ? `；来源=${evidence.join(",")}` : ""
    }。`;
  }
  if (auditStatus === "reviewed") {
    return `外部 Skill 已有审核标记；信任=${trustStatus}；风险=${riskLevel}。`;
  }
  return `外部 Skill 默认不可信；信任=${trustStatus}；风险=${riskLevel}；使用前需要核对来源、权限和适用范围。`;
}

function formatSkillPermissionKind(kind) {
  const labels = {
    "filesystem.read": "读取文件",
    "filesystem.write": "写入文件",
    "network.request": "网络请求",
    "command.execute": "执行命令",
    "tool.use": "工具调用",
  };
  return labels[kind] ?? kind;
}

function formatSkillSourceDocument(skill, content) {
  const metadata = isPlainObject(skill.metadata) ? skill.metadata : {};
  const sourceRef =
    readStringProperty(metadata, "sourceRef") ??
    readStringProperty(metadata, "sourcePath") ??
    readStringProperty(metadata, "proposalId") ??
    skill.id;
  const limited = limitDesktopTextContent(content, MAX_DESKTOP_SKILL_CONTENT_CHARS, "Skill 正文");
  return {
    title: skill.title,
    sourceRef,
    sourceKind: "approved-skill",
    contentType: "text/markdown",
    bytes: Buffer.byteLength(content, "utf8"),
    content: limited.content,
    originalChars: content.length,
    truncated: limited.truncated,
    isFullContent: !limited.truncated,
  };
}

function inferSkillCategory(skill, { tags, toolNames, metadata }) {
  const metadataCategory = readSkillMetadataCategory(metadata);
  if (metadataCategory !== null) {
    return createSkillCategory(metadataCategory, "metadata");
  }

  const tagCategory = readSkillTagCategory(tags);
  if (tagCategory !== null) {
    return createSkillCategory(tagCategory, "tag");
  }

  const haystack = [skill.id, skill.title, skill.description, skill.content, ...tags, ...toolNames]
    .filter((value) => typeof value === "string")
    .join(" ")
    .toLowerCase();
  const inferred = inferSkillCategoryIdFromText(haystack);
  return createSkillCategory(inferred, "inferred");
}

function readSkillMetadataCategory(metadata) {
  for (const key of ["category", "categoryId", "domain", "area"]) {
    const value = readStringProperty(metadata, key);
    if (value !== null && value.trim().length > 0) {
      return value;
    }
  }
  const taxonomy = isPlainObject(metadata.taxonomy) ? metadata.taxonomy : null;
  const taxonomyCategory = readStringProperty(taxonomy, "categoryId");
  return taxonomyCategory !== null && taxonomyCategory.trim().length > 0 ? taxonomyCategory : null;
}

function readSkillTagCategory(tags) {
  for (const tag of tags) {
    const match = /^(?:category|domain|area):(.+)$/u.exec(tag);
    if (match?.[1]?.trim()) {
      return match[1].trim();
    }
  }
  return null;
}

function inferSkillCategoryIdFromText(haystack) {
  const checks = [
    ["frontend", /\b(frontend|ui|react|vue|svelte|css|browser|dom)\b/u],
    ["backend", /\b(backend|api|server|database|postgres|sql|queue|worker)\b/u],
    ["testing", /\b(test|testing|vitest|jest|playwright|e2e|tdd|coverage)\b/u],
    ["documentation", /\b(document|documentation|docs|readme|article|writing|guide)\b/u],
    ["security", /\b(security|auth|oauth|permission|secret|token|vulnerability)\b/u],
    ["delivery", /\b(deploy|deployment|release|ci|cd|docker|build)\b/u],
    ["research", /\b(research|search|market|competitive|source|evidence)\b/u],
    ["agent", /\b(agent|llm|model|prompt|tool|mcp|skill)\b/u],
    ["review", /\b(review|quality|compliance|audit|proposal|approval)\b/u],
  ];
  return checks.find(([, pattern]) => pattern.test(haystack))?.[0] ?? "general";
}

function createSkillCategory(value, source) {
  const trimmed = String(value).trim();
  const categoryId = sanitizeSkillTaxonomyId(trimmed || "general");
  return {
    categoryId,
    id: categoryId,
    name: trimmed || "general",
    source,
  };
}

function createSkillTaxonomyTag(tag) {
  const name = String(tag).trim();
  const tagId = sanitizeSkillTaxonomyId(name);
  return {
    tagId,
    id: tagId,
    name,
    source: "skill-tag",
  };
}

function resolveSkillTaxonomyBinding(taxonomyDocument, skillId) {
  const binding = taxonomyDocument?.skills?.find((entry) => entry.skillId === skillId);
  if (!isPlainObject(binding)) {
    return null;
  }
  return {
    skillId,
    ...(typeof binding.categoryId === "string" && binding.categoryId.length > 0
      ? { categoryId: binding.categoryId }
      : {}),
    tagIds: Array.isArray(binding.tagIds)
      ? binding.tagIds.filter((tagId) => typeof tagId === "string")
      : [],
    updatedAtMs: readFiniteNumber(binding.updatedAtMs),
    ...(typeof binding.updatedBy === "string" ? { updatedBy: binding.updatedBy } : {}),
  };
}

function resolveSkillTaxonomyCategory(taxonomyDocument, binding) {
  if (!binding?.categoryId) {
    return null;
  }
  const stored = taxonomyDocument?.categories?.find(
    (category) => category.categoryId === binding.categoryId,
  );
  return {
    categoryId: binding.categoryId,
    id: binding.categoryId,
    name: stored?.name ?? binding.categoryId,
    source: "taxonomy",
  };
}

function resolveSkillTaxonomyTags(taxonomyDocument, binding) {
  const tagIds = binding?.tagIds ?? [];
  if (tagIds.length === 0) {
    return [];
  }
  return tagIds.map((tagId) => {
    const stored = taxonomyDocument?.tags?.find((tag) => tag.tagId === tagId);
    return {
      tagId,
      id: tagId,
      name: stored?.name ?? tagId,
      source: stored === undefined ? "taxonomy-binding" : "taxonomy",
    };
  });
}

function createSkillTaxonomy(items, categories, taxonomyDocument, readError = null) {
  const tagCounts = new Map();
  for (const item of items) {
    for (const tag of item.taxonomyTags) {
      const current = tagCounts.get(tag.tagId) ?? {
        tagId: tag.tagId,
        id: tag.tagId,
        name: tag.name,
        count: 0,
      };
      current.count += 1;
      tagCounts.set(tag.tagId, current);
    }
  }

  for (const tag of taxonomyDocument?.tags ?? []) {
    if (!tagCounts.has(tag.tagId)) {
      tagCounts.set(tag.tagId, {
        tagId: tag.tagId,
        id: tag.tagId,
        name: tag.name,
        count: 0,
      });
    }
  }

  return {
    schemaVersion: "director.skills.taxonomy.v1",
    sourceSchemaVersion: taxonomyDocument?.schemaVersion ?? null,
    readError,
    categories: mergeSkillTaxonomyCategories(items, categories, taxonomyDocument),
    tags: [...tagCounts.values()].sort(compareSkillGroup),
  };
}

function mergeSkillTaxonomyCategories(items, categories, taxonomyDocument) {
  const byId = new Map();
  for (const category of taxonomyDocument?.categories ?? []) {
    byId.set(category.categoryId, {
      categoryId: category.categoryId,
      id: category.categoryId,
      name: category.name,
      count: category.categoryId === "all" ? items.length : 0,
      selfCount: 0,
      externalCount: 0,
    });
  }
  for (const category of categories) {
    const current = byId.get(category.id) ?? {
      categoryId: category.id,
      id: category.id,
      name: category.label,
      count: 0,
      selfCount: 0,
      externalCount: 0,
    };
    byId.set(category.id, {
      ...current,
      name: current.name ?? category.label,
      count: category.count,
      selfCount: category.selfCount,
      externalCount: category.externalCount,
    });
  }
  return [...byId.values()].sort(compareSkillGroup);
}

function groupSkillsByCategory(items) {
  const groups = new Map();
  for (const item of items) {
    const current = groups.get(item.category.categoryId) ?? {
      id: item.category.categoryId,
      categoryId: item.category.categoryId,
      label: item.category.name,
      name: item.category.name,
      count: 0,
      selfCount: 0,
      externalCount: 0,
      toolCount: 0,
    };
    current.count += 1;
    current.selfCount += item.source === "self" ? 1 : 0;
    current.externalCount += item.source === "external" ? 1 : 0;
    current.toolCount += item.toolNames.length;
    groups.set(item.category.categoryId, current);
  }
  return [...groups.values()].sort(compareSkillGroup);
}

function groupSkillsBySource(items) {
  const groups = new Map();
  for (const item of items) {
    const current = groups.get(item.source) ?? {
      id: item.source,
      label: item.source === "self" ? "Self-evolved" : "External",
      count: 0,
      categoryCount: 0,
      toolCount: 0,
    };
    current.count += 1;
    current.toolCount += item.toolNames.length;
    groups.set(item.source, current);
  }
  for (const group of groups.values()) {
    group.categoryCount = new Set(
      items.filter((item) => item.source === group.id).map((item) => item.category.categoryId),
    ).size;
  }
  return [...groups.values()].sort(compareSkillGroup);
}

function collectSkillToolNames(items) {
  return uniqueStringArray(items.flatMap((item) => item.toolNames)).sort(compareStrings);
}

function collectSkillTagNames(items) {
  return uniqueStringArray(items.flatMap((item) => item.tags)).sort(compareStrings);
}

function uniqueStringArray(values) {
  const seen = new Set();
  const result = [];
  for (const value of values) {
    const normalized = typeof value === "string" ? value.trim() : "";
    if (normalized.length === 0 || seen.has(normalized)) {
      continue;
    }
    seen.add(normalized);
    result.push(normalized);
  }
  return result;
}

function sanitizeSkillTaxonomyId(value) {
  const sanitized = value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9._:-]+/gu, "-")
    .replace(/^-+|-+$/gu, "");
  return sanitized || "general";
}

function compareSkillGroup(left, right) {
  if (right.count !== left.count) {
    return right.count - left.count;
  }
  return compareStrings(left.name ?? left.label ?? left.id, right.name ?? right.label ?? right.id);
}

function compareExternalToolItems(left, right) {
  if (left.registered !== right.registered) {
    return left.registered ? -1 : 1;
  }
  if (left.enabled !== right.enabled) {
    return left.enabled ? -1 : 1;
  }
  return compareStrings(left.title ?? left.id, right.title ?? right.id);
}

function compareStrings(left, right) {
  return String(left).localeCompare(String(right));
}

function isPlainObject(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function createRecallCopy({ enabled, publishedCount, recall }) {
  if (!enabled) {
    return publishedCount > 0
      ? "召回已关闭；已发布经验会保留，但不会进入运行时召回。"
      : "召回已关闭；经验发布后仍会保留，开启后才能进入运行时召回。";
  }
  if (recall?.packet) {
    if (recall.packet.status === "hit") {
      return `召回命中 ${recall.packet.hits.length} 条已发布经验。`;
    }
    return "召回已启用，但当前查询没有命中已发布经验。";
  }
  return publishedCount > 0
    ? "已发布经验可进入运行时召回；执行召回预览后会显示命中结果。"
    : "经验需要接受、晋升并发布后，才能进入运行时召回。";
}

function createRecallEvent(recall, actionType) {
  if (!recall.enabled || recall.packet === null) {
    return createEvent("Recall Preview", "召回未启用，无法预览已发布经验。", actionType);
  }
  if (recall.packet.hits.length === 0) {
    return createEvent("Recall Preview", "召回已启用，但当前查询没有命中。", actionType);
  }
  const hitIds = recall.packet.hits.map((hit) => hit.knowledgePackId).join(", ");
  return createEvent("Recall Preview", `召回命中：${hitIds}`, actionType);
}

function formatApiProviderRunEventBody(runResult) {
  const status = runResult.status === undefined ? "" : `HTTP ${runResult.status} · `;
  const output = typeof runResult.output === "string" ? runResult.output.trim() : "";
  if (runResult.ok && output.length > 0) {
    return `${runResult.providerId} · ${runResult.model} · ${status}${runResult.latencyMs}ms\n${output}`;
  }
  return `${runResult.providerId} · ${runResult.model} · ${status}${runResult.latencyMs}ms\n${runResult.message}`;
}

