function createComfyUiWorkflowDraft({
  objective,
  workflowKind,
  workflowModes,
  author,
  now,
  angelDraft = null,
}) {
  const createdAt = normalizeComfyUiDraftTimestamp(now);
  const normalizedWorkflowModes = normalizeComfyUiDraftWorkflowModes(workflowModes, workflowKind);
  const id = `comfyui-${normalizedWorkflowModes.join("-")}-${Date.parse(createdAt)}-${sanitizeComfyUiWorkflowSlug(
    objective,
  )}`;
  return {
    schemaVersion: 1,
    id,
    kind: workflowKind,
    workflowModes: normalizedWorkflowModes,
    objective,
    status: "draft",
    executable: false,
    createdAt,
    author,
    requires: [
      "Angel output review",
      "ComfyUI node parameter mapping",
      "operator review before execution",
    ],
    boundary:
      "Director Angel generates content and parameters first. ComfyUI is the external canvas/executor and should receive mapped workflow data.",
    workflowPlan: createComfyUiWorkflowPlan(
      workflowKind,
      objective,
      angelDraft,
      normalizedWorkflowModes,
    ),
    angelOutput: angelDraft?.output ?? "",
    angelSource: angelDraft?.source ?? "api-provider-unavailable",
    knowledgeHits: angelDraft?.knowledgeHits ?? [],
    skillHits: angelDraft?.skillHits ?? [],
    recallTrace: angelDraft?.recallTrace ?? [],
    capabilityPlan: angelDraft?.capabilityPlan ?? [],
    toolParameters: angelDraft?.toolParameters ?? [],
    handoffNotes:
      angelDraft?.handoffNotes ?? createComfyUiHandoffNotes(workflowKind, normalizedWorkflowModes),
    angel: {
      output: angelDraft?.output ?? "",
      source: angelDraft?.source ?? "api-provider-unavailable",
      status: angelDraft?.status ?? "degraded",
      providerId: angelDraft?.providerId ?? null,
      model: angelDraft?.model ?? null,
      message: angelDraft?.message ?? null,
      blueprintId: angelDraft?.blueprintId ?? null,
      recallStatus: angelDraft?.recallStatus ?? "miss",
      skillStatus: angelDraft?.skillStatus ?? "miss",
      visibleSummary: angelDraft?.visibleSummary ?? "未召回额外上下文。",
      knowledgeHits: angelDraft?.knowledgeHits ?? [],
      skillHits: angelDraft?.skillHits ?? [],
      recallTrace: angelDraft?.recallTrace ?? [],
      capabilityPlan: angelDraft?.capabilityPlan ?? [],
    },
    apiWorkflow: null,
    notes: [
      "Angel owns learning, content generation, and parameter planning.",
      "ComfyUI owns workflow display and configured media execution.",
      "Use /comfyui 打开界面 to open ComfyUI, and /comfyui <prompt> only when an executable API workflow JSON is configured.",
    ],
  };
}

async function uploadComfyUiWorkflowToUserData({
  baseUrl,
  mode,
  userDataPath,
  workflow,
  fetchImpl,
}) {
  const endpoint = buildComfyUiUserDataEndpoint(baseUrl, mode, userDataPath);
  const fetcher = fetchImpl ?? globalThis.fetch;
  if (typeof fetcher !== "function") {
    return {
      ok: false,
      endpoint,
      message: "当前运行环境没有 fetch，无法写入 ComfyUI 工作流列表。",
    };
  }

  try {
    const response = await fetcher(endpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(workflow, null, 2),
    });
    const body = await response.text();
    return {
      ok: response.ok,
      endpoint,
      status: response.status,
      statusText: response.statusText,
      body,
      message: response.ok
        ? `ComfyUI 已保存 ${userDataPath}。`
        : `ComfyUI 保存失败：HTTP ${response.status} ${response.statusText || ""}`.trim(),
    };
  } catch (error) {
    return {
      ok: false,
      endpoint,
      message: `ComfyUI 保存失败：${toErrorMessage(error)}`,
    };
  }
}

function buildComfyUiUserDataEndpoint(baseUrl, mode, userDataPath) {
  const normalized = String(baseUrl ?? "http://127.0.0.1:8188").replace(/\/+$/u, "");
  const prefix = mode === "cloud" ? "/api/userdata" : "/userdata";
  return `${normalized}${prefix}/${encodeURIComponent(userDataPath)}?overwrite=true&full_info=true`;
}

function formatComfyUiWorkflowDraftMessage({ upload, comfyUiPath, openMessage, templateBridge }) {
  if (!upload.ok) {
    return `Angel 已生成内容和参数，已保存本地工作流；同步到 ComfyUI 失败：${upload.message}。`;
  }
  if (templateBridge?.directOpenReady) {
    return "已创建完整 ComfyUI 工作流，并已尝试直接打开画布。";
  }
  if (templateBridge?.ok) {
    return "已创建完整 ComfyUI 工作流；如果页面没有自动显示，请在 Workflows / DirectorAngel 中打开。";
  }
  return "已创建完整 ComfyUI 工作流；请在 ComfyUI 的 Workflows / DirectorAngel 中查看。";
}

function createComfyUiWorkflowPlan(
  workflowKind,
  objective,
  angelDraft = null,
  workflowModes = null,
) {
  const modes = normalizeComfyUiDraftWorkflowModes(workflowModes, workflowKind);
  if (modes.includes("script") && (modes.includes("image") || modes.includes("video"))) {
    return [
      {
        id: "input-story-objective",
        role: "input",
        description: "接收故事主题、时长、角色、风格和限制。",
      },
      {
        id: "angel-script-and-parameter-planner",
        role: "angel",
        description: "Angel 先生成脚本，再拆出图片/视频提示词和参数。",
      },
      {
        id: "comfyui-script-preview",
        role: "text",
        requiredNode: "PrimitiveStringMultiline + PreviewAny",
        description: `把 Angel 脚本写入 ComfyUI 文本预览链（${angelDraft?.toolParameters?.length ?? 0} 项参数）。`,
      },
      ...(modes.includes("image")
        ? [
            {
              id: "comfyui-image-branch",
              role: "media",
              requiredNode: "WanTextToImageApi + SaveImage",
              description: "把 Angel 图片提示词映射到文生图节点并保存图片。",
            },
          ]
        : []),
      ...(modes.includes("video")
        ? [
            {
              id: "comfyui-video-branch",
              role: "media",
              requiredNode: modes.includes("image")
                ? "Wan2ImageToVideoApi + SaveVideo"
                : "WanTextToVideoApi + SaveVideo",
              description: modes.includes("image")
                ? "把本场景图片输出接入本场景图生视频节点，并只注入当前场景视频提示词。"
                : "把 Angel 视频提示词按场景拆分到文生视频节点并保存片段。",
            },
          ]
        : []),
    ];
  }
  if (workflowKind === "copywriting") {
    return [
      {
        id: "input-brief",
        role: "input",
        description: "接收文案目标、平台、受众和约束。",
      },
      {
        id: "angel-copywriter",
        role: "angel",
        description: "Angel 根据经验和 Skill 生成文案正文与字幕/画面参数。",
      },
      {
        id: "comfyui-text-handoff",
        role: "output",
        description: "把 Angel 文案 payload 写入 ComfyUI 画布，后续可接字幕或媒体节点。",
      },
    ];
  }
  if (workflowKind === "image" || workflowKind === "video") {
    return [
      {
        id: "input-prompt",
        role: "input",
        description: "接收视觉生成目标和风格约束。",
      },
      {
        id: "angel-parameter-planner",
        role: "angel",
        description:
          workflowKind === "image"
            ? "Angel 生成正负提示词、构图、光影、尺寸、采样和 seed 等参数。"
            : "Angel 生成镜头段落、运动方式、关键帧提示词、时长、fps 和 seed 等参数。",
      },
      {
        id: "comfyui-media-handoff",
        role: "media",
        requiredNode:
          workflowKind === "image" ? "text-to-image API workflow" : "text-to-video API workflow",
        description: "把 Angel 参数映射到真实 ComfyUI API workflow 后再提交执行。",
      },
    ];
  }
  return [
    {
      id: "input-story-objective",
      role: "input",
      description: "接收故事主题、时长、角色、风格和限制。",
    },
    {
      id: "angel-script-writer",
      role: "angel",
      description: "Angel 根据经验和 Skill 生成脚本、对白、分镜和后续媒体提示词拆分。",
    },
    {
      id: "parameter-structure",
      role: "transform",
      description: `把 Angel 输出整理为 ComfyUI 可承载的文本 payload 和参数清单（${angelDraft?.toolParameters?.length ?? 0} 项）。`,
    },
    {
      id: "comfyui-canvas-handoff",
      role: "output",
      description: "写入 ComfyUI 可见画布，等待审核或继续接媒体执行节点。",
    },
  ];
}

function normalizeComfyUiDraftWorkflowKind(value) {
  const normalized = String(value ?? "script")
    .trim()
    .toLowerCase();
  if (["copywriting", "image", "video"].includes(normalized)) {
    return normalized;
  }
  return "script";
}

function normalizeComfyUiDraftWorkflowModes(value, workflowKind = "script") {
  const raw = Array.isArray(value) ? value : [];
  const modes = raw
    .map((item) =>
      String(item ?? "")
        .trim()
        .toLowerCase(),
    )
    .filter((item) => ["script", "image", "video"].includes(item));
  if (modes.length > 0) {
    return [...new Set(modes)];
  }
  if (workflowKind === "image") {
    return ["image"];
  }
  if (workflowKind === "video") {
    return ["video"];
  }
  return ["script"];
}

function normalizeComfyUiDraftTimestamp(value) {
  const date =
    typeof value === "string" || typeof value === "number" ? new Date(value) : new Date();
  if (Number.isNaN(date.getTime())) {
    return new Date().toISOString();
  }
  return date.toISOString();
}

function sanitizeComfyUiWorkflowSlug(value) {
  const sanitized = String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/gu, "-")
    .replace(/^-+|-+$/gu, "")
    .slice(0, 48);
  return sanitized || "draft";
}

function formatComfyUiRunEventBody(runResult) {
  const status = runResult.status === undefined ? "" : `HTTP ${runResult.status} · `;
  const artifacts = (runResult.artifacts ?? [])
    .map((artifact) => artifact.localPath ?? artifact.url ?? artifact.filename)
    .filter(Boolean)
    .join("\n");
  const diagnostics = [
    `执行类型：${formatComfyUiReadiness(runResult.readiness)}`,
    ...(runResult.diagnostics ?? []).map((line) => `诊断：${line}`),
  ].join("\n");
  if (runResult.ok && artifacts.length > 0) {
    if (runResult.promptApplied === false) {
      return `ComfyUI · ${status}${runResult.latencyMs}ms\n${diagnostics}\n${runResult.message}\n${artifacts}`;
    }
    return `ComfyUI · ${status}${runResult.latencyMs}ms\n${diagnostics}\n${artifacts}`;
  }
  return `ComfyUI · ${status}${runResult.latencyMs}ms\n${diagnostics}\n${runResult.message}`;
}

function formatComfyUiRunEventTitle(runResult) {
  if (!runResult.ok) {
    return "ComfyUI 未完成生成";
  }
  if (runResult.readiness === "connectivity_check" || runResult.promptApplied === false) {
    return "ComfyUI 连通性验证完成";
  }
  return "ComfyUI 生成完成";
}

function createComfyUiOpenEvent(result, actionType) {
  return createEvent(
    result.ok ? "ComfyUI 界面已打开" : "ComfyUI 界面打开失败",
    `${result.message}\n${result.url}`,
    actionType,
  );
}

function createComfyUiWorkflowEvent(result, actionType) {
  const lines = [
    result.message,
    `目标：${result.objective}`,
    `类型：${formatComfyUiWorkflowKind(result.workflowKind)}`,
    `组合：${formatComfyUiWorkflowModes(result.workflowModes)}`,
    result.ok
      ? result.uploadedToComfyUi
        ? result.directOpenReady
          ? "画布：已尝试直接打开到这条工作流。"
          : "画布：已同步到 ComfyUI，请在 Workflows / DirectorAngel 中查看。"
        : "画布：已保存本地草案，等 ComfyUI 恢复后可重新同步。"
      : "画布：未创建。",
    "下一步：检查节点、模型和输出目录，确认后再执行。",
  ];
  return createEvent(
    result.ok ? "ComfyUI 工作流已创建" : "ComfyUI 工作流创建失败",
    lines.filter(Boolean).join("\n"),
    actionType,
  );
}

function formatComfyUiWorkflowKind(workflowKind) {
  const labels = {
    script: "脚本",
    copywriting: "文案",
    image: "图片",
    video: "视频",
  };
  return labels[workflowKind] ?? workflowKind ?? "未知";
}

function formatComfyUiWorkflowModes(workflowModes) {
  const labels = {
    script: "脚本",
    image: "图片",
    video: "视频",
  };
  const modes = Array.isArray(workflowModes) ? workflowModes : [];
  return (
    modes
      .map((mode) => labels[mode] ?? mode)
      .filter(Boolean)
      .join("+") || "脚本"
  );
}

function formatComfyUiReadiness(readiness) {
  if (readiness === "generation") {
    return "真实生成";
  }
  if (readiness === "connectivity_check") {
    return "连通性验证";
  }
  return "未就绪";
}

function createLearningEvent(title, source, output, actionType) {
  const newCandidates = extractLearningCount(output, "new candidates");
  const distillation = formatLearningDistillationStatus(
    extractLearningValue(output, "model distillation"),
  );
  const reasons = extractLearningReasonLines(output);
  const projection = createDesktopLearningProjection({
    source: inferDesktopLearningSourceKind(source),
    query: source,
    candidateCount: newCandidates ?? 0,
    failures: reasons.map((reason) => ({
      reason,
      detail: reason,
    })),
  });
  const body =
    distillation.length === 0 ? projection.userText : `${projection.userText}\n${distillation}`;
  return createEvent(
    title,
    body,
    actionType,
  );
}

function createDesktopLearningProjection(input) {
  const projection = createConversationRuntimeLearningArtifactProjection({
    source: input.source,
    ...(input.query === undefined ? {} : { query: input.query }),
    candidateCount: input.candidateCount ?? readLearningCandidateCount(input.result),
    candidates: extractDesktopLearningProjectionCandidates(input.result),
    failureCount:
      input.failureCount ??
      readLearningFailureCount(input.result) ??
      (Array.isArray(input.failures) ? input.failures.length : 0),
    failures:
      Array.isArray(input.failures) && input.failures.length > 0
        ? input.failures
        : extractDesktopLearningProjectionFailures(input.result),
    sourceEvidenceRefs: Array.isArray(input.result?.sourceEvidenceRefs)
      ? input.result.sourceEvidenceRefs
      : [],
    memoryEvidenceRecords: Array.isArray(input.result?.memoryEvidenceRecords)
      ? input.result.memoryEvidenceRecords
      : [],
  });
  return {
    ...projection,
    userText: addDesktopLearningProjectionStatusLines(projection.userText, {
      source: input.source,
      result: input.result,
    }),
  };
}

function addDesktopLearningProjectionStatusLines(userText, { source, result }) {
  const lines = [];
  const intro = createDesktopLearningProjectionIntro(source, userText);
  if (intro.length > 0 && !userText.includes(intro)) {
    lines.push(intro);
  }
  lines.push(userText);
  const candidateCount = readLearningCandidateCount(result);
  if (
    source === "runtime-tool" &&
    candidateCount > 0 &&
    !/生成\s*\d+\s*条待审经验候选/iu.test(userText)
  ) {
    lines.push(`生成 ${candidateCount} 条待审经验候选。`);
  }
  const distillation = readDesktopLearningDistillationStatusLine(result);
  if (distillation.length > 0 && !userText.includes(distillation)) {
    lines.push(distillation);
  }
  return lines.filter((line) => line.length > 0).join("\n");
}

function createDesktopLearningProjectionIntro(source, userText) {
  if (!hasDesktopLearningCandidateStatusLine(userText)) {
    return "";
  }
  if (source === "directory") {
    return "这个目录我整理过了";
  }
  if (source === "query") {
    return "这轮学习我整理好了";
  }
  if (source === "runtime-tool") {
    return "这次学习我整理好了";
  }
  return "";
}

function hasDesktopLearningCandidateStatusLine(value) {
  return /已整理出\s*\d+\s*条待确认经验候选|整理出\s*\d+\s*条待确认经验候选/iu.test(
    String(value ?? ""),
  );
}

function readDesktopLearningDistillationStatusLine(result) {
  const candidates = readDesktopLearningCandidates(result);
  if (candidates.some((candidate) => isDesktopLearningModelDistilledCandidate(candidate))) {
    return "模型提炼：已启用。";
  }
  const tagTexts = candidates
    .flatMap((candidate) => (Array.isArray(candidate?.tags) ? candidate.tags : []))
    .map((tag) => String(tag));
  if (tagTexts.some((tag) => /distillation:model/iu.test(tag))) {
    return "模型提炼：已启用。";
  }
  const learningBudget = result?.learningBudget ?? result?.result?.learningBudget;
  if (
    learningBudget?.budgetGate?.blocked === true ||
    learningBudget?.options?.useModelDistillation === false ||
    learningBudget?.options?.enableModelDistillation === false
  ) {
    return "模型提炼：未启用。";
  }
  const modelDistillation = readNonEmptyString(
    result?.modelDistillation ??
      result?.model_distillation ??
      result?.metadata?.modelDistillation ??
      result?.result?.modelDistillation ??
      result?.result?.model_distillation,
  );
  if (modelDistillation !== undefined) {
    return formatLearningDistillationStatus(modelDistillation);
  }
  return "";
}

function isDesktopLearningModelDistilledCandidate(candidate) {
  const tags = Array.isArray(candidate?.tags) ? candidate.tags.map((tag) => String(tag)) : [];
  if (tags.some((tag) => /distillation:model/iu.test(tag))) {
    return true;
  }
  const distillation = candidate?.distillation ?? candidate?.metadata?.distillation;
  return (
    distillation?.mode === "model" ||
    /API\s*模型提炼|model/iu.test(String(distillation?.label ?? ""))
  );
}

function inferDesktopLearningSourceKind(source) {
  const text = String(source ?? "");
  if (/^https?:\/\//iu.test(text)) {
    return "url";
  }
  if (/^主题/u.test(text)) {
    return "query";
  }
  if (/^(?:\/|[A-Za-z]:\\)/u.test(text)) {
    return "directory";
  }
  return "runtime-tool";
}

function extractDesktopLearningProjectionCandidates(result) {
  const candidates = readDesktopLearningCandidates(result);
  return candidates.slice(0, 12).map((candidate) => ({
    ...(candidate?.candidateId === undefined && candidate?.id === undefined
      ? {}
      : { candidateId: candidate.candidateId ?? candidate.id }),
    ...(candidate?.title === undefined && candidate?.metadata?.title === undefined
      ? {}
      : { title: candidate.title ?? candidate.metadata.title }),
    ...(resolveDesktopLearningProjectionSummary(candidate) === undefined
      ? {}
      : {
          summary: resolveDesktopLearningProjectionSummary(candidate),
        }),
  }));
}

function resolveDesktopLearningProjectionSummary(candidate) {
  const parts = [];
  for (const part of [
    candidate?.summary,
    candidate?.evidencePreview,
    candidate?.sourceDocument?.content,
    candidate?.sourceDocument?.rawContent,
    candidate?.metadata?.summary,
  ]) {
    const normalized = sanitizeDesktopLearningProjectionSummary(part);
    if (normalized.length === 0) {
      continue;
    }
    const existingIndex = parts.findIndex((existing) =>
      desktopLearningProjectionSummaryPartsOverlap(existing, normalized),
    );
    if (existingIndex === -1) {
      parts.push(normalized);
      continue;
    }
    if (
      normalizeDesktopLearningProjectionSummaryPart(normalized).length >
      normalizeDesktopLearningProjectionSummaryPart(parts[existingIndex]).length * 1.25
    ) {
      parts[existingIndex] = normalized;
    }
  }
  if (parts.length === 0) {
    return undefined;
  }
  return parts.join("。");
}

function desktopLearningProjectionSummaryPartsOverlap(left, right) {
  const normalizedLeft = normalizeDesktopLearningProjectionSummaryPart(left);
  const normalizedRight = normalizeDesktopLearningProjectionSummaryPart(right);
  if (normalizedLeft.length === 0 || normalizedRight.length === 0) {
    return false;
  }
  return (
    normalizedLeft === normalizedRight ||
    normalizedLeft.includes(normalizedRight) ||
    normalizedRight.includes(normalizedLeft)
  );
}

function normalizeDesktopLearningProjectionSummaryPart(value) {
  return String(value ?? "")
    .replace(/^\s*(?:低置信)?经验提炼\s*[:：]\s*/iu, "")
    .replace(/\s+/gu, " ")
    .replace(/[。！？!?；;，,、:：\s]+/gu, "")
    .toLocaleLowerCase()
    .trim();
}

function sanitizeDesktopLearningProjectionSummary(value) {
  return String(value ?? "")
    .replace(/\[Video:[^\]\n]+\]\([^)]+\)/giu, "[媒体：视频]")
    .replace(/\[Image:[^\]\n]+\]\([^)]+\)/giu, "[媒体：图片]")
    .replace(/blob:https?:\/\/\S+/giu, "[媒体链接]")
    .replace(/\bposter=https?:\/\/\S+/giu, "poster=[媒体封面]")
    .replace(/https?:\/\/pbs\.twimg\.com\/\S+/giu, "[媒体链接]")
    .replace(/\s+/gu, " ")
    .trim();
}

function extractDesktopLearningProjectionFailures(result) {
  const failures = [];
  const quarantines = Array.isArray(result?.quarantines) ? result.quarantines : [];
  for (const item of quarantines) {
    const artifact = item?.artifact ?? {};
    const reason =
      item?.reason ?? artifact?.quality?.reasons?.[0] ?? item?.notes?.[0] ?? "source quarantined";
    failures.push({
      ...(artifact?.sourceRef === undefined ? {} : { sourceRef: artifact.sourceRef }),
      ...(artifact?.title === undefined ? {} : { title: artifact.title }),
      reason,
      detail: artifact?.textPreview ?? item?.notes?.[0] ?? reason,
    });
  }
  return failures.slice(0, 12);
}

function readLearningFailureCount(result) {
  if (typeof result === "string") {
    return extractLearningCount(result, "quarantined sources");
  }
  if (Array.isArray(result?.quarantines)) {
    return result.quarantines.length;
  }
  if (Array.isArray(result?.result?.quarantines)) {
    return result.result.quarantines.length;
  }
  if (Number.isFinite(result?.quarantineCount)) {
    return result.quarantineCount;
  }
  if (Number.isFinite(result?.result?.quarantineCount)) {
    return result.result.quarantineCount;
  }
  return null;
}

function readDesktopLearningCandidates(result) {
  if (Array.isArray(result?.candidates)) {
    return result.candidates;
  }
  if (result?.learningReport !== undefined && typeof result.learningReport !== "string") {
    return readDesktopLearningCandidates(result.learningReport);
  }
  if (typeof result?.learningReport === "string") {
    return [];
  }
  if (Array.isArray(result?.result?.candidates)) {
    return result.result.candidates;
  }
  return [];
}

function readDesktopLearningCandidateIds(result) {
  if (result?.learningReport !== undefined && typeof result.learningReport !== "string") {
    return uniqueStringArray([
      ...readDesktopLearningCandidateIds(result.learningReport),
      ...readDesktopLearningCandidateIdArray(result?.candidateIds),
      ...readDesktopLearningCandidateIdArray(result?.candidate_ids),
      ...readDesktopLearningCandidateIdArray(result?.result?.candidateIds),
      ...readDesktopLearningCandidateIdArray(result?.result?.candidate_ids),
    ]);
  }
  return uniqueStringArray([
    ...readDesktopLearningCandidateIdArray(result?.candidateIds),
    ...readDesktopLearningCandidateIdArray(result?.candidate_ids),
    ...readDesktopLearningCandidateIdArray(result?.result?.candidateIds),
    ...readDesktopLearningCandidateIdArray(result?.result?.candidate_ids),
    ...readDesktopLearningCandidates(result)
      .map((candidate) => candidate?.candidateId ?? candidate?.id ?? candidate?.metadata?.id)
      .filter((id) => typeof id === "string" && id.length > 0),
  ]);
}

function readDesktopLearningCandidateIdArray(value) {
  return Array.isArray(value)
    ? value.filter((id) => typeof id === "string" && id.length > 0)
    : [];
}

function appendDesktopLearningMediaAuthorizationNote(body, result) {
  const summary = summarizeDesktopLearningDiscoveredMedia(result);
  if (summary.assetCount <= 0 || body.includes("媒体授权")) {
    return body;
  }
  const bodyWithTakeaways = /(?:学到的要点|可用要点)：/iu.test(body)
    ? body
    : [
        body,
        "",
        "可用要点：",
        "1. 正文要点已整理为待确认经验候选；媒体只记录清单，未授权前不参与结论。",
      ].join("\n");
  return [
    bodyWithTakeaways,
    "",
    "媒体授权",
    formatDesktopLearningMediaAuthorizationCountLine(summary),
    formatDesktopLearningMediaSupplementalLine(summary),
    "文本已读，媒体未理解。",
    "当前只学习了正文文字和可审计摘要；媒体本体还没有交给视觉、视频或音频工具精读。",
    "如需精读媒体，需要你授权处理范围和 token 预算。",
    "未授权前不把媒体内容当成已学经验入库。",
  ]
    .filter((line) => line.length > 0)
    .join("\n");
}

function formatDesktopLearningMediaAuthorizationCountLine(summary) {
  const relevant = summary.primary.assetCount > 0 ? summary.primary : summary;
  return `发现 ${relevant.assetCount} 个正文相关媒体资源：图片 ${relevant.imageCount}、视频 ${relevant.videoCount}、音频 ${relevant.audioCount}。`;
}

function formatDesktopLearningMediaSupplementalLine(summary) {
  if (summary.primary.assetCount <= 0 || summary.supplemental.assetCount <= 0) {
    return "";
  }
  return `另有 ${summary.supplemental.assetCount} 个页面附属媒体未计入正文媒体，例如头像、emoji、登录组件或推荐区素材。`;
}

function createDesktopLearningEvidenceMediaInventory(counts) {
  return {
    assetCount: readFiniteNumber(counts?.assetCount) ?? 0,
    imageCount: readFiniteNumber(counts?.imageCount) ?? 0,
    videoCount: readFiniteNumber(counts?.videoCount) ?? 0,
    audioCount: readFiniteNumber(counts?.audioCount) ?? 0,
    posterCount: readFiniteNumber(counts?.posterCount) ?? 0,
    blobCount: readFiniteNumber(counts?.blobCount) ?? 0,
    unknownCount: readFiniteNumber(counts?.unknownCount) ?? 0,
  };
}

function createDesktopLearningMediaAuthorizationRequest(mediaInventory) {
  const tokenLimit = createDesktopLearningMediaTokenLimit(mediaInventory);
  return {
    required: true,
    assetCount: mediaInventory.assetCount,
    imageCount: mediaInventory.imageCount,
    videoCount: mediaInventory.videoCount,
    audioCount: mediaInventory.audioCount,
    posterCount: mediaInventory.posterCount,
    blobCount: mediaInventory.blobCount,
    recommendedMode: mediaInventory.videoCount > 0 ? "low_cost" : "media_inventory",
    estimatedCostTier: mediaInventory.assetCount > 0 ? "medium" : "low",
    estimatedTokenBudget: {
      mediaInventory: 0,
      lowCost: Math.min(tokenLimit, 12000),
      deepMultimodal: tokenLimit,
    },
  };
}

function createDesktopLearningMediaAdmission(mediaInventory) {
  const request = createDesktopLearningMediaAuthorizationRequest(mediaInventory);
  return {
    status: "text_admissible_media_list_only",
    reason: "media_not_understood_without_user_authorization",
    canAdmitTextEvidence: true,
    canAdmitMediaContent: false,
    requiredNextAction: "request_user_authorization",
    budget: {
      tokenLimit: request.estimatedTokenBudget.deepMultimodal,
      fileCountLimit: mediaInventory.assetCount,
      videoMinuteLimit: mediaInventory.videoCount > 0 ? Math.max(1, mediaInventory.videoCount) : 0,
      estimatedCostTier: request.estimatedCostTier,
    },
  };
}

function createDesktopLearningMediaTokenLimit(mediaInventory) {
  return (
    mediaInventory.imageCount * 3500 +
    mediaInventory.videoCount * 12000 +
    mediaInventory.audioCount * 3000 +
    mediaInventory.posterCount * 1000 +
    mediaInventory.blobCount * 1500 +
    mediaInventory.unknownCount * 2500
  );
}

function recordDesktopStructuredFetchContent(store, requestedUrl, fetched) {
  if (!(store instanceof Map) || typeof fetched !== "object" || fetched === null) {
    return;
  }
  const structuredContent = isPlainObject(fetched.structuredContent)
    ? fetched.structuredContent
    : null;
  if (structuredContent === null) {
    return;
  }
  for (const url of [requestedUrl, fetched.url]) {
    for (const key of normalizeDesktopStructuredContentUrlKeys(url)) {
      store.set(key, structuredContent);
    }
  }
}

function readDesktopStructuredFetchContent(store, ...urls) {
  if (!(store instanceof Map)) {
    return undefined;
  }
  for (const url of urls) {
    for (const key of normalizeDesktopStructuredContentUrlKeys(url)) {
      const value = store.get(key);
      if (isPlainObject(value)) {
        return value;
      }
    }
  }
  return undefined;
}

function normalizeDesktopStructuredContentUrlKeys(value) {
  if (typeof value !== "string" || value.trim().length === 0) {
    return [];
  }
  const raw = value.trim();
  const keys = new Set([raw]);
  try {
    const parsed = new URL(raw);
    parsed.hash = "";
    keys.add(parsed.toString());
    parsed.search = "";
    keys.add(parsed.toString());
    if (parsed.pathname.length > 1 && parsed.pathname.endsWith("/")) {
      parsed.pathname = parsed.pathname.replace(/\/+$/u, "");
      keys.add(parsed.toString());
    }
  } catch {
    // Keep the raw key for non-standard URLs.
  }
  return [...keys];
}

function summarizeDesktopLearningDiscoveredMedia(result) {
  const counts = createDesktopLearningScopedMediaCounts();
  const seen = new Set();
  const seenStructuredContent = new Set();
  collectDesktopLearningMediaFromUniqueStructuredContent(
    result?.structuredContent,
    counts,
    seen,
    seenStructuredContent,
  );
  collectDesktopLearningMediaFromUniqueStructuredContent(
    result?.urlRead?.source?.structuredContent,
    counts,
    seen,
    seenStructuredContent,
  );
  collectDesktopLearningMediaFromUniqueStructuredContent(
    result?.urlRead?.source?.sourceSnapshot,
    counts,
    seen,
    seenStructuredContent,
  );
  if (counts.assetCount > 0) {
    return counts;
  }
  const disclosureSources = Array.isArray(result?.evidenceDisclosure?.sources)
    ? result.evidenceDisclosure.sources
    : [];
  for (const source of disclosureSources) {
    collectDesktopLearningMediaFromUniqueStructuredContent(
      source,
      counts,
      seen,
      seenStructuredContent,
    );
  }
  const urlReadAttempts = Array.isArray(result?.urlRead?.attempts) ? result.urlRead.attempts : [];
  for (const attempt of urlReadAttempts) {
    collectDesktopLearningMediaFromUniqueStructuredContent(
      attempt,
      counts,
      seen,
      seenStructuredContent,
    );
  }
  if (counts.assetCount === 0) {
    for (const candidate of readDesktopLearningCandidates(result)) {
      collectDesktopLearningMediaFromText(
        [candidate?.summary, candidate?.applicability, candidate?.evidencePreview].join("\n"),
        counts,
        seen,
      );
    }
  }
  if (counts.assetCount === 0) {
    collectDesktopLearningMediaFromText(
      [
        result?.learningReport,
        result?.urlRead?.source?.body,
        result?.urlRead?.source?.sourceSnapshot,
      ]
        .map((value) => (typeof value === "string" ? value : JSON.stringify(value ?? "")))
        .join("\n"),
      counts,
      seen,
    );
  }
  return counts;
}

function collectDesktopLearningMediaFromUniqueStructuredContent(value, counts, seen, seenStructuredContent) {
  if (!isPlainObject(value) && !Array.isArray(value)) {
    return;
  }
  const identity = `structured:${hashDesktopRuntimeText(JSON.stringify(value))}`;
  if (seenStructuredContent.has(identity)) {
    return;
  }
  seenStructuredContent.add(identity);
  collectDesktopLearningMediaFromStructuredContent(value, counts, seen);
}

function createDesktopLearningMediaCounts() {
  return {
    assetCount: 0,
    imageCount: 0,
    videoCount: 0,
    audioCount: 0,
    posterCount: 0,
    blobCount: 0,
    unknownCount: 0,
  };
}

function createDesktopLearningScopedMediaCounts() {
  return {
    ...createDesktopLearningMediaCounts(),
    primary: createDesktopLearningMediaCounts(),
    supplemental: createDesktopLearningMediaCounts(),
  };
}

function collectDesktopLearningMediaFromStructuredContent(
  value,
  counts,
  seen = new Set(),
  scope = "root",
) {
  if (Array.isArray(value)) {
    for (const item of value) {
      collectDesktopLearningMediaFromStructuredContent(item, counts, seen, scope);
    }
    return;
  }
  if (!isPlainObject(value)) {
    return;
  }
  if (isDesktopConversationMediaInventory(value)) {
    addDesktopLearningMediaInventoryCounts(value, counts, seen, scope);
    return;
  }
  for (const inventory of [
    value.mediaInventory,
    value.media_inventory,
    value.output?.mediaInventory,
    value.output?.media_inventory,
  ]) {
    if (isDesktopConversationMediaInventory(inventory)) {
      addDesktopLearningMediaInventoryCounts(inventory, counts, seen, scope);
      return;
    }
  }
  if (isDesktopLearningStructuredMediaBlock(value)) {
    addDesktopLearningStructuredMediaItem(value.media ?? value, counts, seen, "primary");
  }
  for (const key of ["blocks", "orderedBlocks", "children", "items"]) {
    if (Array.isArray(value[key])) {
      collectDesktopLearningMediaFromStructuredContent(value[key], counts, seen, "content");
    }
  }
  for (const key of ["media", "assets"]) {
    const media = Array.isArray(value[key]) ? value[key] : [];
    for (const item of media) {
      addDesktopLearningStructuredMediaItem(
        item,
        counts,
        seen,
        scope === "content" || scope === "primary" ? "primary" : "supplemental",
      );
    }
  }
  for (const key of [
    "structuredContent",
    "sourceSnapshot",
    "source_snapshot",
    "externalContent",
    "snapshot",
  ]) {
    if (isPlainObject(value[key]) || Array.isArray(value[key])) {
      collectDesktopLearningMediaFromStructuredContent(value[key], counts, seen, scope);
    }
  }
}

function addDesktopLearningMediaInventoryCounts(inventory, counts, seen, scope) {
  const normalized = normalizeDesktopConversationMediaInventory(inventory);
  const inventoryId = hashDesktopRuntimeText(JSON.stringify(normalized));
  for (const [kind, count] of [
    ["image", normalized.imageCount],
    ["video", normalized.videoCount],
    ["audio", normalized.audioCount],
    ["poster", normalized.posterCount],
    ["blob", normalized.blobCount],
    ["unknown", normalized.unknownCount],
  ]) {
    for (let index = 1; index <= count; index += 1) {
      const identity = `inventory:${inventoryId}:${kind}:${index}`;
      if (seen.has(identity)) {
        continue;
      }
      seen.add(identity);
      incrementDesktopLearningMediaCount(counts, kind);
      incrementDesktopLearningMediaCount(
        scope === "content" || scope === "primary" ? counts.primary : counts.supplemental,
        kind,
      );
    }
  }
}

function isDesktopLearningStructuredMediaBlock(value) {
  if (!isPlainObject(value)) {
    return false;
  }
  if (value.kind === "media" && isPlainObject(value.media)) {
    return true;
  }
  const kind = String(value.kind ?? value.type ?? value.mediaType ?? "").toLowerCase();
  return (
    kind === "image" ||
    kind === "video" ||
    kind === "audio" ||
    kind === "iframe" ||
    kind === "media"
  );
}

function addDesktopLearningStructuredMediaItem(item, counts, seen, scope) {
  if (!isPlainObject(item)) {
    return;
  }
  const kind = String(item.kind ?? item.type ?? item.mediaType ?? "").toLowerCase();
  const identity = createDesktopLearningMediaIdentity(item, kind);
  if (seen.has(identity)) {
    return;
  }
  seen.add(identity);
  incrementDesktopLearningMediaCount(counts, kind);
  incrementDesktopLearningMediaCount(
    scope === "primary" ? counts.primary : counts.supplemental,
    kind,
  );
}

function createDesktopLearningMediaIdentity(item, kind) {
  const locator =
    item.src ??
    item.url ??
    item.href ??
    item.poster ??
    item.thumbnail ??
    item.alt ??
    item.title ??
    JSON.stringify(item);
  return `${kind || "unknown"}:${String(locator)}`;
}

function collectDesktopLearningMediaFromText(value, counts, seen = new Set()) {
  const text = String(value ?? "");
  const patterns = [
    ["image", /!\[[^\]]*\]\(([^)]+)\)|\[Image:[^\]\n]+\]\(([^)]+)\)|https?:\/\/pbs\.twimg\.com\/media\/\S+/giu],
    ["video", /\[Video:[^\]\n]*\]\(([^)]+)\)|blob:https?:\/\/\S+|https?:\/\/\S*(?:video|amplify_video)\S*/giu],
    ["audio", /\[Audio:[^\]\n]*\]\(([^)]+)\)|https?:\/\/\S*(?:audio|podcast)\S*/giu],
  ];
  for (const [kind, pattern] of patterns) {
    for (const match of text.matchAll(pattern)) {
      const locator = match[1] ?? match[2] ?? match[0];
      const identity = `${kind}:${String(locator).replace(/\s+poster=.*$/iu, "")}`;
      if (seen.has(identity)) {
        continue;
      }
      seen.add(identity);
      incrementDesktopLearningMediaCount(counts, kind);
      incrementDesktopLearningMediaCount(counts.primary, kind);
    }
  }
}

function incrementDesktopLearningMediaCount(counts, kind) {
  if (!isPlainObject(counts)) {
    return;
  }
  counts.assetCount += 1;
  if (kind.includes("image") || kind.includes("图片")) {
    counts.imageCount += 1;
    return;
  }
  if (kind.includes("video") || kind.includes("视频")) {
    counts.videoCount += 1;
    return;
  }
  if (kind.includes("audio") || kind.includes("音频")) {
    counts.audioCount += 1;
    return;
  }
  if (kind.includes("poster") || kind.includes("thumbnail") || kind.includes("封面")) {
    counts.posterCount += 1;
    return;
  }
  if (kind.includes("blob")) {
    counts.blobCount += 1;
    return;
  }
  counts.unknownCount += 1;
}

function createPastedTextTitle(text) {
  const firstLine = String(text)
    .split(/\n/u)
    .map((line) => line.trim())
    .find((line) => line.length > 0);
  if (!firstLine) {
    return "粘贴文本";
  }
  return firstLine.length <= 80 ? firstLine : firstLine.slice(0, 80);
}

function extractLearningCount(output, label) {
  const match = new RegExp(`${label}:\\s*(\\d+)`, "iu").exec(output);
  return match?.[1] === undefined ? null : Number.parseInt(match[1], 10);
}

function extractLearningValue(output, label) {
  const escaped = label.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&");
  const match = new RegExp(`^\\s*${escaped}:\\s*(.+)$`, "imu").exec(output);
  return match?.[1]?.trim() ?? null;
}

function formatLearningDistillationStatus(value) {
  if (value === null) {
    return "";
  }
  if (/^enabled$/iu.test(value)) {
    return "模型提炼：已启用。";
  }
  if (/^disabled$/iu.test(value)) {
    return "模型提炼：未启用。";
  }
  return `模型提炼：${value}。`;
}

function extractLearningReasonLines(output) {
  const reasonLines = [];
  for (const match of output.matchAll(/^\s+notes:\s*(.+)$/gimu)) {
    reasonLines.push(...splitLearningNotes(match[1] ?? ""));
  }
  for (const match of output.matchAll(/^\s*(?:Skipped|Quarantined)\s+(.+)$/gimu)) {
    reasonLines.push(match[0].trim());
  }
  return Array.from(new Set(reasonLines.map((line) => line.trim()).filter(Boolean)));
}

function splitLearningNotes(value) {
  return String(value)
    .split(/\s+\|\s+/u)
    .map((entry) => entry.trim())
    .filter(Boolean);
}

function createRunOutputExperienceEvent(result, actionType) {
  const materialized = result.materialized;
  if (materialized.status === "candidate") {
    const candidateId = materialized.candidate.candidateId;
    const isFailureLesson = materialized.candidate.tags.includes("failure-lesson");
    return createEvent(
      isFailureLesson ? "失败教训已生成" : "运行经验候选已生成",
      [
        `候选 ${candidateId} 已进入经验库待审。`,
        `sourceQuality=${materialized.admission.sourceQuality.score}`,
        `claimQuality=${materialized.admission.claimQuality.score}`,
        `写入：${result.write.notes.join(" | ")}`,
      ].join(" "),
      actionType,
    );
  }

  return createEvent(
    "运行产物已隔离",
    [
      materialized.quarantine.reason,
      `sourceQuality=${materialized.admission.sourceQuality.score}`,
      `claimQuality=${materialized.admission.claimQuality.score}`,
      `写入：${result.write.notes.join(" | ")}`,
    ].join(" "),
    actionType,
  );
}

function createDesktopReflectionResult(result, learningEnabled) {
  const recommended = result.experience.recommended;
  return {
    reflectionId: result.reflection.reflectionId,
    runId: result.reflection.sourceId,
    reportId: result.reflection.reportId,
    outcome: result.reflection.outcome,
    status: result.reflection.status,
    suggestedExperienceIntent: result.reflection.suggestedExperienceIntent,
    recommendedCandidateStatus: recommended?.materialized.status ?? "none",
    recommendedCandidateId:
      recommended?.materialized.status === "candidate"
        ? recommended.materialized.candidate.candidateId
        : null,
    positiveBlocked: result.experience.blockedPositive?.status === "quarantined",
    reflectionPath: result.reflectionWrite.path,
    experienceWriteStatus:
      result.experienceWrite?.status ?? (learningEnabled ? "none" : "disabled"),
    soulCandidateStatus: result.soulCandidate?.status ?? "none",
    soulCandidateId: result.soulCandidate?.candidateId ?? null,
    soulWriteStatus: result.soulWrite?.status ?? "none",
    soulWritePath: result.soulWrite?.path ?? null,
    whatWorked: [...result.reflection.whatWorked],
    whatFailed: [...result.reflection.whatFailed],
    reusableLessons: [...result.reflection.reusableLessons],
    failureLessons: [...result.reflection.failureLessons],
    nextActions: [...result.reflection.nextActions],
    learningEnabled,
  };
}

function createReflectionEvent(result, actionType, learningEnabled) {
  const reflection = result.reflection;
  const recommended = result.experience.recommended;
  const candidateCopy =
    recommended?.materialized.status === "candidate"
      ? `候选 ${recommended.materialized.candidate.candidateId} 已进入经验库待审。`
      : learningEnabled
        ? "本次复盘没有生成经验候选。"
        : "自我学习入口关闭，只保存复盘报告，不写入经验候选。";
  return createEvent(
    "运行复盘已生成",
    [
      `outcome=${reflection.outcome}`,
      `suggested=${reflection.suggestedExperienceIntent}`,
      candidateCopy,
      reflection.outcome === "success"
        ? "正向经验仍需人工审核后才能发布。"
        : "该结果不会作为正向经验发布。",
      `复盘文件：${result.reflectionWrite.path}`,
    ].join(" "),
    actionType,
  );
}

function readHostApiText(result, fallback) {
  return typeof result?.text === "string" && result.text.trim().length > 0 ? result.text : fallback;
}

function createMaintenanceActionInput(action) {
  const input = {};
  for (const key of [
    "nowMs",
    "logRetentionDays",
    "logMaxBytes",
    "archivePromotedExperienceAfterDays",
    "archiveRejectedExperienceAfterDays",
    "archiveQuarantineAfterDays",
    "archiveUnreferencedArtifactsAfterDays",
    "staleUnreviewedExperienceDays",
    "staleUnreviewedMinimumScore",
    "archiveRejectedKnowledgeAfterDays",
    "staleUnreviewedKnowledgeDays",
    "archiveOrphanKnowledgeReviewsAfterDays",
    "knowledgeHistoryRetentionVersions",
    "archiveKnowledgeRollbackAfterDays",
  ]) {
    if (action[key] !== undefined) {
      input[key] = action[key];
    }
  }
  return input;
}

async function inspectLocalDesktopMaintenance(workspaceRoot, action) {
  const workspace = resolveDirectorWorkspace({ root: workspaceRoot });
  return inspectDirectorMaintenance({
    runtimeRoot: workspace.runtime,
    experienceDir: join(workspace.knowledge, "experience"),
    knowledgeDir: workspace.knowledge,
    ...createLocalMaintenanceInput(action),
  });
}

async function applyLocalDesktopMaintenance(workspaceRoot, action) {
  const workspace = resolveDirectorWorkspace({ root: workspaceRoot });
  return applyDirectorMaintenance({
    runtimeRoot: workspace.runtime,
    experienceDir: join(workspace.knowledge, "experience"),
    knowledgeDir: workspace.knowledge,
    ...createLocalMaintenanceInput(action),
  });
}

function createLocalMaintenanceInput(action) {
  const policy = {};
  for (const key of [
    "logRetentionDays",
    "logMaxBytes",
    "archivePromotedExperienceAfterDays",
    "archiveRejectedExperienceAfterDays",
    "archiveQuarantineAfterDays",
    "archiveUnreferencedArtifactsAfterDays",
    "staleUnreviewedExperienceDays",
    "staleUnreviewedMinimumScore",
    "archiveRejectedKnowledgeAfterDays",
    "staleUnreviewedKnowledgeDays",
    "archiveOrphanKnowledgeReviewsAfterDays",
    "knowledgeHistoryRetentionVersions",
    "archiveKnowledgeRollbackAfterDays",
  ]) {
    if (action[key] !== undefined) {
      policy[key] = action[key];
    }
  }
  return {
    ...(action.nowMs === undefined ? {} : { nowMs: action.nowMs }),
    ...(Object.keys(policy).length === 0 ? {} : { policy }),
  };
}

function createMaintenanceEvent(report, actionType) {
  return createEvent(
    report?.mode === "apply" ? "维护已执行" : "维护预览",
    summarizeMaintenanceReport(report),
    actionType,
  );
}

function summarizeMaintenanceReport(report) {
  const log = report?.logMaintenance?.summary ?? {};
  const experience = report?.experienceMaintenance?.summary ?? {};
  const knowledge = report?.knowledgeMaintenance?.summary ?? {};
  return [
    `模式：${report?.mode === "apply" ? "已执行" : "预览"}`,
    `日志：扫描 ${readFiniteNumber(log.scannedFiles) ?? 0} 个，归档 ${
      readFiniteNumber(log.archiveFiles) ?? 0
    } 个`,
    `经验：活跃 ${readFiniteNumber(experience.activeCandidates) ?? 0} 条，候选归档 ${
      readFiniteNumber(experience.archiveCandidates) ?? 0
    } 条，隔离归档 ${readFiniteNumber(experience.archiveQuarantines) ?? 0} 条，源材料归档 ${
      readFiniteNumber(experience.archiveArtifacts) ?? 0
    } 条`,
    `重复组：${readFiniteNumber(experience.duplicateGroups) ?? 0}`,
    `知识：候选归档 ${readFiniteNumber(knowledge.archiveCandidates) ?? 0} 条，审查归档 ${
      readFiniteNumber(knowledge.archiveReviews) ?? 0
    } 条，历史归档 ${readFiniteNumber(knowledge.archiveHistory) ?? 0} 条，回滚归档 ${
      readFiniteNumber(knowledge.archiveRollback) ?? 0
    } 条`,
    report?.mode === "apply"
      ? `审计：${report?.auditPath ?? "(未返回)"}`
      : "执行：确认无误后发送 /维护 执行",
  ].join(" · ");
}

function renderMaintenanceReport(report) {
  const log = report?.logMaintenance?.summary ?? {};
  const experience = report?.experienceMaintenance?.summary ?? {};
  const knowledge = report?.knowledgeMaintenance?.summary ?? {};
  const lines = [
    "Director maintenance:",
    `  mode: ${report?.mode ?? "unknown"}`,
    `  generated: ${report?.generatedAt ?? "(unknown)"}`,
    `  logs: scanned=${readFiniteNumber(log.scannedFiles) ?? 0} archive=${
      readFiniteNumber(log.archiveFiles) ?? 0
    } bytes=${readFiniteNumber(log.archiveBytes) ?? 0}`,
    `  experience: active=${readFiniteNumber(experience.activeCandidates) ?? 0} candidates=${
      readFiniteNumber(experience.archiveCandidates) ?? 0
    } quarantines=${readFiniteNumber(experience.archiveQuarantines) ?? 0} artifacts=${
      readFiniteNumber(experience.archiveArtifacts) ?? 0
    } duplicateGroups=${readFiniteNumber(experience.duplicateGroups) ?? 0}`,
    `  knowledge: active=${readFiniteNumber(knowledge.activeCandidates) ?? 0} candidates=${
      readFiniteNumber(knowledge.archiveCandidates) ?? 0
    } reviews=${readFiniteNumber(knowledge.archiveReviews) ?? 0} history=${
      readFiniteNumber(knowledge.archiveHistory) ?? 0
    } rollback=${readFiniteNumber(knowledge.archiveRollback) ?? 0}`,
    `  audit: ${report?.auditPath ?? "(not written in preview)"}`,
  ];
  const actions = [
    ...(Array.isArray(report?.logMaintenance?.actions) ? report.logMaintenance.actions : []),
    ...(Array.isArray(report?.experienceMaintenance?.actions)
      ? report.experienceMaintenance.actions
      : []),
    ...(Array.isArray(report?.knowledgeMaintenance?.actions) ? report.knowledgeMaintenance.actions : []),
  ].slice(0, 8);
  for (const action of actions) {
    lines.push(
      `  - ${action.recordKind ?? "log"} ${action.reason ?? "archive"} ${
        action.status ?? "preview"
      } ${action.recordId ?? action.sourcePath ?? ""}`,
    );
  }
  return lines.join("\n");
}

function renderHostApiSoulCandidates(candidates) {
  const items = Array.isArray(candidates) ? candidates : [];
  const lines = ["Director Soul candidates:", `  total: ${items.length}`];
  if (items.length === 0) {
    lines.push("  candidates: (none)");
    return lines.join("\n");
  }
  for (const candidate of items) {
    lines.push(
      `  - ${candidate.candidateId} status=${candidate.status} risk=${candidate.riskLevel} source=${candidate.sourceId}`,
    );
    lines.push(`    summary: ${candidate.patchSummary}`);
  }
  return lines.join("\n");
}

function renderHostApiSoulCandidate(candidate) {
  if (!candidate) {
    return "Director Soul candidate:\n  status: missing";
  }
  const lines = [
    "Director Soul candidate:",
    `  candidate id: ${candidate.candidateId}`,
    `  status: ${candidate.status}`,
    `  risk: ${candidate.riskLevel}`,
    `  source reflection: ${candidate.sourceReflectionId}`,
    `  source: ${candidate.sourceKind}/${candidate.sourceId}`,
    `  summary: ${candidate.patchSummary}`,
  ];
  return lines.join("\n");
}

function renderHostApiSoulDecision(result) {
  return [
    "Director Soul decision:",
    `  candidate id: ${result?.candidate?.candidateId ?? "(unknown)"}`,
    `  decision: ${result?.decision?.decision ?? "(unknown)"}`,
    `  decision file: ${result?.decisionPath ?? "(unknown)"}`,
    `  soul.json: ${result?.soulPath ?? "(unchanged)"}`,
    `  SOUL.md: ${result?.soulMarkdownPath ?? "(unchanged)"}`,
  ].join("\n");
}

function createWeixinGatewayEvent(result, actionType) {
  const service = result.service;
  const accountCopy = service.account.loggedIn
    ? `已登录账号：${service.account.primaryId ?? service.account.count}`
    : "未检测到微信登录账号";
  const statusCopy = service.running ? "运行中" : service.status;
  const operationLabels = {
    status: "微信网关状态",
    start: "微信网关已启动",
    stop: "微信网关已停止",
    restart: "微信网关已重启",
  };
  const failureLabels = {
    start: "微信网关启动失败",
    restart: "微信网关重启失败",
    stop: "微信网关停止异常",
  };
  const failed = result.ok === false;
  return createEvent(
    failed
      ? (failureLabels[result.operation] ?? "微信网关操作失败")
      : (operationLabels[result.operation] ?? "微信网关"),
    [
      failed && result.message ? `原因：${result.message}` : null,
      `状态：${statusCopy}`,
      `常驻：${service.enabled ? "开启" : "关闭"}`,
      `管理器：${service.manager}`,
      accountCopy,
      result.issue ? `问题：${result.issue}` : null,
      `日志：${service.stdoutPath}`,
    ]
      .filter(Boolean)
      .join(" · "),
    actionType,
  );
}

function createWeixinGatewayLoginEvent(result, actionType) {
  const login = result.login;
  const labels = {
    qr: "微信二维码已生成",
    wait: "等待微信扫码",
    scaned: "微信已扫码",
    scaned_but_redirect: "微信登录节点已切换",
    need_verifycode: "微信需要验证码",
    confirmed: "微信已连接",
    expired: "微信二维码已过期",
    verify_code_blocked: "微信验证码被锁定",
    binded_redirect: "微信已绑定",
    idle: "微信登录",
  };
  const pieces = [
    login.message ?? "等待微信登录状态更新。",
    result.service?.account?.loggedIn
      ? `账号：${result.service.account.primaryId ?? result.service.account.count}`
      : null,
    result.service?.running ? "网关：运行中" : null,
  ].filter(Boolean);
  return createEvent(labels[login.status] ?? "微信登录", pieces.join(" · "), actionType);
}

function createEvent(title, body, actionType, extras = {}) {
  return {
    role: DESKTOP_EVENT_ROLES.SYSTEM,
    title,
    body,
    actionType,
    ...extras,
  };
}

function writeDesktopSessionTranscriptArchive({ dataDir, sessionKey, transcriptArchive }) {
  const archiveSessionKey = readNonEmptyString(sessionKey) ?? "desktop:workbench";
  const archiveCreatedAt = new Date().toISOString();
  const archiveId = `desktop-session-${sanitizeDesktopSessionArchiveId(
    archiveSessionKey,
  )}-${Date.now()}`;
  const archiveDir = join(dataDir, "desktop-session-archives");
  const archivePath = join(archiveDir, `${archiveId}.json`);
  try {
    mkdirSync(archiveDir, { recursive: true });
    const archiveBody = {
      schemaVersion:
        readNonEmptyString(transcriptArchive?.schemaVersion) ??
        "director.desktop.session-transcript-archive.v1",
      archiveId,
      sessionKey: archiveSessionKey,
      archivedAt: archiveCreatedAt,
      sourceArchivedAt: readNonEmptyString(transcriptArchive?.archivedAt) ?? null,
      runtimeHistory: Array.isArray(transcriptArchive?.runtimeHistory)
        ? transcriptArchive.runtimeHistory
        : [],
      turns: Array.isArray(transcriptArchive?.turns) ? transcriptArchive.turns : [],
      evidenceDisclosures: Array.isArray(transcriptArchive?.evidenceDisclosures)
        ? transcriptArchive.evidenceDisclosures
        : [],
      activeEvidenceFrame: transcriptArchive?.activeEvidenceFrame ?? null,
    };
    writeFileSync(archivePath, `${JSON.stringify(archiveBody, null, 2)}\n`, "utf8");
    return {
      ok: true,
      archiveId,
      path: archivePath,
      sessionKey: archiveSessionKey,
      archivedAt: archiveBody.archivedAt,
    };
  } catch (error) {
    return {
      ok: false,
      archiveId,
      path: archivePath,
      sessionKey: archiveSessionKey,
      reason: error instanceof Error ? error.message : String(error),
    };
  }
}

function sanitizeDesktopSessionArchiveId(value) {
  return String(value ?? "")
    .replace(/[^A-Za-z0-9._-]+/gu, "-")
    .replace(/^-+|-+$/gu, "")
    .slice(0, 160) || "workbench";
}

function createNativeCommandResult({ commandId, label, stdout, actionType, domain = "Soul" }) {
  return {
    status: "completed",
    handlerType: "desktopAction",
    exitCode: 0,
    stdout,
    actionType,
    command: {
      id: commandId,
      label,
      domain,
    },
  };
}

function summarizeNativeOutput(value, maxLength = 260) {
  const text = String(value ?? "")
    .trim()
    .replaceAll(/\s+/gu, " ");
  if (text.length <= maxLength) {
    return text;
  }
  return `${text.slice(0, maxLength)}...`;
}

function requiredValue(value, name) {
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new Error(`Director desktop action requires ${name}.`);
  }
  return value;
}

function requiredBoolean(value, name) {
  if (typeof value !== "boolean") {
    throw new Error(`Director desktop action requires boolean ${name}.`);
  }
  return value;
}

function requiredRuntimeToolApprovalDecision(value) {
  if (value === "approve" || value === "reject") {
    return value;
  }
  throw new Error("Director desktop action requires runtime tool approval decision approve or reject.");
}

function requiredComfyUiLifecycleAction(value) {
  if (value === "status" || value === "start" || value === "stop" || value === "restart") {
    return value;
  }
  throw new Error("Director desktop action requires ComfyUI lifecycle action status/start/stop/restart.");
}

function requiredOptionalComfyUiGpuFlag(value) {
  if (value === undefined || value === null || value === "") {
    return undefined;
  }
  if (value === "--nvidia" || value === "--amd" || value === "--m-series" || value === "--cpu") {
    return value;
  }
  throw new Error("Director desktop action requires ComfyUI gpuFlag --nvidia/--amd/--m-series/--cpu.");
}

function requiredNonNegativeNumber(value, name) {
  if (typeof value !== "number" || !Number.isFinite(value) || value < 0) {
    throw new Error(`Director desktop action requires non-negative number ${name}.`);
  }
  return value;
}

function requiredHeartbeatIntervalMs(value, key) {
  if (key !== "heartbeat.intervalMs") {
    throw new Error(`Unknown Director runtime setting: ${key}`);
  }
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new Error("Director desktop action requires numeric heartbeat.intervalMs.");
  }
  return clampHeartbeatIntervalMs(value);
}

function clampHeartbeatIntervalMs(value) {
  return Math.min(
    MAX_HEARTBEAT_INTERVAL_MS,
    Math.max(MIN_HEARTBEAT_INTERVAL_MS, Math.trunc(value)),
  );
}

function normalizeOptionalIsoTimestamp(value) {
  if (value === undefined) {
    return null;
  }
  const normalized = requiredValue(value, "now");
  const parsed = Date.parse(normalized);
  if (!Number.isFinite(parsed)) {
    throw new Error("Director desktop action requires valid ISO timestamp now.");
  }
  return new Date(parsed).toISOString();
}

function normalizeStringList(value) {
  if (Array.isArray(value)) {
    return value.map((entry) => String(entry).trim()).filter(Boolean);
  }
  if (typeof value === "string") {
    return value
      .split(/[,\n]/u)
      .map((entry) => entry.trim())
      .filter(Boolean);
  }
  return [];
}

function requiredProviderSettingValue(value, key) {
  if (typeof value === "boolean") {
    return value;
  }
  const normalized = requiredValue(value, "value");
  if (key === "enabled") {
    if (/^(true|1|on|enable|enabled|开启|启用)$/iu.test(normalized)) {
      return true;
    }
    if (/^(false|0|off|disable|disabled|关闭|禁用)$/iu.test(normalized)) {
      return false;
    }
  }
  return normalized;
}

function requiredComfyUiSettingValue(value, key) {
  if (typeof value === "boolean") {
    return value;
  }
  const normalized = requiredValue(value, "value");
  if (key === "enabled") {
    if (/^(true|1|on|enable|enabled|开启|启用)$/iu.test(normalized)) {
      return true;
    }
    if (/^(false|0|off|disable|disabled|关闭|禁用)$/iu.test(normalized)) {
      return false;
    }
  }
  return normalized;
}

function requiredExternalToolManageOperation(value) {
  const normalized = requiredValue(value, "operation").trim().toLowerCase();
  if (["enable", "disable", "update", "delete", "install"].includes(normalized)) {
    return normalized;
  }
  if (/^(安装|部署)$/u.test(normalized)) {
    return "install";
  }
  if (/^(启用|开启|启动)$/u.test(normalized)) {
    return "enable";
  }
  if (/^(停用|禁用|关闭|停止)$/u.test(normalized)) {
    return "disable";
  }
  if (/^(更新|保存|修改)$/u.test(normalized)) {
    return "update";
  }
  if (/^(删除|移除|重置)$/u.test(normalized)) {
    return "delete";
  }
  throw new Error(`Unsupported external tool operation: ${String(value)}`);
}

function normalizeExternalToolManageSettings(settings) {
  if (!isPlainObject(settings)) {
    return {};
  }
  const allowedKeys = new Set([
    "enabled",
    "mode",
    "apiKey",
    "apiKeyEnvVar",
    "baseUrl",
    "localInstallPath",
    "defaultWorkflowPath",
    "outputDir",
    "profile",
    "positivePromptNodeId",
    "positivePromptInputName",
    "negativePromptNodeId",
    "negativePromptInputName",
  ]);
  const normalized = {};
  for (const [key, value] of Object.entries(settings)) {
    if (!allowedKeys.has(key)) {
      continue;
    }
    normalized[key] = requiredComfyUiSettingValue(value, key);
  }
  return normalized;
}

function normalizeExternalProviderManageSettings(settings, configFields) {
  if (!isPlainObject(settings)) {
    return {};
  }
  const allowedKeys = new Set((configFields ?? []).map((field) => field.key).filter(Boolean));
  const normalized = {};
  for (const [key, value] of Object.entries(settings)) {
    if (key === "enabled" || key === "__proto__" || key === "prototype" || key === "constructor") {
      continue;
    }
    if (allowedKeys.size > 0 && !allowedKeys.has(key)) {
      continue;
    }
    if (typeof value === "boolean") {
      normalized[key] = value;
    } else {
      normalized[key] = requiredValue(value, key);
    }
  }
  return normalized;
}

function resolveDesktopConversationRunRegistryPath(dataDir) {
  return join(dataDir, "conversation-runtime", "runs.json");
}

function resolveDesktopLearningArtifactStorePath(dataDir) {
  return join(dataDir, "conversation-runtime", "learning-artifacts.json");
}

function resolveDesktopToolEvidenceStorePath(dataDir) {
  return join(dataDir, "conversation-runtime", "tool-evidence");
}

function createDesktopPendingLearningConfirmationFromResult({
  learningArtifactStore,
  sessionKey,
  turnRunId,
  sourceKind,
  sourceRef,
  result,
}) {
  if (learningArtifactStore === undefined) {
    return null;
  }
  const enrichedResult = enrichDesktopPendingLearningArtifactResult(result);
  const roleScope = readDesktopLearningResultRoleScope(enrichedResult);
  const created = createPendingLearningArtifactFromResult({
    store: learningArtifactStore,
    sessionKey,
    turnRunId,
    sourceSurface: "desktop",
    sourceKind,
    sourceRef,
    result: enrichedResult,
    ...(roleScope === undefined ? {} : { roleScope }),
    observedAtMs: Date.now(),
  });
  return syncDesktopPendingLearningArtifactRuntimeMetadata({
    learningArtifactStore,
    result: enrichedResult,
    created,
  });
}

function readDesktopLearningResultRoleScope(result) {
  const roleScope = result?.metadata?.roleScope ?? result?.roleScope ?? result?.result?.roleScope;
  if (!isPlainObject(roleScope)) {
    return undefined;
  }
  const roleName =
    readNonEmptyString(roleScope.roleName) ??
    readNonEmptyString(roleScope.title) ??
    readNonEmptyString(roleScope.name);
  const domain = readNonEmptyString(roleScope.domain);
  const responsibilityTags = uniqueStringArray([
    ...(Array.isArray(roleScope.responsibilityTags) ? roleScope.responsibilityTags : []),
    ...(Array.isArray(roleScope.learningScope) ? roleScope.learningScope : []),
    ...(Array.isArray(roleScope.focus) ? roleScope.focus : []),
  ].filter((item) => typeof item === "string" && item.trim().length > 0));
  if (roleName === undefined || domain === undefined || responsibilityTags.length === 0) {
    return undefined;
  }
  return {
    roleName,
    domain,
    responsibilityTags,
  };
}

function syncDesktopPendingLearningArtifactRuntimeMetadata({
  learningArtifactStore,
  result,
  created,
}) {
  const artifact = created?.artifact;
  if (artifact === undefined) {
    return created;
  }
  const metadataPatch = readDesktopLearningResultRuntimeMetadata(result);
  if (Object.keys(metadataPatch).length === 0) {
    return created;
  }
  const nextMetadata = compactDesktopMetadata({
    ...(artifact.metadata ?? {}),
    ...metadataPatch,
  });
  if (JSON.stringify(nextMetadata) === JSON.stringify(artifact.metadata ?? {})) {
    return created;
  }
  const updated = {
    ...artifact,
    metadata: nextMetadata,
    updatedAtMs: Date.now(),
  };
  learningArtifactStore.upsertArtifact(updated);
  return {
    ...created,
    artifact: updated,
  };
}

function readDesktopLearningResultRuntimeMetadata(result) {
  const metadata = isPlainObject(result?.metadata) ? result.metadata : {};
  return compactDesktopMetadata({
    roleScopedScheduledLearning:
      typeof metadata.roleScopedScheduledLearning === "boolean"
        ? metadata.roleScopedScheduledLearning
        : undefined,
    roleId: readNonEmptyString(metadata.roleId),
    learningScope: Array.isArray(metadata.learningScope)
      ? metadata.learningScope.filter((item) => typeof item === "string" && item.trim().length > 0)
      : undefined,
    sourcePolicy: isPlainObject(metadata.sourcePolicy) ? metadata.sourcePolicy : undefined,
    triggerReason:
      readNonEmptyString(metadata.triggerReason) ?? readNonEmptyString(metadata.learningReason),
    candidateOnly: typeof metadata.candidateOnly === "boolean" ? metadata.candidateOnly : undefined,
    autoPublish: typeof metadata.autoPublish === "boolean" ? metadata.autoPublish : undefined,
    memorySync: readNonEmptyString(metadata.memorySync),
  });
}

function compactDesktopMetadata(value) {
  return Object.fromEntries(
    Object.entries(value).filter(([, entry]) => {
      if (entry === undefined || entry === null) {
        return false;
      }
      if (Array.isArray(entry)) {
        return entry.length > 0;
      }
      return true;
    }),
  );
}

function enrichDesktopPendingLearningArtifactResult(result) {
  const candidates = readDesktopLearningCandidates(result);
  const candidateIds = readDesktopLearningCandidateIds(result);
  const mediaEvidenceRefs = readDesktopLearningPendingMediaEvidenceRefs(result);
  const mediaInventory = resolveDesktopLearningResultMediaInventory(result);
  const mediaAuthorizationRequest =
    mediaInventory?.assetCount > 0
      ? createDesktopLearningMediaAuthorizationRequest(
          createDesktopLearningEvidenceMediaInventory(mediaInventory),
        )
      : null;
  const mediaMetadata =
    mediaInventory?.assetCount > 0
      ? {
          mediaInventory,
          mediaAuthorizationRequest,
          mediaUnderstandingStatus: "not_understood_without_user_authorization",
        }
      : {};
  if (candidates.length === 0 && candidateIds.length === 0) {
    return mediaEvidenceRefs.length === 0 && Object.keys(mediaMetadata).length === 0
      ? result
      : {
          ...(isPlainObject(result) ? result : {}),
          mediaEvidenceRefs,
          metadata: {
            ...(isPlainObject(result?.metadata) ? result.metadata : {}),
            ...mediaMetadata,
          },
        };
  }
  return {
    ...(isPlainObject(result) ? result : {}),
    ...(candidateIds.length === 0 ? {} : { candidateIds }),
    ...(candidates.length === 0 ? {} : { candidates }),
    ...(mediaEvidenceRefs.length === 0 ? {} : { mediaEvidenceRefs }),
    metadata: {
      ...(isPlainObject(result?.metadata) ? result.metadata : {}),
      ...mediaMetadata,
    },
    result: {
      ...(isPlainObject(result?.result) ? result.result : {}),
      candidateCount: readLearningCandidateCount(result),
      ...(candidateIds.length === 0 ? {} : { candidateIds }),
      ...(candidates.length === 0 ? {} : { candidates }),
    },
  };
}

function readDesktopLearningPendingMediaEvidenceRefs(result) {
  const direct = readDesktopLearningMediaEvidenceRefsFromUnknown(result?.mediaEvidenceRefs);
  if (direct.length > 0) {
    return direct;
  }
  const report = isPlainObject(result?.learningReport) ? result.learningReport : null;
  const reportRefs = readDesktopLearningMediaEvidenceRefsFromUnknown(report?.mediaEvidenceRefs);
  if (reportRefs.length > 0) {
    return reportRefs;
  }
  const inventory = resolveDesktopLearningResultMediaInventory(result);
  if (inventory?.assetCount > 0) {
    const evidenceRefs = createMediaEvidenceRefsFromInventory(inventory, {
      evidencePrefix: `desktop-learning-media-${hashDesktopRuntimeText(
        readDesktopLearningResultSourceRef(result) ?? "source",
      )}`,
    });
    if (evidenceRefs.length > 0) {
      return evidenceRefs;
    }
    return createDesktopCountOnlyMediaEvidenceRefsFromInventory(inventory, {
      sourceRef: readDesktopLearningResultSourceRef(result) ?? "desktop-learning-source",
      evidencePrefix: `desktop-learning-media-${hashDesktopRuntimeText(
        readDesktopLearningResultSourceRef(result) ?? "source",
      )}`,
    });
  }
  return [];
}

function createDesktopCountOnlyMediaEvidenceRefsFromInventory(inventory, { sourceRef, evidencePrefix }) {
  const refs = [];
  for (const kind of ["image", "video", "audio", "poster", "blob", "unknown"]) {
    const count = readDesktopMediaInventoryKindCount(inventory, kind);
    for (let index = 1; index <= count; index += 1) {
      refs.push(
        createMediaEvidenceRef({
          id: `${evidencePrefix}-${kind}-${index}`,
          sourceRef: `${sourceRef}#media-${kind}-${index}`,
          status: "listed_only",
          publishable: false,
          metadata: {
            mediaType: kind === "poster" ? "image" : kind === "blob" ? "video" : kind,
            inventoryKind: kind,
            origin: "desktop.media_inventory.count_only",
            scope: "primary",
            sourceUrl: sourceRef,
            locatorUnavailable: true,
            evidenceBoundary:
              "媒体清单来自来源元数据或正文计数；未获得媒体文件 URL，未做视觉/视频/音频理解。",
          },
        }),
      );
    }
  }
  return refs;
}

function readDesktopMediaInventoryKindCount(inventory, kind) {
  if (kind === "image") {
    return readFiniteNumber(inventory?.imageCount) ?? 0;
  }
  if (kind === "video") {
    return readFiniteNumber(inventory?.videoCount) ?? 0;
  }
  if (kind === "audio") {
    return readFiniteNumber(inventory?.audioCount) ?? 0;
  }
  if (kind === "poster") {
    return readFiniteNumber(inventory?.posterCount) ?? 0;
  }
  if (kind === "blob") {
    return readFiniteNumber(inventory?.blobCount) ?? 0;
  }
  return readFiniteNumber(inventory?.unknownCount) ?? 0;
}

function readDesktopLearningMediaEvidenceRefsFromUnknown(value) {
  if (!Array.isArray(value)) {
    return [];
  }
  return value
    .filter(isPlainObject)
    .map((item) => ({
      id:
        readNonEmptyString(item.id) ??
        `desktop-learning-media-${hashDesktopRuntimeText(
          `${readNonEmptyString(item.sourceRef) ?? readNonEmptyString(item.url) ?? "source"}:${JSON.stringify(item)}`,
        )}`,
      sourceRef:
        readNonEmptyString(item.sourceRef) ??
        readNonEmptyString(item.source_ref) ??
        readNonEmptyString(item.url) ??
        "",
      status: readNonEmptyString(item.status) ?? "listed_only",
      realVisualUnderstanding: item.realVisualUnderstanding === true,
      confidence: readNonEmptyString(item.confidence) ?? "low",
      publishable: item.publishable === true,
      privacy: readNonEmptyString(item.privacy) ?? "pii_potential",
      metadata: isPlainObject(item.metadata) ? item.metadata : {},
    }))
    .filter((item) => item.sourceRef.length > 0);
}

function resolveDesktopLearningResultMediaInventory(result) {
  const candidates = [
    result?.mediaInventory,
    result?.media_inventory,
    result?.learningReport?.mediaInventory,
    result?.learningReport?.media_inventory,
    result?.urlRead?.source?.mediaInventory,
    result?.urlRead?.source?.media_inventory,
    result?.urlRead?.source?.structuredContent?.mediaInventory,
    result?.urlRead?.source?.structuredContent?.media_inventory,
    result?.structuredContent?.output?.mediaInventory,
    result?.structuredContent?.output?.media_inventory,
    result?.urlRead?.source?.structuredContent?.output?.mediaInventory,
    result?.urlRead?.source?.structuredContent?.output?.media_inventory,
    result?.evidenceDisclosure?.sources?.[0]?.mediaInventory,
    result?.evidenceDisclosure?.sources?.[0]?.media_inventory,
  ];
  let fallback = null;
  for (const candidate of candidates) {
    if (isDesktopConversationMediaInventory(candidate)) {
      const normalized = normalizeDesktopConversationMediaInventory(candidate);
      if (normalized.assets.length > 0) {
        return normalized;
      }
      fallback ??= normalized;
    }
  }
  const sourceRef = readDesktopLearningResultSourceRef(result);
  const inventory = createConversationRuntimeMediaInventory({
    body: [
      typeof result?.urlRead?.source?.body === "string" ? result.urlRead.source.body : "",
      typeof result?.urlRead?.source?.sourceSnapshot === "string"
        ? result.urlRead.source.sourceSnapshot
        : "",
      typeof result?.learningReport === "string" ? result.learningReport : "",
    ]
      .filter((item) => item.length > 0)
      .join("\n"),
    structuredContent:
      result?.structuredContent ??
      result?.urlRead?.source?.structuredContent ??
      result?.urlRead?.source?.externalContent,
    sourceSnapshot: result?.urlRead?.source?.sourceSnapshot,
    ...(sourceRef === undefined ? {} : { sourceUrl: sourceRef }),
  });
  if (inventory.assetCount > 0) {
    return inventory;
  }
  return fallback?.assetCount > 0 ? fallback : null;
}

function isDesktopConversationMediaInventory(value) {
  return (
    isPlainObject(value) &&
    (value.schemaVersion === "conversation-runtime.media-inventory.v1" ||
      value.schemaVersion === "director.desktop.media-inventory.v1" ||
      value.schemaVersion === undefined) &&
    readFiniteNumber(value.assetCount) !== null
  );
}

function normalizeDesktopConversationMediaInventory(value) {
  const assetCount = readFiniteNumber(value?.assetCount) ?? 0;
  const imageCount = readFiniteNumber(value?.imageCount) ?? 0;
  const videoCount = readFiniteNumber(value?.videoCount) ?? 0;
  const audioCount = readFiniteNumber(value?.audioCount) ?? 0;
  const posterCount = readFiniteNumber(value?.posterCount) ?? 0;
  const blobCount = readFiniteNumber(value?.blobCount) ?? 0;
  const explicitUnknownCount = readFiniteNumber(value?.unknownCount);
  const unknownCount =
    explicitUnknownCount ??
    Math.max(0, assetCount - imageCount - videoCount - audioCount - posterCount - blobCount);
  return {
    ...(isPlainObject(value) ? value : {}),
    schemaVersion:
      value.schemaVersion === "conversation-runtime.media-inventory.v1"
        ? "conversation-runtime.media-inventory.v1"
        : value.schemaVersion === "director.desktop.media-inventory.v1"
          ? "director.desktop.media-inventory.v1"
          : "director.desktop.media-inventory.v1",
    assetCount,
    imageCount,
    videoCount,
    audioCount,
    posterCount,
    blobCount,
    unknownCount,
    assets: Array.isArray(value?.assets) ? value.assets : [],
  };
}

function readDesktopLearningResultSourceRef(result) {
  return readFirstString([
    result?.urlRead?.source?.url,
    result?.urlRead?.source?.externalContent?.final_url,
    result?.urlRead?.source?.externalContent?.source_url,
    result?.evidenceDisclosure?.sources?.[0]?.url,
  ]);
}

async function persistDesktopLearningConfirmation({
  payload,
  workspaceRoot,
  dataDir,
  knowledge,
  hostApiUrl,
  hostApiFetch,
  apiProviderFetch,
}) {
  const artifact = payload.artifact;
  const resolvedDataDir =
    dataDir ?? payload.input?.trustedContext?.dataDir ?? payload.input?.metadata?.dataDir;
  const confirmationPersistenceInput = {
    dataDir: resolvedDataDir,
    input: {
      text: payload.input?.text ?? payload.decision.decisionText,
      sessionKey: payload.input?.sessionKey ?? payload.confirmation.sessionKey,
      channel: payload.input?.channel ?? "desktop",
      surface: payload.input?.surface ?? "desktop",
      ...(payload.input?.messageId === undefined ? {} : { messageId: payload.input.messageId }),
    },
    turnId: payload.turnId,
    artifact,
    confirmation: payload.confirmation,
  };
  const existingCandidateIds = Array.isArray(payload.decision?.candidateIds)
    ? payload.decision.candidateIds.filter((id) => typeof id === "string" && id.length > 0)
    : [];
  if (existingCandidateIds.length > 0) {
    const blockedReview = await findRejectedDesktopLearningConfirmationCandidate({
      candidateIds: existingCandidateIds,
      workspaceRoot,
      knowledge,
      hostApiUrl,
      hostApiFetch,
    });
    if (blockedReview !== null) {
      return {
        status: "candidate-confirmation-blocked",
        candidateIds: existingCandidateIds,
        auditId: `learning-confirm-blocked-${String(payload.confirmation.confirmationId).replace(/[^a-z0-9._-]/giu, "-")}`,
        message: `候选 ${blockedReview.candidateId} 最新审核已拒绝，不能用自然语言确认复活。请重新学习正确来源后再保存。`,
        metadata: {
          artifactId: artifact.artifactId,
          confirmationId: payload.confirmation.confirmationId,
          blockedCandidateId: blockedReview.candidateId,
          latestReview: blockedReview.latestReview,
        },
      };
    }
    const accepted = [];
    for (const candidateId of existingCandidateIds) {
      const result = hostApiUrl
        ? await decideDesktopExperienceViaHostApi(
            { hostApiUrl, fetchFn: hostApiFetch },
            {
              candidateId,
              action: "accept",
              actor: "director-desktop-runtime",
              note: createDesktopLearningConfirmationNote(payload),
            },
          )
        : await knowledge.decideDirectorExperienceCandidateStructured(workspaceRoot, {
            candidateId,
            decision: "accepted",
            author: "director-desktop-runtime",
            note: createDesktopLearningConfirmationNote(payload),
          });
      accepted.push({ candidateId, result });
    }
    const repositoryPersistence = await persistAcceptedLearningConfirmationToRepository({
      ...confirmationPersistenceInput,
      decision: {
        kind: "accept",
        confirmationId: payload.confirmation.confirmationId,
        artifactId: artifact.artifactId,
        candidateIds: existingCandidateIds,
        ...(payload.decision.acceptedByMessageId === undefined
          ? {}
          : { acceptedByMessageId: payload.decision.acceptedByMessageId }),
        decisionText: payload.decision.decisionText,
      },
    });
    return {
      status: repositoryPersistence.status,
      candidateIds: repositoryPersistence.candidateIds ?? existingCandidateIds,
      auditId:
        repositoryPersistence.auditId ??
        `learning-confirm-accept-${String(payload.confirmation.confirmationId).replace(/[^a-z0-9._-]/giu, "-")}`,
      message: `已确认 ${existingCandidateIds.length} 条经验候选，已进入待审经验候选，等待发布审核。`,
      metadata: {
        accepted,
        repositoryPersistence,
        artifactId: artifact.artifactId,
        confirmationId: payload.confirmation.confirmationId,
      },
    };
  }
  const sourceId = `learning-confirm-${String(artifact.artifactId ?? payload.turnId).replace(/[^a-z0-9._-]/giu, "-")}`;
  const title = artifact.classification?.topic ?? artifact.sourceRef ?? "已确认经验";
  const body = createDesktopLearningConfirmationBody(payload);
  const result = hostApiUrl
    ? await learnDesktopAdmitViaHostApi(
        { hostApiUrl, fetchFn: hostApiFetch },
        {
          sourceId,
          sources: [
            {
              title,
              body,
              sourceRef: artifact.sourceRef,
              contentType: "text/plain",
            },
          ],
          privacy: artifact.privacy === "public" ? "public" : "internal",
        },
      )
    : await knowledge.learnDirectorExperience(workspaceRoot, {
        sourceId,
        texts: [
          {
            title,
            content: body,
            sourceRef: artifact.sourceRef,
          },
        ],
        privacy: artifact.privacy === "public" ? "public" : "internal",
        ...(apiProviderFetch === undefined ? {} : { apiProviderFetch }),
      });
  const candidateIds = readDesktopLearningCandidates(result)
    .map((candidate) => candidate?.candidateId ?? candidate?.id)
    .filter((id) => typeof id === "string" && id.length > 0);
  if (candidateIds.length > 0) {
    const repositoryPersistence = await persistAcceptedLearningConfirmationToRepository({
      ...confirmationPersistenceInput,
      decision: {
        kind: "accept",
        confirmationId: payload.confirmation.confirmationId,
        artifactId: artifact.artifactId,
        candidateIds,
        ...(payload.decision.acceptedByMessageId === undefined
          ? {}
          : { acceptedByMessageId: payload.decision.acceptedByMessageId }),
        decisionText: payload.decision.decisionText,
      },
    });
    return {
      status: repositoryPersistence.status,
      candidateIds: repositoryPersistence.candidateIds ?? candidateIds,
      auditId: repositoryPersistence.auditId ?? sourceId,
      message: `已确认 ${candidateIds.length} 条经验候选，已进入待审经验候选，等待发布审核。`,
      metadata: {
        result,
        repositoryPersistence,
        artifactId: artifact.artifactId,
        confirmationId: payload.confirmation.confirmationId,
      },
    };
  }
  return {
    status:
      readLearningFailureCount(result) > 0 && readLearningCandidateCount(result) === 0
        ? "quarantined"
        : "candidate-created",
    candidateIds,
    auditId: sourceId,
    message:
      readLearningCandidateCount(result) > 0
        ? "已进入经验候选，后续会按岗位经验召回。"
        : "已记录确认，但这条内容还没有形成可用经验候选。",
    metadata: {
      result,
      artifactId: artifact.artifactId,
      confirmationId: payload.confirmation.confirmationId,
    },
  };
}

async function findRejectedDesktopLearningConfirmationCandidate({
  candidateIds,
  workspaceRoot,
  knowledge,
  hostApiUrl,
  hostApiFetch,
}) {
  if (candidateIds.length === 0) {
    return null;
  }
  const candidateIdSet = new Set(candidateIds);
  const inspection = hostApiUrl
    ? createExperienceInspectionFromHostCatalog(
        await readDesktopHostCatalogSnapshot({ hostApiUrl, fetchFn: hostApiFetch }),
      )
    : await knowledge.inspectDirectorExperienceCandidates(workspaceRoot);
  for (const entry of Array.isArray(inspection?.candidates) ? inspection.candidates : []) {
    const candidateId = readNonEmptyString(entry?.candidate?.candidateId ?? entry?.id);
    if (candidateId === undefined || !candidateIdSet.has(candidateId)) {
      continue;
    }
    const latestReview = isPlainObject(entry?.latestReview) ? entry.latestReview : null;
    const status = String(entry?.status ?? latestReview?.decision ?? "").toLowerCase();
    if (status === "rejected") {
      return {
        candidateId,
        latestReview,
      };
    }
  }
  return null;
}

function createDesktopLearningConfirmationBody(payload) {
  const artifact = payload.artifact;
  return [
    `来源：${artifact.sourceRef}`,
    `岗位：${artifact.roleScope?.roleName ?? "Director Angel"}`,
    `领域：${artifact.roleScope?.domain ?? "影视制作"}`,
    `确认文本：${payload.decision.decisionText}`,
    artifact.classification === undefined
      ? ""
      : [
          `主题：${artifact.classification.topic}`,
          `用途：${(artifact.classification.useCases ?? []).join("、")}`,
          `标签：${(artifact.classification.tags ?? []).join("、")}`,
        ]
          .filter(Boolean)
          .join("\n"),
    (artifact.qualityGates ?? []).length === 0
      ? "质量门：通过"
      : `质量门：${artifact.qualityGates.join("、")}`,
    `证据：${[
      ...(artifact.evidenceRefs ?? []),
      ...(artifact.mediaEvidenceRefs ?? []).map((evidence) => evidence.id),
    ].join("、")}`,
  ]
    .filter((line) => String(line).trim().length > 0)
    .join("\n");
}

function createDesktopLearningConfirmationNote(payload) {
  return [
    "用户在当前会话确认保存这条学习候选。",
    `确认文本：${payload.decision?.decisionText ?? ""}`,
    `来源：${payload.artifact?.sourceRef ?? ""}`,
    `确认对象：${payload.confirmation?.confirmationId ?? ""}`,
  ]
    .filter((line) => String(line).trim().length > 0)
    .join("\n");
}

function startDesktopConversationTask(store, { turnId, sessionKey, prompt, action }) {
  if (!store || typeof store.upsert !== "function") {
    return null;
  }
  const now = Date.now();
  const runtimeSessionKey =
    readNonEmptyString(sessionKey) ?? resolveDesktopConversationRuntimeSessionKey(action);
  return store.upsert({
    id: createDesktopConversationTaskId(turnId, runtimeSessionKey),
    turnId,
    sessionKey: runtimeSessionKey,
    promptPreview: summarizeNativeOutput(prompt, 180),
    actionType: action.type,
    status: "running",
    progress: 15,
    model: readNonEmptyString(action.model) ?? "runtime",
    provider: "conversation-runtime",
    activeRunId: readNonEmptyString(action.runId) ?? null,
    replySource: null,
    runtimeEvents: [],
    runtimeEventCount: 0,
    toolCount: 0,
    pendingApprovalCount: 0,
    approvalIds: [],
    artifactIds: [],
    finalTextPreview: null,
    cancelReason: null,
    createdAt: now,
    startedAt: now,
    updatedAt: now,
    events: [
      createDesktopConversationTaskEvent("conversation.queued", "普通对话已排队", "等待模型/工具运行。", now, 0),
      createDesktopConversationTaskEvent("conversation.started", "普通对话已开始", "ConversationRuntime 已开始处理本回合。", now, 15),
    ],
  });
}

function completeDesktopConversationTask(store, { turnId, sessionKey, runtimeResult, runResult, runtimeToolApproval, evidenceDisclosure }) {
  if (!store || typeof store.get !== "function" || typeof store.upsert !== "function") {
    return null;
  }
  const runtimeSessionKey =
    readNonEmptyString(sessionKey) ??
    readDesktopConversationRuntimeResultSessionKey(runtimeResult) ??
    "desktop:workbench";
  const taskId = createDesktopConversationTaskId(turnId, runtimeSessionKey);
  const previous = store.get(taskId);
  const now = Date.now();
  const runtimeEvents = Array.isArray(runtimeResult?.events) ? runtimeResult.events : [];
  const runtimeEventsV1 = Array.isArray(runtimeResult?.runtimeEventsV1)
    ? runtimeResult.runtimeEventsV1
    : [];
  const approvalIds = collectDesktopConversationApprovalIds(runtimeResult, runtimeToolApproval);
  const pendingApprovalCount =
    readFiniteNumber(runtimeToolApproval?.pendingCount) ??
    runtimeEvents.filter((event) => event.kind === "runtime.approval" && event.payload?.approval?.status === "pending").length;
  const toolCount = countUniqueConversationRuntimeToolCalls(runtimeEvents);
  const artifactIds = Array.isArray(runtimeResult?.artifactIds) ? [...runtimeResult.artifactIds] : [];
  const projectedEvidenceDisclosure = evidenceDisclosure ?? createDesktopEvidenceDisclosure(runtimeResult);
  const projectedRuntimeReply = projectConversationRuntimeClientReply({
    surface: "desktop.rich",
    result: runtimeResult,
    evidenceDisclosure: projectedEvidenceDisclosure,
  });
  const projectedFinalText =
    typeof runtimeResult?.finalText === "string" ||
    typeof runtimeResult?.userFacingProjection?.userText === "string"
      ? projectedRuntimeReply.mainText
      : null;
  const wasCancelled = previous?.status === "cancelled" || runtimeResult?.replySource === "local-command";
  const status =
    wasCancelled
      ? "cancelled"
      : pendingApprovalCount > 0
      ? "needs_attention"
      : runtimeResult?.replySource === "degraded-error" || runResult?.ok === false
        ? "failed"
        : "completed";
  const progress = status === "completed" ? 100 : status === "needs_attention" ? 65 : 100;
  const nextEvents = [
    ...(previous?.events ?? [
      createDesktopConversationTaskEvent("conversation.queued", "普通对话已排队", "等待模型/工具运行。", now, 0),
    ]),
    ...formatRuntimeEventsAsConversationTaskEvents(runtimeEvents),
  ];
  if (status === "cancelled") {
    nextEvents.push(
      createDesktopConversationTaskEvent(
        "conversation.cancelled",
        "普通对话已取消",
        previous?.cancelReason ?? runResult?.message ?? "当前普通对话已停止。",
        now,
        100,
      ),
    );
  } else if (pendingApprovalCount > 0) {
    nextEvents.push(
      createDesktopConversationTaskEvent(
        "conversation.approval.pending",
        "普通对话等待人工批准",
        createConversationApprovalTaskMessage(runtimeEvents),
        now,
        progress,
      ),
    );
  } else if (status === "completed") {
    nextEvents.push(
      createDesktopConversationTaskEvent(
        "conversation.completed",
        "普通对话已完成",
        projectedFinalText ?? runResult?.output ?? "ConversationRuntime 已完成本回合。",
        now,
        100,
      ),
    );
  } else {
    nextEvents.push(
      createDesktopConversationTaskEvent(
        "conversation.failed",
        "普通对话失败",
        runResult?.message ??
          renderConversationRuntimeUserFacingFailureReply({
            code: "runtime_failed",
            surface: "desktop",
          }).text,
        now,
        100,
      ),
    );
  }
  return store.upsert({
    ...(previous ?? {}),
    id: taskId,
    turnId,
    sessionKey: runtimeSessionKey,
    turnRunId: runtimeResult?.turnRunId ?? previous?.turnRunId ?? null,
    actionType: previous?.actionType ?? DESKTOP_ACTIONS.COMPOSER_SUBMIT,
    status,
    progress,
    model: readNonEmptyString(runResult?.model) ?? previous?.model ?? "runtime",
    provider: "conversation-runtime",
    replySource: runtimeResult?.replySource ?? null,
    runtimeEvents,
    runtimeEventsV1,
    runtimeEventCount: runtimeEvents.length,
    evidenceDisclosure: projectedEvidenceDisclosure,
    clientProjection: projectedRuntimeReply,
    toolCount,
    pendingApprovalCount,
    approvalIds,
    artifactIds,
    finalTextPreview:
      typeof projectedFinalText === "string"
        ? summarizeNativeOutput(projectedFinalText, 240)
        : typeof runResult?.output === "string"
          ? summarizeNativeOutput(runResult.output, 240)
          : null,
    finalText:
      typeof projectedFinalText === "string"
        ? projectedFinalText
        : typeof runResult?.output === "string"
          ? runResult.output
          : null,
    error:
      status === "needs_attention"
        ? `等待人工批准：${approvalIds.join(", ") || "runtime.approval"}`
        : status === "failed"
          ? runResult?.message ??
            renderConversationRuntimeUserFacingFailureReply({
              code: "runtime_failed",
              surface: "desktop",
            }).text
          : status === "cancelled"
            ? previous?.cancelReason ?? runResult?.message ?? undefined
          : undefined,
    updatedAt: now,
    completedAt: isActiveDesktopTaskStatus(status) ? undefined : now,
    events: dedupeConversationTaskEvents(nextEvents),
  });
}

function createDesktopEvidenceDisclosure(runtimeResult) {
  if (isPlainObject(runtimeResult?.evidenceDisclosure)) {
    const sources = Array.isArray(runtimeResult.evidenceDisclosure.sources)
      ? runtimeResult.evidenceDisclosure.sources
      : [];
    return {
      schemaVersion:
        readStringProperty(runtimeResult.evidenceDisclosure, "schemaVersion") ??
        "director.desktop.evidence-disclosure.v1",
      sourceCount: sources.length,
      sources,
    };
  }
  const sources = collectDesktopEvidenceDisclosureSources(runtimeResult);
  return {
    schemaVersion: "director.desktop.evidence-disclosure.v1",
    sourceCount: sources.length,
    sources,
  };
}

function collectDesktopEvidenceDisclosureSources(runtimeResult) {
  const sourcesByUrl = new Map();
  for (const event of runtimeResult?.events ?? []) {
    if (
      event?.kind !== "runtime.tool" ||
      (event.payload?.tool?.phase !== "completed" && event.payload?.tool?.phase !== "failed")
    ) {
      continue;
    }
    const toolName = event.payload?.tool?.name;
    if (
      toolName !== "web_extract" &&
      toolName !== "web_extract_artifact_read" &&
      toolName !== "browser_snapshot" &&
      toolName !== "browser_navigate" &&
      toolName !== "director.opencli.invoke" &&
      toolName !== "director.experience.candidates.list"
    ) {
      continue;
    }
    const output = readDesktopRuntimeToolOutput(event);
    if (!isPlainObject(output)) {
      continue;
    }
    if (toolName === "director.experience.candidates.list") {
      const disclosure = isPlainObject(output.evidenceDisclosure)
        ? output.evidenceDisclosure
        : isPlainObject(event.payload?.tool?.metadata?.toolResultMetadata?.evidenceDisclosure)
          ? event.payload.tool.metadata.toolResultMetadata.evidenceDisclosure
          : null;
      if (disclosure !== null && Array.isArray(disclosure.sources)) {
        for (const source of disclosure.sources.filter(isPlainObject)) {
          const sourceUrl = readStringProperty(source, "url");
          if (sourceUrl === null) {
            continue;
          }
          const previous = sourcesByUrl.get(sourceUrl);
          sourcesByUrl.set(sourceUrl, previous === undefined ? source : { ...previous, ...source });
        }
      }
      continue;
    }
    const url =
      readStringProperty(output, "url") ??
      readStringProperty(output, "source_ref") ??
      readStringProperty(output, "sourceUrl") ??
      readStringProperty(event.payload?.tool?.metadata?.toolResultMetadata, "sourceUrl") ??
      readStringProperty(
        event.payload?.tool?.metadata?.toolResultMetadata?.externalToolMetadata,
        "sourceUrl",
      );
    if (url === null) {
      continue;
    }
    const phase = event.payload?.tool?.phase;
    const openCliText =
      toolName === "director.opencli.invoke" ? readDesktopRuntimeToolEvidenceText(output) : "";
    const sourceAccessStatus = readDesktopEvidenceSourceAccessStatus({
      output,
      event,
      phase,
    });
    const failedReason =
      sourceAccessStatus === "failed"
        ? readDesktopEvidenceFailedReason({ output, event })
        : null;
    const previous = sourcesByUrl.get(url) ?? {
      url,
      title: "",
      fullBodyChars: 0,
      previewChars: 0,
      bodyTruncatedForModel: false,
      secondPassExtracted: false,
      mediaCount: 0,
      mediaInventory: null,
      mediaAuthorization: null,
      mediaAdmission: null,
      evidenceProvenance: null,
      persisted: false,
      admitted: false,
      sourceAccessStatus: "available",
      readStatus: "read",
      failedReason: null,
      mediaUnderstandingStatus: "not_understood_without_user_authorization",
    };
    const disclosure = isPlainObject(output.evidence_disclosure) ? output.evidence_disclosure : null;
    const mediaInventory = isPlainObject(output.media_inventory) ? output.media_inventory : null;
    const evidenceProvenance = isPlainObject(output.evidence_provenance)
      ? output.evidence_provenance
      : null;
    const mediaUnderstandingWorkflow = isPlainObject(output.media_understanding_workflow)
      ? output.media_understanding_workflow
      : null;
    const mediaAuthorization = isPlainObject(mediaUnderstandingWorkflow?.authorization?.request)
      ? mediaUnderstandingWorkflow.authorization.request
      : isPlainObject(output.learning_gate?.mediaAuthorizationRequest)
        ? output.learning_gate.mediaAuthorizationRequest
        : isPlainObject(output.mediaAuthorizationRequest)
          ? output.mediaAuthorizationRequest
          : null;
    const mediaAdmission = isPlainObject(mediaUnderstandingWorkflow?.admission)
      ? mediaUnderstandingWorkflow.admission
      : null;
    const browserSnapshotText =
      toolName === "browser_snapshot" || toolName === "browser_navigate"
        ? readDesktopBrowserSnapshotText(output)
        : "";
    const isSocialBrowserSnapshot =
      (toolName === "browser_snapshot" || toolName === "browser_navigate") &&
      isDesktopMediaRichSocialUrl(url);
    const hasBrowserText = browserSnapshotText.trim().length > 0;
    const mediaBoundaryRequired =
      mediaUnderstandingWorkflow?.mediaUnderstandingStatus === "not_understood" ||
      mediaAdmission?.requiredNextAction === "request_user_authorization" ||
      (isSocialBrowserSnapshot && (toolName === "browser_snapshot" || hasBrowserText));
    const fallbackMediaInventory =
      mediaInventory ??
      (mediaBoundaryRequired
        ? createDesktopUnverifiedMediaInventory({
            sourceUrl: url,
            reason: isSocialBrowserSnapshot
              ? "dynamic-social-browser-snapshot"
              : "browser-snapshot-media-not-verified",
          })
        : null);
    const fallbackMediaAdmission =
      mediaAdmission ??
      (mediaBoundaryRequired
        ? createDesktopMediaEvidenceBoundaryAdmission({
            mediaInventory: fallbackMediaInventory,
            reason: isSocialBrowserSnapshot
              ? "dynamic_social_media_requires_authorization"
              : "media_requires_authorization",
          })
        : null);
    sourcesByUrl.set(url, {
      ...previous,
      title:
        readStringProperty(output, "title") ??
        readStringProperty(disclosure, "title") ??
        previous.title,
      fullBodyChars:
        readFiniteNumber(output.full_body_chars) ??
        readFiniteNumber(disclosure?.full_body_chars) ??
        (openCliText.length > 0 ? openCliText.length : null) ??
        (browserSnapshotText.length > 0 ? browserSnapshotText.length : previous.fullBodyChars),
      previewChars:
        readFiniteNumber(output.preview_chars) ??
        readFiniteNumber(disclosure?.preview_chars) ??
        (openCliText.length > 0 ? Math.min(openCliText.length, 1200) : null) ??
        (browserSnapshotText.length > 0 ? browserSnapshotText.length : previous.previewChars),
      bodyTruncatedForModel:
        output.body_truncated_for_model === true ||
        disclosure?.body_truncated_for_model === true ||
        previous.bodyTruncatedForModel,
      secondPassExtracted:
        event.payload?.tool?.name === "web_extract_artifact_read" ||
        event.payload?.tool?.name === "director.opencli.invoke" ||
        disclosure?.secondPassExtracted === true ||
        disclosure?.second_pass_extracted === true ||
        previous.secondPassExtracted,
      mediaCount:
        readFiniteNumber(evidenceProvenance?.media?.assetCount) ??
        readFiniteNumber(fallbackMediaInventory?.assetCount) ??
        readFiniteNumber(disclosure?.media_count) ??
        previous.mediaCount,
      mediaInventory: fallbackMediaInventory ?? previous.mediaInventory,
      mediaAuthorization: mediaAuthorization ?? previous.mediaAuthorization,
      mediaAdmission: fallbackMediaAdmission ?? previous.mediaAdmission,
      evidenceProvenance: evidenceProvenance ?? previous.evidenceProvenance,
      persisted:
        sourceAccessStatus === "failed"
          ? previous.persisted
          : disclosure?.persisted === true ||
            isPlainObject(output.full_body_artifact) ||
            Array.isArray(output.artifacts) ||
            previous.persisted,
      admitted: previous.admitted,
      sourceAccessStatus:
        sourceAccessStatus === "failed" ? "failed" : previous.sourceAccessStatus ?? "available",
      readStatus: sourceAccessStatus === "failed" ? "failed" : previous.readStatus ?? "read",
      failedReason: failedReason ?? previous.failedReason,
      mediaUnderstandingStatus:
        readStringProperty(mediaUnderstandingWorkflow, "mediaUnderstandingStatus") ??
        readStringProperty(mediaUnderstandingWorkflow, "media_understanding_status") ??
        readStringProperty(disclosure, "media_understanding_status") ??
        readStringProperty(disclosure, "mediaUnderstandingStatus") ??
        (mediaBoundaryRequired ? "not_understood_without_user_authorization" : null) ??
        previous.mediaUnderstandingStatus,
      mediaBoundaryRequired: previous.mediaBoundaryRequired || mediaBoundaryRequired,
    });
  }
  return [...sourcesByUrl.values()];
}

function readDesktopEvidenceSourceAccessStatus({ output, event, phase }) {
  const fullBodyChars =
    readFiniteNumber(output?.full_body_chars) ??
    readFiniteNumber(output?.fullBodyChars) ??
    readFiniteNumber(output?.evidence_disclosure?.full_body_chars) ??
    readFiniteNumber(output?.evidenceDisclosure?.fullBodyChars);
  const hasReadableText =
    readDesktopRuntimeToolEvidenceText(output).trim().length > 0 ||
    readDesktopBrowserSnapshotText(output).trim().length > 0;
  if (fullBodyChars === 0 && !hasReadableText) {
    return "failed";
  }
  const explicit =
    readStringProperty(output, "sourceAccessStatus") ??
    readStringProperty(output, "source_access_status") ??
    readStringProperty(output, "access_status") ??
    readStringProperty(event?.payload?.tool?.metadata?.toolResultMetadata, "sourceAccessStatus") ??
    readStringProperty(
      event?.payload?.tool?.metadata?.toolResultMetadata?.externalToolMetadata,
      "sourceAccessStatus",
    );
  if (explicit === "failed" || explicit === "blocked" || explicit === "error") {
    return "failed";
  }
  if (phase === "failed") {
    return "failed";
  }
  const status = readStringProperty(output, "status");
  return status === "error" || status === "blocked" || status === "failed"
    ? "failed"
    : "available";
}

function readDesktopEvidenceFailedReason({ output, event }) {
  const failures = Array.isArray(output.failures)
    ? output.failures
        .map((item) => String(item ?? "").trim())
        .filter((item) => item.length > 0)
    : [];
  return (
    failures[0] ??
    readStringProperty(output, "error") ??
    readStringProperty(output, "summary") ??
    readStringProperty(event?.payload?.tool?.metadata, "error") ??
    readStringProperty(event?.payload?.tool?.metadata?.toolResultMetadata, "error") ??
    readStringProperty(
      event?.payload?.tool?.metadata?.toolResultMetadata?.externalToolMetadata,
      "error",
    ) ??
    readStringProperty(event?.payload?.tool, "outputPreview")
  );
}

function readDesktopBrowserSnapshotText(output) {
  return [
    readStringProperty(output, "text"),
    readStringProperty(output, "snapshot_preview"),
    readStringProperty(output, "snapshotPreview"),
  ]
    .filter((value) => typeof value === "string" && value.length > 0)
    .join("\n");
}

function isDesktopMediaRichSocialUrl(value) {
  if (typeof value !== "string" || value.trim().length === 0) {
    return false;
  }
  try {
    const host = new URL(value).hostname.toLowerCase().replace(/^www\./u, "");
    return (
      host === "x.com" ||
      host === "twitter.com" ||
      host === "mobile.twitter.com" ||
      host.endsWith(".x.com") ||
      host.endsWith(".twitter.com") ||
      host === "weibo.com" ||
      host.endsWith(".weibo.com") ||
      host === "douyin.com" ||
      host.endsWith(".douyin.com") ||
      host === "tiktok.com" ||
      host.endsWith(".tiktok.com") ||
      host === "instagram.com" ||
      host.endsWith(".instagram.com") ||
      host === "youtube.com" ||
      host === "youtu.be" ||
      host.endsWith(".youtube.com") ||
      host === "bilibili.com" ||
      host.endsWith(".bilibili.com")
    );
  } catch {
    return false;
  }
}

function createDesktopUnverifiedMediaInventory({ sourceUrl, reason }) {
  return {
    schemaVersion: "director.desktop.media-inventory.v1",
    sourceUrl,
    assetCount: 0,
    imageCount: 0,
    videoCount: 0,
    audioCount: 0,
    posterCount: 0,
    blobCount: 0,
    unknownCount: 0,
    verified: false,
    verificationStatus: "not_verified",
    reason,
    assets: [],
  };
}

function createDesktopMediaEvidenceBoundaryAdmission({ mediaInventory, reason }) {
  const assetCount = readFiniteNumber(mediaInventory?.assetCount) ?? 0;
  return {
    status: "text_admissible_media_not_verified",
    reason,
    canAdmitTextEvidence: true,
    canAdmitMediaContent: false,
    requiredNextAction: "request_user_authorization",
    budget: {
      tokenLimit: 0,
      fileCountLimit: assetCount,
      videoMinuteLimit: 0,
      estimatedCostTier: "unknown",
    },
  };
}

function readDesktopRuntimeToolOutput(event) {
  const metadataOutput =
    event?.payload?.tool?.metadata?.toolResultMetadata?.externalToolMetadata?.toolOutput ??
    event?.payload?.tool?.metadata?.toolResultMetadata?.externalToolMetadata?.outputMetadata
      ?.toolOutput ??
    event?.payload?.tool?.metadata?.toolResultMetadata?.externalToolMetadata?.output ??
    event?.payload?.tool?.metadata?.toolResultMetadata?.toolOutput ??
    event?.payload?.tool?.metadata?.toolResultMetadata?.outputMetadata?.toolOutput ??
    event?.payload?.tool?.metadata?.toolResultMetadata?.output ??
    event?.payload?.tool?.output;
  if (metadataOutput !== undefined) {
    return metadataOutput;
  }
  const preview = event?.payload?.tool?.outputPreview;
  if (typeof preview !== "string") {
    return null;
  }
  return parseDesktopRuntimeToolObservation(preview);
}

function parseDesktopRuntimeToolObservation(preview) {
  const output = {};
  let currentBlock = null;
  const blockLines = [];
  const flushBlock = () => {
    if (currentBlock === null) {
      return;
    }
    const value = blockLines.join("\n").trim();
    if (value.length > 0) {
      output[currentBlock] = value;
    }
    currentBlock = null;
    blockLines.length = 0;
  };
  for (const line of preview.split(/\r?\n/u)) {
    const trimmed = line.trim();
    if (currentBlock !== null) {
      if (/^[a-z_][a-z0-9_]*\s*:/iu.test(trimmed)) {
        flushBlock();
      } else {
        blockLines.push(line);
        continue;
      }
    }
    const separator = line.indexOf(":");
    if (separator <= 0) {
      continue;
    }
    const key = line.slice(0, separator).trim();
    const value = line.slice(separator + 1).trim();
    if (key === "text" || key === "snapshot_preview") {
      currentBlock = key;
      if (value.length > 0) {
        blockLines.push(value);
      }
    } else if (key === "url" || key === "title" || key === "status" || key === "summary") {
      output[key] = value;
    } else if (key === "full_body_chars" || key === "preview_chars" || key === "element_count") {
      const numberValue = Number(value);
      if (Number.isFinite(numberValue)) {
        output[key] = numberValue;
      }
    } else if (key === "body_truncated_for_model") {
      output[key] = value === "true";
    } else if (key === "media_inventory") {
      output.media_inventory = readDesktopRuntimeToolEvidenceMediaInventoryFromPreview(line);
    }
  }
  flushBlock();
  return output;
}

function failDesktopConversationTask(store, { turnId, sessionKey, error }) {
  if (!store || typeof store.get !== "function" || typeof store.upsert !== "function") {
    return null;
  }
  const runtimeSessionKey = readNonEmptyString(sessionKey) ?? "desktop:workbench";
  const taskId = createDesktopConversationTaskId(turnId, runtimeSessionKey);
  const previous = store.get(taskId);
  const now = Date.now();
  const message = renderConversationRuntimeUserFacingFailureReply({
    error,
    surface: "desktop",
  }).text;
  return store.upsert({
    ...(previous ?? {}),
    id: taskId,
    turnId,
    sessionKey: runtimeSessionKey,
    status: "failed",
    progress: 100,
    provider: "conversation-runtime",
    model: previous?.model ?? "runtime",
    error: message,
    updatedAt: now,
    completedAt: now,
    events: [
      ...(previous?.events ?? []),
      createDesktopConversationTaskEvent(
        "conversation.failed",
        "普通对话失败",
        message,
        now,
        100,
      ),
    ],
  });
}

async function cancelDesktopConversationTaskByAction({
  store,
  runRegistry,
  action,
  reason,
  dataDir,
  browserToolService,
}) {
  if (!store || typeof store.get !== "function" || typeof store.list !== "function" || typeof store.upsert !== "function") {
    return { cancelled: 0, taskIds: [] };
  }
  const taskId = readNonEmptyString(action.taskId);
  const turnId = readNonEmptyString(action.turnId);
  const storeCandidates =
    taskId !== undefined
      ? [store.get(taskId)].filter(Boolean)
      : turnId !== undefined
        ? store.list().filter((task) => task.turnId === turnId)
        : [];
  const registryCandidates =
    taskId !== undefined
      ? [readDesktopConversationTaskFromRunRegistry(runRegistry, taskId)].filter(Boolean)
      : turnId !== undefined
        ? listDesktopConversationTasksFromRunRegistry(runRegistry, { turnId })
        : [];
  const candidatesById = new Map();
  for (const candidate of [...registryCandidates, ...storeCandidates]) {
    candidatesById.set(candidate.id, candidate);
  }
  const candidates = [...candidatesById.values()];
  const conversationTasks = candidates.filter(
    (task) => task?.id?.startsWith("conversation:") && task.status !== "cancelled",
  );
  const cancelledTaskIds = [];
  const stoppedRunIds = [];
  const cancelledSubagentRunIds = [];
  const subagentCancellationErrors = [];
  const browserCleanupResults = [];
  const now = Date.now();
  for (const task of conversationTasks) {
    const stopResult = stopDesktopConversationRunForTask({
      runRegistry,
      task,
      reason,
    });
    stoppedRunIds.push(...stopResult.turnRunIds);
    const cascadeResult = await cancelDesktopConversationSubagentRuns({
      dataDir,
      runRegistry,
      task,
      turnRunIds: stopResult.turnRunIds,
      reason,
    });
    cancelledSubagentRunIds.push(...cascadeResult.subagentRunIds);
    subagentCancellationErrors.push(...cascadeResult.errors);
    const browserCleanup = await cleanupDesktopConversationBrowserSession({
      browserToolService,
      action,
      task,
    });
    if (browserCleanup !== null) {
      browserCleanupResults.push(browserCleanup);
    }
    store.upsert({
      ...task,
      status: "cancelled",
      progress: 100,
      cancelReason: reason,
      error: reason,
      updatedAt: now,
      completedAt: now,
      events: dedupeConversationTaskEvents([
        ...(task.events ?? []),
        createDesktopConversationTaskEvent("conversation.cancelled", "普通对话已取消", reason, now, 100),
      ]),
    });
    cancelledTaskIds.push(task.id);
  }
  return {
    cancelled: cancelledTaskIds.length,
    taskIds: cancelledTaskIds,
    turnRunIds: stoppedRunIds,
    subagentRunIds: [...new Set(cancelledSubagentRunIds)],
    subagentCancellationErrors,
    browserCleanupResults,
  };
}

async function cleanupDesktopConversationBrowserSession({ browserToolService, action, task }) {
  if (!browserToolService || typeof browserToolService.cleanup !== "function") {
    return null;
  }
  const sessionKey =
    readNonEmptyString(action?.sessionKey) ??
    readNonEmptyString(task?.sessionKey) ??
    readNonEmptyString(task?.payload?.sessionKey) ??
    "desktop:workbench";
  try {
    return {
      sessionKey,
      result: await Promise.resolve(browserToolService.cleanup({ sessionKey })),
    };
  } catch (error) {
    return {
      sessionKey,
      result: {
        success: false,
        error: error instanceof Error ? error.message : String(error),
      },
    };
  }
}

function stopDesktopConversationRunForTask({ runRegistry, task, reason }) {
  if (!runRegistry || typeof runRegistry.stop !== "function" || typeof runRegistry.list !== "function") {
    return { stopped: 0, turnRunIds: [] };
  }
  const runIds = resolveDesktopConversationTurnRunIds(runRegistry, task);
  const stoppedRunIds = [];
  for (const turnRunId of runIds) {
    try {
      runRegistry.stop(turnRunId, {
        requestedBy: "user",
        reason: reason ?? "desktop conversation task cancelled",
      });
      stoppedRunIds.push(turnRunId);
    } catch (_error) {
      // A completed run may already have finalized between the UI cancel click and this handler.
    }
  }
  return { stopped: stoppedRunIds.length, turnRunIds: stoppedRunIds };
}

async function cancelDesktopConversationSubagentRuns({
  dataDir,
  runRegistry,
  task,
  turnRunIds,
  reason,
}) {
  if (typeof dataDir !== "string" || dataDir.trim().length === 0) {
    return { cancelled: 0, subagentRunIds: [], errors: [] };
  }
  if (!runRegistry || typeof runRegistry.read !== "function") {
    return { cancelled: 0, subagentRunIds: [], errors: [] };
  }
  const subagentRunIds = [];
  const runIds = [];
  for (const turnRunId of turnRunIds) {
    const record = runRegistry.read(turnRunId);
    if (record === undefined) {
      continue;
    }
    subagentRunIds.push(...(record.activeSubagentRunIds ?? []));
    const activeRunId = readNonEmptyString(record.metadata?.activeRunId);
    if (activeRunId !== undefined) {
      runIds.push(activeRunId);
    }
  }
  const taskActiveRunId = readNonEmptyString(task?.activeRunId);
  if (taskActiveRunId !== undefined) {
    runIds.push(taskActiveRunId);
  }
  const uniqueSubagentRunIds = [...new Set(subagentRunIds)];
  const uniqueRunIds = [...new Set(runIds)];
  if (uniqueSubagentRunIds.length === 0 || uniqueRunIds.length === 0) {
    return { cancelled: 0, subagentRunIds: [], errors: [] };
  }
  const cancelled = [];
  const errors = [];
  for (const runId of uniqueRunIds) {
    await withDesktopRunTaskPlane(
      dataDir,
      runId,
      { createIfMissing: false },
      async (taskPlane) => {
        if (taskPlane === null) {
          return null;
        }
        const state = await taskPlane.status();
        const delegationsById = new Map(
          (Array.isArray(state?.delegation) ? state.delegation : []).map((record) => [
            record.id,
            record,
          ]),
        );
        for (const subagentRunId of uniqueSubagentRunIds) {
          const record = delegationsById.get(subagentRunId);
          if (record === undefined || isTerminalDesktopDelegationStatus(record.status)) {
            continue;
          }
          try {
            await taskPlane.setDelegationStatus({
              id: subagentRunId,
              status: "cancelled",
              reason: reason ?? "parent conversation run stopped",
              error: reason ?? "parent conversation run stopped",
            });
            cancelled.push(subagentRunId);
          } catch (error) {
            errors.push({
              runId,
              subagentRunId,
              message: error instanceof Error ? error.message : String(error),
            });
          }
        }
        return null;
      },
    );
  }
  return {
    cancelled: cancelled.length,
    subagentRunIds: [...new Set(cancelled)],
    errors,
  };
}

function isTerminalDesktopDelegationStatus(status) {
  return status === "completed" || status === "failed" || status === "cancelled";
}

function resolveDesktopConversationTurnRunIds(runRegistry, task) {
  const explicitTurnRunId = readNonEmptyString(task.turnRunId);
  if (explicitTurnRunId !== undefined) {
    return [explicitTurnRunId];
  }
  const turnId = readNonEmptyString(task.turnId);
  if (turnId === undefined || typeof runRegistry.list !== "function") {
    return [];
  }
  const sessionKey = readDesktopConversationTaskSessionKey(task);
  const activeRuns = runRegistry
    .list(sessionKey === undefined ? {} : { sessionKey })
    .filter((run) => run.turnId === turnId && isActiveConversationRunRegistryStatus(run.status))
    .map((run) => run.turnRunId);
  if (activeRuns.length > 0) {
    return [...new Set(activeRuns)];
  }
  return [`${sessionKey ?? "desktop:workbench"}:${turnId}:run`];
}

function readDesktopConversationTaskSessionKey(task) {
  return (
    readNonEmptyString(task?.sessionKey) ??
    readNonEmptyString(task?.payload?.sessionKey) ??
    readNonEmptyString(task?.summary?.sessionKey)
  );
}

function readDesktopConversationRuntimeResultSessionKey(runtimeResult) {
  const eventSessionKey = (Array.isArray(runtimeResult?.events) ? runtimeResult.events : [])
    .map((event) => readNonEmptyString(event?.sessionKey))
    .find((value) => value !== undefined);
  if (eventSessionKey !== undefined) {
    return eventSessionKey;
  }
  const runtimeEventSessionKey = (
    Array.isArray(runtimeResult?.runtimeEventsV1) ? runtimeResult.runtimeEventsV1 : []
  )
    .map((event) => readNonEmptyString(event?.conversationId))
    .find((value) => value !== undefined);
  if (runtimeEventSessionKey !== undefined) {
    return runtimeEventSessionKey;
  }
  const turnRunId = readNonEmptyString(runtimeResult?.turnRunId);
  const match = turnRunId?.match(/^(desktop:workbench(?::[A-Za-z0-9_-]+)?):/u);
  return match?.[1];
}

function isActiveConversationRunRegistryStatus(status) {
  return isActiveConversationTurnRunStatus(status);
}

async function cancelDesktopLiveRunnerSessionsByAction({ liveRunner, action, reason }) {
  const store = liveRunner?.store;
  if (!store || typeof store.listSessions !== "function") {
    return { cancelled: 0, driverCancelled: 0, sessionIds: [], errors: [] };
  }
  const sessionId = readNonEmptyString(action.sessionId);
  const runId = readNonEmptyString(action.runId);
  const turnId = readNonEmptyString(action.turnId);
  if (sessionId === undefined && runId === undefined && turnId === undefined) {
    return { cancelled: 0, driverCancelled: 0, sessionIds: [], errors: [] };
  }
  const sessions = await store.listSessions({
    activeOnly: true,
    ...(runId === undefined ? {} : { runId }),
  });
  const matchingSessions = sessions.filter((session) => {
    if (sessionId !== undefined) {
      return session.sessionId === sessionId;
    }
    if (turnId !== undefined) {
      return isLiveRunSessionForDesktopTurn(session, turnId);
    }
    return runId !== undefined && session.runId === runId;
  });
  if (matchingSessions.length === 0) {
    if (sessionId !== undefined) {
      liveRunner?.abortSession?.(sessionId, reason);
    }
    if (turnId !== undefined) {
      liveRunner?.abortTurn?.(turnId, reason);
    }
  }
  return cancelDesktopLiveRunnerSessionList({
    liveRunner,
    sessions: matchingSessions,
    reason,
    source: "desktop.liveRunner.cancel",
    turnId,
  });
}

async function cancelDesktopComposerLiveRunnerSessions({ liveRunner, turnId, reason }) {
  const store = liveRunner?.store;
  if (!store || typeof store.listSessions !== "function" || turnId.length === 0) {
    return { cancelled: 0, driverCancelled: 0, sessionIds: [], errors: [] };
  }

  const sessions = await store.listSessions({ activeOnly: true });
  const matchingSessions = sessions.filter((session) => isLiveRunSessionForDesktopTurn(session, turnId));
  if (matchingSessions.length === 0) {
    liveRunner?.abortTurn?.(turnId, reason);
  }
  return cancelDesktopLiveRunnerSessionList({
    liveRunner,
    sessions: matchingSessions,
    reason,
    source: "desktop.composer.cancel",
    turnId,
  });
}

async function cancelDesktopLiveRunnerSessionList({ liveRunner, sessions, reason, source, turnId }) {
  const store = liveRunner?.store;
  let cancelled = 0;
  let driverCancelled = 0;
  const sessionIds = [];
  const errors = [];
  for (const session of sessions) {
    try {
      const requested = requestLiveRunCancel(session, {
        reason,
        metadata: {
          source,
          ...(typeof turnId === "string" ? { turnId } : {}),
        },
      });
      await store.appendTransition(requested);
      const token = createLiveRunCancelToken(requested.session, {
        reason,
        metadata: {
          source,
          ...(typeof turnId === "string" ? { turnId } : {}),
        },
      });
      const driver = liveRunner?.driverRegistry?.resolve?.({
        providerId: requested.session.providerId,
        capabilityId: requested.session.capabilityId,
      });
      let driverResult;
      if (
        requested.session.providerTask !== undefined &&
        driver &&
        typeof driver.cancel === "function"
      ) {
        driverResult = await driver.cancel({
          request: createDesktopLiveRunCancelRequest(requested.session, turnId),
          session: requested.session,
          cancelToken: token,
        });
        if (driverResult?.cancelled === true) {
          driverCancelled += 1;
        }
      }
      const final = cancelLiveRunSession(requested.session, {
        reason,
        metadata: {
          source,
          ...(typeof turnId === "string" ? { turnId } : {}),
          driverId: driver?.id ?? null,
          driverCancelled: driverResult?.cancelled === true,
          ...(driverResult?.metadata === undefined ? {} : { driverMetadata: driverResult.metadata }),
        },
      });
      await store.appendTransition(final);
      liveRunner?.abortSession?.(final.session.sessionId, reason);
      cancelled += 1;
      sessionIds.push(final.session.sessionId);
    } catch (error) {
      errors.push({
        sessionId: session.sessionId,
        message: error instanceof Error ? error.message : String(error),
      });
    }
  }
  return { cancelled, driverCancelled, sessionIds, errors };
}

function createDesktopMemefastLiveRunner({ workspaceRoot, apiProviderFetch }) {
  const workspace = resolveDirectorWorkspace({ root: workspaceRoot });
  const providersRoot = join(workspace.root, "providers");
  const sessionDbPath = join(workspace.runtime, "sessions", "live-runner.sqlite");
  const sessionStore = new SessionStore({ dbPath: sessionDbPath });
  const store = createSessionStoreLiveRunStore({
    sessionStore,
    journalSessionId: "desktop-live-runner",
  });
  const activeControllers = new Map();
  const activeControllerAliases = new Map();
  const driverRegistry = createLiveRunDriverRegistry([
    createMemefastLiveRunProviderDriver(providersRoot, {
      timeoutMs: DESKTOP_REAL_TEXT_TIMEOUT_MS,
      maxTextAttempts: DESKTOP_REAL_TEXT_MAX_ATTEMPTS,
      ...(apiProviderFetch === undefined ? {} : { fetchImpl: apiProviderFetch }),
    }),
  ]);
  return {
    store,
    driverRegistry,
    createAbortSignal(sessionId, request) {
      const controller = new AbortController();
      activeControllers.set(sessionId, controller);
      for (const alias of createDesktopLiveRunnerAbortAliases(sessionId, request)) {
        activeControllerAliases.set(alias, sessionId);
      }
      return controller.signal;
    },
    abortSession(sessionId, reason) {
      const resolvedSessionId = activeControllers.has(sessionId)
        ? sessionId
        : activeControllerAliases.get(sessionId);
      const controller =
        resolvedSessionId === undefined ? undefined : activeControllers.get(resolvedSessionId);
      if (controller === undefined || controller.signal.aborted) {
        return false;
      }
      controller.abort(new Error(reason ?? "desktop live runner cancelled"));
      return true;
    },
    abortTurn(turnId, reason) {
      const sessionId = activeControllerAliases.get(`turn:${turnId}`);
      return sessionId === undefined ? false : this.abortSession(sessionId, reason);
    },
    clearAbortSignal(sessionId) {
      activeControllers.delete(sessionId);
      for (const [alias, mappedSessionId] of activeControllerAliases.entries()) {
        if (mappedSessionId === sessionId) {
          activeControllerAliases.delete(alias);
        }
      }
    },
    close() {
      for (const controller of activeControllers.values()) {
        if (!controller.signal.aborted) {
          controller.abort(new Error("desktop live runner closing"));
        }
      }
      activeControllers.clear();
      sessionStore.close();
    },
  };
}

function readNonEmptyString(value) {
  return typeof value === "string" && value.trim().length > 0 ? value.trim() : undefined;
}

function readDesktopOptionalNumber(value) {
  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

function readFirstString(values) {
  for (const value of values) {
    if (typeof value === "string" && value.trim().length > 0) {
      return value.trim();
    }
  }
  return undefined;
}

function hasOwn(object, key) {
  return Object.prototype.hasOwnProperty.call(object, key);
}
